window.PROTOCOLS=[{"id": "http", "name": "HTTP", "full": "Hypertext Transfer Protocol", "layer": 7, "cat": "app", "title": "An HTTP request, in motion.", "port": "80", "transport": "TCP", "lede": "Follow one plain HTTP page load, from the address bar to the finished page. You see DNS, the TCP handshake and the request and response.", "overview": "<p>HTTP is the language of the web. A client sends a <b>request<\/b> with a method, a path and headers. A server sends a <b>response<\/b> with a status code, headers and a body. HTTP/1.1 is text, so you can read it.<\/p>\n<p>Plain HTTP is <b>not encrypted<\/b>. Anyone on the path can read and change it. Real sites use HTTPS, which is the same HTTP inside TLS.<\/p>\n<div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Part<\/th><th>Example<\/th><\/tr><\/thead><tbody><tr><td>Request line<\/td><td><code>GET /index.html HTTP/1.1<\/code><\/td><\/tr><tr><td>Header<\/td><td><code>Host: www.example.com<\/code><\/td><\/tr><tr><td>Status line<\/td><td><code>HTTP/1.1 200 OK<\/code><\/td><\/tr><\/tbody><\/table><\/div>", "nodes": {"client": {"label": "Client", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 2}, "router": {"label": "Home router", "sub": "192.168.1.1", "icon": "router", "x": 2, "y": 2}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 4, "y": 2}, "dns": {"label": "DNS resolver", "sub": "198.51.100.53", "icon": "dns", "x": 5, "y": 0}, "web": {"label": "Web server", "sub": "203.0.113.10", "icon": "web", "x": 6, "y": 3}}, "links": [["client", "router"], ["router", "net"], ["net", "dns"], ["net", "web"]], "steps": [{"t": "Choose a resource", "tag": "setup", "d": "<p>You type <code>http://www.example.com/<\/code> and press Enter. The browser prepares a <code>GET<\/code> request. It still needs the server&#x27;s IP address.<\/p>", "f": [["URL", "http://www.example.com/"], ["Method", "GET"], ["Next hop", "Router 192.168.1.1"]], "p": [], "on": [], "good": "", "bad": []}, {"t": "Resolve the name", "tag": "dns", "d": "<p>The browser asks a DNS resolver for the address of www.example.com. The resolver answers with an A record. The browser caches the answer for its TTL.<\/p>", "f": [["Query", "www.example.com A"], ["Answer", "203.0.113.10"], ["Transport", "UDP 53"]], "p": [{"f": "client", "t": "dns", "m": "DNS query A www.example.com", "k": "req", "fields": [["Type", "A"], ["Class", "IN"], ["ID", "0x1a2b"]], "raw": null, "hex": null}, {"f": "dns", "t": "client", "m": "A 203.0.113.10 TTL 300", "k": "res", "fields": [["Answer", "203.0.113.10"], ["TTL", "300 s"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Open a TCP connection", "tag": "handshake", "d": "<p>The client and the server do the TCP three way handshake on port 80. SYN, SYN-ACK, ACK. Now they have a reliable byte stream.<\/p>", "f": [["Destination", "203.0.113.10:80"], ["Source port", "51514"], ["Round trips", "1"]], "p": [{"f": "client", "t": "web", "m": "SYN seq=1000", "k": "ctl", "fields": [["Flags", "SYN"], ["Seq", "1000"]], "raw": null, "hex": null}, {"f": "web", "t": "client", "m": "SYN-ACK seq=5000 ack=1001", "k": "ctl", "fields": [["Flags", "SYN, ACK"], ["Seq", "5000"], ["Ack", "1001"]], "raw": null, "hex": null}, {"f": "client", "t": "web", "m": "ACK ack=5001", "k": "ctl", "fields": [["Flags", "ACK"], ["Ack", "5001"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Send the request, get the response", "tag": "exchange", "d": "<p>The client sends the request as text. The server finds the file and answers <code>200 OK<\/code> with HTML in the body.<\/p>", "f": [["Request", "GET / HTTP/1.1"], ["Status", "200 OK"], ["Content-Type", "text/html"]], "p": [{"f": "client", "t": "web", "m": "GET / HTTP/1.1", "k": "req", "fields": [], "raw": "GET / HTTP/1.1\r\nHost: www.example.com\r\nUser-Agent: Mozilla/5.0\r\nAccept: text/html\r\n\r\n", "hex": null}, {"f": "web", "t": "client", "m": "HTTP/1.1 200 OK", "k": "res", "fields": [["Status", "200"], ["Length", "1256 bytes"]], "raw": "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Length: 1256\r\nCache-Control: max-age=600\r\n\r\n<!doctype html><html>...", "hex": null}], "on": [], "good": "Plain HTTP is readable by every router on the path. That is why browsers mark http pages as not secure.", "bad": []}, {"t": "Display the page", "tag": "render", "d": "<p>The browser reads the HTML, finds images, CSS and scripts, and requests them on the same connection. HTTP/1.1 keeps the connection open by default for reuse.<\/p>", "f": [["Connection", "kept alive"], ["Extra requests", "CSS, JS, images"]], "p": [{"f": "client", "t": "web", "m": "GET /style.css", "k": "req", "fields": [], "raw": "GET /style.css HTTP/1.1\r\nHost: www.example.com\r\nConnection: keep-alive\r\n\r\n", "hex": null}, {"f": "web", "t": "client", "m": "200 OK text/css", "k": "res", "fields": [], "raw": "HTTP/1.1 200 OK\r\nContent-Type: text/css\r\nContent-Length: 5120\r\nCache-Control: max-age=86400\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What does the server send first in a response?", "opts": ["The body", "The status line, such as HTTP/1.1 200 OK", "A DNS answer"], "a": 1, "why": "The status line comes first, then headers, then an empty line, then the body.", "type": "mcq"}, {"type": "fill", "q": "Plain HTTP uses TCP port ____ by default.", "a": ["80"], "why": "HTTPS uses 443."}, {"q": "Why is plain HTTP unsafe on public Wi-Fi?", "opts": ["It is slow", "Anyone on the path can read and change it, because it is not encrypted", "It uses UDP"], "a": 1, "why": "HTTPS adds TLS encryption and server authentication.", "type": "mcq"}], "refs": ["MDN. <a href=\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Overview\" target=\"_blank\" rel=\"noopener\">An overview of HTTP<\/a>.", "IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc9112\" target=\"_blank\" rel=\"noopener\">RFC 9112, HTTP/1.1<\/a>."]}, {"id": "https", "name": "HTTPS", "full": "HTTP Secure", "layer": 7, "cat": "security", "title": "HTTPS, the same request inside a locked tunnel.", "port": "443", "transport": "TCP", "lede": "HTTPS is HTTP sent inside a TLS connection. Watch the extra handshake that proves the server&#x27;s identity and agrees on secret keys, then the encrypted request.", "overview": "<p>HTTPS protects three things. <b>Confidentiality<\/b>, nobody on the path can read the data. <b>Integrity<\/b>, nobody can change it without being detected. <b>Authentication<\/b>, the certificate proves you talk to the real site.<\/p>\n<p>The cost is one extra round trip with TLS 1.3, or two with TLS 1.2. Connection reuse and TLS session resumption hide most of that cost.<\/p>", "nodes": {"client": {"label": "Browser", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 2}, "router": {"label": "Home router", "sub": "192.168.1.1", "icon": "router", "x": 2, "y": 2}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 4, "y": 2}, "web": {"label": "shop.example", "sub": "203.0.113.20", "icon": "web", "x": 6, "y": 2}, "ca": {"label": "Certificate authority", "sub": "trusted root", "icon": "shield", "x": 6, "y": 0}}, "links": [["client", "router"], ["router", "net"], ["net", "web"], ["net", "ca"]], "steps": [{"t": "TCP handshake on port 443", "tag": "handshake", "d": "<p>The browser opens a TCP connection to port 443. SYN, SYN-ACK, ACK, as for plain HTTP.<\/p>", "f": [], "p": [{"f": "client", "t": "web", "m": "SYN", "k": "ctl", "fields": [["Src port", "51514"], ["Dst port", "443"], ["Flags", "SYN"], ["Seq", "2000"], ["Window", "64240"]], "raw": null, "hex": null}, {"f": "web", "t": "client", "m": "SYN-ACK", "k": "ctl", "fields": [["Src port", "443"], ["Dst port", "51514"], ["Flags", "SYN ACK"], ["Seq", "9000"], ["Ack", "2001"], ["Window", "65160"]], "raw": null, "hex": null}, {"f": "client", "t": "web", "m": "ACK", "k": "ctl", "fields": [["Src port", "51514"], ["Dst port", "443"], ["Flags", "ACK"], ["Seq", "2001"], ["Ack", "9001"], ["Window", "502"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "ClientHello", "tag": "tls", "d": "<p>The browser sends a TLS 1.3 ClientHello. It lists cipher suites, a key share for key agreement, the server name in SNI, and <code>h2<\/code> and <code>http/1.1<\/code> in ALPN.<\/p>", "f": [["TLS version", "1.3"], ["SNI", "shop.example"], ["ALPN", "h2, http/1.1"], ["Key share", "x25519"]], "p": [{"f": "client", "t": "web", "m": "ClientHello", "k": "sec", "fields": [["SNI", "shop.example"], ["Key share", "x25519 public key"], ["Cipher suites", "TLS_AES_128_GCM_SHA256 and more"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The server proves who it is", "tag": "tls", "d": "<p>The server answers with ServerHello and its own key share. Both sides now compute the same secret keys. The rest of the handshake is already encrypted. The server sends its certificate, a signature that proves it owns the private key, and Finished.<\/p>", "f": [["Certificate", "CN shop.example"], ["Issuer", "Example CA"], ["Signed with", "server private key"]], "p": [{"f": "web", "t": "client", "m": "ServerHello + key share", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "122"], ["Handshake type", "0x02 ServerHello"], ["Cipher suite", "0x1301 TLS_AES_128_GCM_SHA256"], ["Key share", "X25519"]], "raw": null, "hex": null}, {"f": "web", "t": "client", "m": "Certificate, CertificateVerify, Finished", "k": "sec", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "2890"], ["Payload", "Certificate, CertificateVerify and Finished, already encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Check the certificate", "tag": "verify", "d": "<p>The browser checks the certificate chain up to a root CA it already trusts, checks the name matches shop.example, and checks the dates. This basic check needs no call to the CA.<\/p>", "f": [["Chain", "leaf, intermediate, root"], ["Name match", "yes"], ["Valid dates", "yes"]], "p": [], "on": [], "good": "The browser already ships a list of trusted root certificates. That is why it can trust a site it has never seen.", "bad": []}, {"t": "Encrypted HTTP", "tag": "exchange", "d": "<p>The browser sends Finished, then the HTTP request, both encrypted. Anyone on the path sees only the server IP, the SNI name and the size and timing of encrypted records.<\/p>", "f": [], "p": [{"f": "client", "t": "web", "m": "Finished + GET / (encrypted)", "k": "sec", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "310"], ["Payload", "Finished, then GET / HTTP/1.1, encrypted"]], "raw": null, "hex": null}, {"f": "web", "t": "client", "m": "200 OK (encrypted)", "k": "res", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "1290"], ["Payload", "HTTP/1.1 200 OK and the page, encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What does the certificate prove?", "opts": ["That the site is fast", "That the server holds the private key for this domain name, vouched for by a trusted CA", "That the site has no bugs"], "a": 1, "why": "The CA signs the certificate, and the server proves it has the matching private key.", "type": "mcq"}, {"type": "fill", "q": "HTTPS uses TCP port ____ by default.", "a": ["443"], "why": "HTTP uses 80, HTTPS uses 443."}], "refs": ["Cloudflare. <a href=\"https://www.cloudflare.com/learning/ssl/what-happens-in-a-tls-handshake/\" target=\"_blank\" rel=\"noopener\">What happens in a TLS handshake?<\/a>", "IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc8446\" target=\"_blank\" rel=\"noopener\">RFC 8446, TLS 1.3<\/a>."]}, {"id": "http2", "name": "HTTP/2", "full": "Binary frames, many streams", "layer": 7, "cat": "app", "title": "HTTP/2, many requests on one connection.", "port": "443", "transport": "TCP with TLS", "lede": "HTTP/2 keeps the meaning of HTTP but sends it as binary frames. Many requests share one connection at the same time, so a page loads with fewer connections and less waiting.", "overview": "<p>HTTP/1.1 sends one request at a time per connection, so browsers open several connections. HTTP/2 <b>multiplexes<\/b> many <b>streams<\/b> on one connection. Each request and response is a stream with an id. Headers are compressed with <b>HPACK<\/b>.<\/p>\n<p>One weakness remains. HTTP/2 runs on TCP, so one lost TCP packet pauses all streams until it is sent again. HTTP/3 over QUIC fixes this.<\/p>", "nodes": {"client": {"label": "Browser", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 3, "y": 1}, "web": {"label": "Web server", "sub": "203.0.113.30", "icon": "web", "x": 6, "y": 1}}, "links": [["client", "net"], ["net", "web"]], "steps": [{"t": "Agree on h2 during TLS", "tag": "tls", "d": "<p>In the TLS handshake the browser offers <code>h2<\/code> with ALPN. The server picks <code>h2<\/code>. No extra round trip is needed to choose HTTP/2.<\/p>", "f": [["ALPN offer", "h2, http/1.1"], ["ALPN chosen", "h2"]], "p": [{"f": "client", "t": "web", "m": "ClientHello ALPN h2", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "512"], ["Handshake type", "0x01 ClientHello"], ["ALPN", "h2, http/1.1"]], "raw": null, "hex": null}, {"f": "web", "t": "client", "m": "ServerHello ALPN h2", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "122"], ["Handshake type", "0x02 ServerHello"], ["ALPN chosen", "h2"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Connection preface and SETTINGS", "tag": "setup", "d": "<p>The client sends a fixed preface string, then a SETTINGS frame. The server sends its own SETTINGS. Each side acknowledges the settings of the other.<\/p>", "f": [["Preface", "PRI * HTTP/2.0"], ["Example setting", "MAX_CONCURRENT_STREAMS 100"]], "p": [{"f": "client", "t": "web", "m": "Preface + SETTINGS", "k": "ctl", "fields": [], "raw": "PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n", "hex": null}, {"f": "web", "t": "client", "m": "SETTINGS", "k": "ctl", "fields": [["Length", "18"], ["Frame type", "0x4 SETTINGS"], ["Frame flags", "0x0"], ["Stream identifier", "0"], ["Contains", "MAX_CONCURRENT_STREAMS 100"]], "raw": null, "hex": null}, {"f": "client", "t": "web", "m": "SETTINGS ACK", "k": "ctl", "fields": [["Length", "0"], ["Frame type", "0x4 SETTINGS"], ["Frame flags", "0x1 ACK"], ["Stream identifier", "0"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Three requests at once", "tag": "streams", "d": "<p>The browser sends three HEADERS frames on streams 1, 3 and 5, for the page, the CSS and a script. It does not wait between them.<\/p>", "f": [["Streams", "1, 3, 5"], ["Header compression", "HPACK"]], "p": [{"f": "client", "t": "web", "m": "HEADERS stream 1 GET /", "k": "req", "fields": [["Length", "32"], ["Frame type", "0x1 HEADERS"], ["Frame flags", "0x5 END_STREAM, END_HEADERS"], ["Stream identifier", "1"], ["Contains", ":method GET, :path /, HPACK"]], "raw": null, "hex": null}, {"f": "client", "t": "web", "m": "HEADERS stream 3 GET /app.css", "k": "req", "fields": [["Length", "14"], ["Frame type", "0x1 HEADERS"], ["Frame flags", "0x5 END_STREAM, END_HEADERS"], ["Stream identifier", "3"], ["Contains", ":path /app.css, HPACK"]], "raw": null, "hex": null}, {"f": "client", "t": "web", "m": "HEADERS stream 5 GET /app.js", "k": "req", "fields": [["Length", "14"], ["Frame type", "0x1 HEADERS"], ["Frame flags", "0x5 END_STREAM, END_HEADERS"], ["Stream identifier", "5"], ["Contains", ":path /app.js, HPACK"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Responses arrive interleaved", "tag": "streams", "d": "<p>The server sends DATA frames for all three streams, mixed together. The browser puts each frame back into its stream by the stream id.<\/p>", "f": [], "p": [{"f": "web", "t": "client", "m": "HEADERS + DATA stream 3", "k": "res", "fields": [["Length", "4096"], ["Frame type", "0x0 DATA"], ["Frame flags", "0x0"], ["Stream identifier", "3"], ["Contains", "CSS bytes after a HEADERS frame"]], "raw": null, "hex": null}, {"f": "web", "t": "client", "m": "DATA stream 1", "k": "res", "fields": [["Length", "8192"], ["Frame type", "0x0 DATA"], ["Frame flags", "0x0"], ["Stream identifier", "1"], ["Contains", "HTML bytes"]], "raw": null, "hex": null}, {"f": "web", "t": "client", "m": "DATA stream 5, END_STREAM", "k": "res", "fields": [["Length", "2048"], ["Frame type", "0x0 DATA"], ["Frame flags", "0x1 END_STREAM"], ["Stream identifier", "5"], ["Contains", "last JavaScript bytes"]], "raw": null, "hex": null}], "on": [], "good": "Streams that the client starts use odd numbers. Streams that the server starts use even numbers.", "bad": []}], "quiz": [{"q": "What is the main gain of HTTP/2 over HTTP/1.1?", "opts": ["It is text based", "Many requests and responses share one connection at the same time", "It removes TLS"], "a": 1, "why": "Multiplexing removes the need for many parallel connections.", "type": "mcq"}, {"type": "fill", "q": "HTTP/2 compresses headers with a scheme called ____.", "a": ["HPACK"], "why": "HTTP/3 uses QPACK."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc9113\" target=\"_blank\" rel=\"noopener\">RFC 9113, HTTP/2<\/a>.", "web.dev. <a href=\"https://web.dev/articles/performance-http2\" target=\"_blank\" rel=\"noopener\">Introduction to HTTP/2<\/a>."]}, {"id": "websocket", "name": "WebSocket", "full": "Two-way web messaging", "layer": 7, "cat": "app", "title": "A WebSocket, from upgrade to close.", "port": "80 or 443", "transport": "TCP", "lede": "A WebSocket starts as a normal HTTP request, then turns the same TCP connection into a two way channel. Both sides can send messages at any time.", "overview": "<p>WebSocket is defined in RFC 6455. The client sends an HTTP GET with <code>Upgrade: websocket<\/code>. The server answers <code>101 Switching Protocols<\/code>. After that, data travels in <b>frames<\/b>. Frames from the client are <b>masked<\/b> with a random key, to protect old proxies from confusion. Ping and pong frames keep the connection alive.<\/p>\n<p>Use <code>wss://<\/code> for WebSocket over TLS.<\/p>", "nodes": {"client": {"label": "Browser", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "lb": {"label": "Load balancer", "sub": "203.0.113.40", "icon": "proxy", "x": 3, "y": 1}, "srv": {"label": "Chat server", "sub": "10.0.1.5", "icon": "server", "x": 6, "y": 1}}, "links": [["client", "lb"], ["lb", "srv"]], "steps": [{"t": "Upgrade request", "tag": "handshake", "d": "<p>After TCP and TLS, the browser sends a GET with the upgrade headers and a random base64 key.<\/p>", "f": [], "p": [{"f": "client", "t": "srv", "m": "GET /chat Upgrade websocket", "k": "req", "fields": [], "raw": "GET /chat HTTP/1.1\r\nHost: chat.example\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "101 Switching Protocols", "tag": "handshake", "d": "<p>The server adds a fixed GUID to the key, hashes it with SHA-1 and sends the base64 result as <code>Sec-WebSocket-Accept<\/code>. This proves the server understood the WebSocket request.<\/p>", "f": [["Status", "101"], ["Accept", "s3pPLMBiTxaQ9kYGzzhZRbK+xOo="]], "p": [{"f": "srv", "t": "client", "m": "101 Switching Protocols", "k": "res", "fields": [], "raw": "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: s3pPLMBiTxaQ9kYGzzhZRbK+xOo=\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Messages both ways", "tag": "data", "d": "<p>The client sends a masked text frame. The server pushes a message at any time, with no request.<\/p>", "f": [["Opcode", "0x1 text"], ["Client mask", "yes"], ["Server mask", "no"]], "p": [{"f": "client", "t": "srv", "m": "text frame hello", "k": "data", "fields": [["FIN", "1"], ["Opcode", "1 text"], ["Mask", "1"], ["Payload", "hello"]], "raw": null, "hex": null}, {"f": "srv", "t": "client", "m": "text frame new message", "k": "data", "fields": [["FIN", "1"], ["Opcode", "0x1 text"], ["Mask", "0 server frames are not masked"], ["Payload length", "27"], ["Payload", "{\"type\":\"msg\",\"text\":\"hi\"}"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Keep alive", "tag": "control", "d": "<p>The server sends a ping frame. The client answers with pong. Proxies do not close the idle connection.<\/p>", "f": [], "p": [{"f": "srv", "t": "client", "m": "ping", "k": "ctl", "fields": [["FIN", "1"], ["Opcode", "0x9 ping"], ["Mask", "0"], ["Payload length", "0"], ["Payload", "empty"]], "raw": null, "hex": null}, {"f": "client", "t": "srv", "m": "pong", "k": "ctl", "fields": [["FIN", "1"], ["Opcode", "0xA pong"], ["Mask", "1 client frames are masked"], ["Payload length", "0"], ["Payload", "empty"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Close", "tag": "close", "d": "<p>One side sends a close frame with a status code, such as 1000 for normal closure. The other side answers with a close frame. Then TCP closes.<\/p>", "f": [], "p": [{"f": "client", "t": "srv", "m": "close 1000", "k": "ctl", "fields": [["FIN", "1"], ["Opcode", "0x8 close"], ["Mask", "1 client frames are masked"], ["Payload length", "2"], ["Payload", "status code 1000 normal closure"]], "raw": null, "hex": null}, {"f": "srv", "t": "client", "m": "close 1000", "k": "ctl", "fields": [["FIN", "1"], ["Opcode", "0x8 close"], ["Mask", "0"], ["Payload length", "2"], ["Payload", "status code 1000 normal closure"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "The server answers a WebSocket upgrade with status ____.", "a": ["101"], "why": "101 Switching Protocols."}, {"q": "Which frames must be masked?", "opts": ["Frames from the server", "Frames from the client", "No frames"], "a": 1, "why": "RFC 6455 requires clients to mask every frame they send.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc6455\" target=\"_blank\" rel=\"noopener\">RFC 6455, the WebSocket protocol<\/a>.", "MDN. <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/WebSockets_API/Writing_WebSocket_servers\" target=\"_blank\" rel=\"noopener\">Writing WebSocket servers<\/a>."]}, {"id": "grpc", "name": "gRPC", "full": "Remote calls over HTTP/2", "layer": 7, "cat": "app", "title": "One gRPC call, frame by frame.", "port": "any, often 443 or 50051", "transport": "HTTP/2", "lede": "gRPC turns a function call into HTTP/2 frames. Watch the headers, the length prefixed protobuf message and the trailers that carry the result status.", "overview": "<p>A gRPC call is an HTTP/2 POST. The path names the service and method, such as <code>/shop.Inventory/Reserve<\/code>. The body holds messages. Each message has a 1 byte compression flag, a 4 byte length, then the protobuf bytes. The result arrives in <b>trailers<\/b> with <code>grpc-status<\/code>. 0 means OK.<\/p>", "nodes": {"cli": {"label": "Checkout service", "sub": "10.0.1.7", "icon": "server", "x": 0, "y": 1}, "srv": {"label": "Inventory service", "sub": "10.0.2.9", "icon": "server", "x": 6, "y": 1}}, "links": [["cli", "srv"]], "steps": [{"t": "Request headers", "tag": "call", "d": "<p>The client opens a new HTTP/2 stream and sends HEADERS with the method path, the content type and a deadline in <code>grpc-timeout<\/code>.<\/p>", "f": [[":method", "POST"], [":path", "/shop.Inventory/Reserve"], ["content-type", "application/grpc"], ["grpc-timeout", "200m"]], "p": [{"f": "cli", "t": "srv", "m": "HEADERS POST /shop.Inventory/Reserve", "k": "req", "fields": [["Length", "46"], ["Frame type", "0x1 HEADERS"], ["Frame flags", "0x4 END_HEADERS"], ["Stream identifier", "1"], ["Contains", ":path /shop.Inventory/Reserve, content-type application/grpc"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The message", "tag": "call", "d": "<p>A DATA frame carries the request. First a compression flag 0, then the length, then the protobuf bytes for sku and qty.<\/p>", "f": [["Compressed", "0"], ["Length", "12 bytes"], ["Message", "sku TSHIRT-M, qty 2"]], "p": [{"f": "cli", "t": "srv", "m": "DATA length-prefixed ReserveRequest", "k": "data", "fields": [["Compressed flag", "0"], ["Message length", "12"], ["Message", "ReserveRequest sku TSHIRT-M qty 2, protobuf"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Reply and status", "tag": "reply", "d": "<p>The server sends response HEADERS, a DATA frame with ReserveReply, and trailing HEADERS with <code>grpc-status 0<\/code>. The client code gets a normal return value.<\/p>", "f": [["grpc-status", "0 OK"], ["Reply", "ok true, left 41"]], "p": [{"f": "srv", "t": "cli", "m": "HEADERS :status 200", "k": "res", "fields": [["Length", "14"], ["Frame type", "0x1 HEADERS"], ["Frame flags", "0x4 END_HEADERS"], ["Stream identifier", "1"], ["Contains", ":status 200, content-type application/grpc"]], "raw": null, "hex": null}, {"f": "srv", "t": "cli", "m": "DATA ReserveReply", "k": "res", "fields": [["Compressed flag", "0"], ["Message length", "6"], ["Message", "ReserveReply ok true left 41, protobuf"]], "raw": null, "hex": null}, {"f": "srv", "t": "cli", "m": "Trailers grpc-status 0", "k": "res", "fields": [["Length", "20"], ["Frame type", "0x1 HEADERS"], ["Frame flags", "0x5 END_STREAM, END_HEADERS"], ["Stream identifier", "1"], ["Contains", "trailers grpc-status 0, grpc-message empty"]], "raw": null, "hex": null}], "on": [], "good": "An HTTP status of 200 does not mean the call worked. Always read grpc-status in the trailers.", "bad": []}], "quiz": [{"type": "fill", "q": "gRPC reports the result of a call in the ____, with grpc-status.", "a": ["trailers", "trailer", "trailing headers"], "why": "The status comes after the messages, so streaming calls can report a final result."}, {"q": "Which HTTP version does gRPC use by default?", "opts": ["HTTP/1.0", "HTTP/2", "SMTP"], "a": 1, "why": "gRPC relies on HTTP/2 streams and trailers.", "type": "mcq"}], "refs": ["gRPC. <a href=\"https://github.com/grpc/grpc/blob/master/doc/PROTOCOL-HTTP2.md\" target=\"_blank\" rel=\"noopener\">gRPC over HTTP/2 protocol<\/a>."]}, {"id": "http-proxy", "name": "HTTP Proxy", "full": "Forward proxy and CONNECT", "layer": 7, "cat": "security", "title": "A forward proxy and the CONNECT tunnel.", "port": "often 3128 or 8080", "transport": "TCP", "lede": "Companies often send all web traffic through a forward proxy. For plain HTTP the proxy reads the request. For HTTPS the client asks the proxy to open a blind tunnel with CONNECT.", "overview": "<p>A <b>forward proxy<\/b> acts for clients. You configure clients to use it. It can filter, log and cache. For HTTPS, the client sends <code>CONNECT host:443<\/code>. The proxy opens a TCP connection to the host and then copies bytes both ways. It cannot read the encrypted traffic, unless the company installs its own root certificate on every machine to inspect TLS.<\/p>\n<p>A proxy can ask for credentials with <code>407 Proxy Authentication Required<\/code>.<\/p>", "nodes": {"client": {"label": "Employee laptop", "sub": "10.10.0.21", "icon": "laptop", "x": 0, "y": 1}, "proxy": {"label": "Forward proxy", "sub": "10.10.0.2", "icon": "proxy", "x": 3, "y": 1}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 5, "y": 1}, "web": {"label": "news.example", "sub": "203.0.113.60", "icon": "web", "x": 7, "y": 1}}, "links": [["client", "proxy"], ["proxy", "net"], ["net", "web"]], "steps": [{"t": "Plain HTTP through the proxy", "tag": "http", "d": "<p>The client sends the full URL in the request line to the proxy. The proxy checks its rules, forwards the request and returns the answer.<\/p>", "f": [], "p": [{"f": "client", "t": "proxy", "m": "GET http://news.example/ HTTP/1.1", "k": "req", "fields": [], "raw": "GET http://news.example/ HTTP/1.1\r\nHost: news.example\r\n\r\n", "hex": null}, {"f": "proxy", "t": "web", "m": "GET / HTTP/1.1", "k": "req", "fields": [], "raw": "GET / HTTP/1.1\r\nHost: news.example\r\nVia: 1.1 proxy\r\nX-Forwarded-For: 10.10.0.21\r\n\r\n", "hex": null}, {"f": "web", "t": "proxy", "m": "200 OK", "k": "res", "fields": [], "raw": "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: 18200\r\n\r\n", "hex": null}, {"f": "proxy", "t": "client", "m": "200 OK", "k": "res", "fields": [], "raw": "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nVia: 1.1 proxy\r\nContent-Length: 18200\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Ask for a tunnel", "tag": "connect", "d": "<p>For HTTPS, the client sends CONNECT with the host and port.<\/p>", "f": [], "p": [{"f": "client", "t": "proxy", "m": "CONNECT news.example:443", "k": "req", "fields": [], "raw": "CONNECT news.example:443 HTTP/1.1\r\nHost: news.example:443\r\nProxy-Authorization: Basic ZW1wOnB3\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Tunnel open", "tag": "connect", "d": "<p>The proxy opens TCP to the host and answers 200. From now on it only copies bytes.<\/p>", "f": [], "p": [{"f": "proxy", "t": "web", "m": "TCP SYN to 443", "k": "ctl", "fields": [["Src port", "40210"], ["Dst port", "443"], ["Flags", "SYN"], ["Seq", "7000"], ["Window", "64240"]], "raw": null, "hex": null}, {"f": "proxy", "t": "client", "m": "HTTP/1.1 200 Connection established", "k": "res", "fields": [], "raw": "HTTP/1.1 200 Connection established\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "TLS through the tunnel", "tag": "tls", "d": "<p>The client does a normal TLS handshake with the real server through the tunnel. The proxy sees encrypted bytes only, plus the host name from CONNECT.<\/p>", "f": [], "p": [{"f": "client", "t": "web", "m": "ClientHello (through tunnel)", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "512"], ["Handshake type", "0x01 ClientHello"], ["Server name", "news.example"], ["Note", "the proxy only copies these bytes"]], "raw": null, "hex": null}, {"f": "web", "t": "client", "m": "ServerHello, Certificate (through tunnel)", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "122"], ["Handshake type", "0x02 ServerHello"], ["Note", "the proxy cannot read what follows"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "To ask a proxy for an HTTPS tunnel, the client uses the method ____.", "a": ["CONNECT"], "why": "CONNECT host:443 opens a byte tunnel."}, {"q": "Can a normal forward proxy read HTTPS traffic in a CONNECT tunnel?", "opts": ["Yes, always", "No, it sees only encrypted bytes and the target host"], "a": 1, "why": "Only TLS inspection with a company installed root certificate changes that.", "type": "mcq"}], "refs": ["MDN. <a href=\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Methods/CONNECT\" target=\"_blank\" rel=\"noopener\">CONNECT method<\/a>.", "MDN. <a href=\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Proxy_servers_and_tunneling\" target=\"_blank\" rel=\"noopener\">Proxy servers and tunneling<\/a>."]}, {"id": "socks5", "name": "SOCKS5", "full": "Socket Secure proxy", "layer": 5, "cat": "security", "title": "SOCKS5, a general purpose proxy.", "port": "1080", "transport": "TCP", "lede": "SOCKS5 can proxy any TCP connection, and UDP too, not only web traffic. Watch the greeting, the login and the CONNECT request.", "overview": "<p>SOCKS5 is defined in RFC 1928. It works below HTTP, so it can carry SSH, mail or any TCP protocol. It does not encrypt anything by itself. SSH can act as a SOCKS proxy with <code>ssh -D 1080 host<\/code>.<\/p>", "nodes": {"client": {"label": "App", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "socks": {"label": "SOCKS5 proxy", "sub": "198.51.100.8", "icon": "proxy", "x": 3, "y": 1}, "srv": {"label": "Target server", "sub": "203.0.113.70", "icon": "server", "x": 6, "y": 1}}, "links": [["client", "socks"], ["socks", "srv"]], "steps": [{"t": "Greeting", "tag": "auth", "d": "<p>The client says version 5 and lists the login methods it supports. Here, no login, and username with password.<\/p>", "f": [["VER", "5"], ["Methods", "0x00 none, 0x02 user and password"]], "p": [{"f": "client", "t": "socks", "m": "VER 5, methods 00 02", "k": "ctl", "fields": [["VER", "5"], ["NMETHODS", "2"], ["Methods", "0x00 none, 0x02 user and password"]], "raw": null, "hex": "05 02 00 02"}, {"f": "socks", "t": "client", "m": "VER 5, method 02", "k": "ctl", "fields": [["VER", "5"], ["METHOD", "0x02 user and password"]], "raw": null, "hex": "05 02"}], "on": [], "good": "", "bad": []}, {"t": "Login", "tag": "auth", "d": "<p>The proxy chose username and password, from RFC 1929. The client sends them. They are not encrypted, so use SOCKS inside a trusted network or a tunnel.<\/p>", "f": [], "p": [{"f": "client", "t": "socks", "m": "user alice, password ****", "k": "sec", "fields": [["VER", "0x01 auth version"], ["ULEN", "5"], ["UNAME", "alice"], ["PLEN", "8"], ["PASSWD", "sent in plain text inside the SOCKS link"]], "raw": null, "hex": null}, {"f": "socks", "t": "client", "m": "status 0 success", "k": "sec", "fields": [["VER", "0x01"], ["STATUS", "0x00 success"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "CONNECT request", "tag": "connect", "d": "<p>The client asks the proxy to connect to a host name and port. The proxy can resolve the name itself, which hides DNS lookups from the local network.<\/p>", "f": [["CMD", "1 CONNECT"], ["ATYP", "3 domain name"], ["DST", "mail.example:993"]], "p": [{"f": "client", "t": "socks", "m": "CONNECT mail.example:993", "k": "req", "fields": [["VER", "5"], ["CMD", "1 CONNECT"], ["RSV", "0"], ["ATYP", "3 domain name"], ["DST ADDR", "mail.example"], ["DST port", "993"]], "raw": null, "hex": null}, {"f": "socks", "t": "srv", "m": "TCP connect", "k": "ctl", "fields": [["Src port", "50600"], ["Dst port", "993"], ["Flags", "SYN"], ["Seq", "3300"], ["Window", "64240"]], "raw": null, "hex": null}, {"f": "socks", "t": "client", "m": "REP 0 succeeded", "k": "res", "fields": [["VER", "5"], ["REP", "0 succeeded"], ["RSV", "0"], ["ATYP", "1 IPv4"], ["BND ADDR", "198.51.100.8"], ["BND port", "50600"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Relay", "tag": "data", "d": "<p>The proxy now copies bytes in both directions. The app talks to the target as if directly.<\/p>", "f": [], "p": [{"f": "client", "t": "srv", "m": "app data (relayed)", "k": "data", "fields": [["Payload", "TLS bytes for IMAP, copied as is"], ["Length", "517"]], "raw": null, "hex": null}, {"f": "srv", "t": "client", "m": "app data (relayed)", "k": "data", "fields": [["Payload", "TLS bytes from the mail server, copied as is"], ["Length", "1440"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "The usual SOCKS port is ____.", "a": ["1080"], "why": "SOCKS servers usually listen on 1080."}, {"q": "Does SOCKS5 encrypt traffic?", "opts": ["Yes", "No, it only relays. Use TLS or SSH for encryption"], "a": 1, "why": "SOCKS5 has no encryption of its own.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc1928\" target=\"_blank\" rel=\"noopener\">RFC 1928, SOCKS protocol version 5<\/a>."]}, {"id": "reverse-proxy", "name": "Reverse Proxy", "full": "TLS offloading and routing", "layer": 7, "cat": "app", "title": "A reverse proxy in front of your servers.", "port": "443", "transport": "TCP", "lede": "A reverse proxy takes requests for your servers. It ends TLS, picks a backend, adds headers and can cache. Users never talk to the backends directly.", "overview": "<p>A reverse proxy acts for <b>servers<\/b>. A forward proxy acts for <b>clients<\/b>. Nginx, HAProxy, Envoy and cloud load balancers are common reverse proxies. See concepts lesson 1.10 for load balancing.<\/p>", "nodes": {"user": {"label": "User", "sub": "198.51.100.23", "icon": "laptop", "x": 0, "y": 1}, "rp": {"label": "Reverse proxy", "sub": "203.0.113.80", "icon": "proxy", "x": 3, "y": 1}, "cache": {"label": "Cache", "sub": "in memory", "icon": "db", "x": 3, "y": 3}, "a": {"label": "App server A", "sub": "10.0.1.11", "icon": "server", "x": 6, "y": 0}, "b": {"label": "App server B", "sub": "10.0.1.12", "icon": "server", "x": 6, "y": 2}}, "links": [["user", "rp"], ["rp", "a"], ["rp", "b"], ["rp", "cache"]], "steps": [{"t": "TLS ends at the proxy", "tag": "tls", "d": "<p>The user connects to the proxy with HTTPS. The proxy holds the certificate and decrypts the request. This is <b>TLS offloading<\/b>.<\/p>", "f": [], "p": [{"f": "user", "t": "rp", "m": "ClientHello", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "512"], ["Handshake type", "0x01 ClientHello"], ["Server name", "shop.example"]], "raw": null, "hex": null}, {"f": "rp", "t": "user", "m": "ServerHello, Certificate", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "122"], ["Handshake type", "0x02 ServerHello"], ["Certificate", "CN shop.example, held by the proxy"]], "raw": null, "hex": null}, {"f": "user", "t": "rp", "m": "GET /products (encrypted)", "k": "req", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "220"], ["Payload", "GET /products HTTP/1.1, encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Pick a backend", "tag": "route", "d": "<p>The proxy chooses app server A by its rule, here least connections. It adds <code>X-Forwarded-For<\/code> with the user IP, because A sees only the address of the proxy.<\/p>", "f": [["Rule", "least connections"], ["X-Forwarded-For", "198.51.100.23"], ["X-Forwarded-Proto", "https"]], "p": [{"f": "rp", "t": "a", "m": "GET /products + X-Forwarded-For", "k": "req", "fields": [], "raw": "GET /products HTTP/1.1\r\nHost: shop.example\r\nX-Forwarded-For: 198.51.100.23\r\nX-Forwarded-Proto: https\r\n\r\n", "hex": null}, {"f": "a", "t": "rp", "m": "200 OK, Cache-Control max-age=60", "k": "res", "fields": [], "raw": "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nCache-Control: max-age=60\r\nContent-Length: 4096\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Cache and answer", "tag": "cache", "d": "<p>The proxy can keep the response for 60 seconds. It sends the response to the user, encrypted again.<\/p>", "f": [], "p": [{"f": "rp", "t": "cache", "m": "store /products", "k": "data", "fields": [["Cache key", "GET shop.example/products"], ["TTL", "60"], ["Size", "4096"]], "raw": null, "hex": null}, {"f": "rp", "t": "user", "m": "200 OK (encrypted)", "k": "res", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "4180"], ["Payload", "HTTP/1.1 200 OK and the JSON body, encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The next user gets the cached copy", "tag": "cache", "d": "<p>A second user asks for the same page within 60 seconds. The proxy answers from its cache. The app servers do no work.<\/p>", "f": [], "p": [{"f": "user", "t": "rp", "m": "GET /products", "k": "req", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "220"], ["Payload", "GET /products HTTP/1.1, encrypted"]], "raw": null, "hex": null}, {"f": "cache", "t": "rp", "m": "hit /products", "k": "data", "fields": [["Cache key", "GET shop.example/products"], ["Age", "12"], ["Result", "hit"]], "raw": null, "hex": null}, {"f": "rp", "t": "user", "m": "200 OK from cache", "k": "res", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "4180"], ["Payload", "HTTP/1.1 200 OK, Age 12, served from cache"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "Why does the backend need X-Forwarded-For?", "opts": ["To speed up TLS", "Because it only sees the IP of the proxy, not the IP of the user", "To cache"], "a": 1, "why": "The header carries the original client IP.", "type": "mcq"}, {"type": "fill", "q": "Decrypting HTTPS at the proxy so backends get plain HTTP is called TLS ____.", "a": ["offloading", "termination", "offload"], "why": "It is also called TLS termination."}], "refs": ["NGINX. <a href=\"https://docs.nginx.com/nginx/admin-guide/web-server/reverse-proxy/\" target=\"_blank\" rel=\"noopener\">Reverse proxy guide<\/a>.", "Cloudflare. <a href=\"https://www.cloudflare.com/learning/cdn/glossary/reverse-proxy/\" target=\"_blank\" rel=\"noopener\">What is a reverse proxy?<\/a>"]}, {"id": "webrtc", "name": "WebRTC", "full": "Browser video calls", "layer": 7, "cat": "app", "title": "WebRTC, a video call straight between two browsers.", "port": "dynamic, STUN 3478", "transport": "UDP mostly", "lede": "WebRTC sends audio and video directly between browsers. A server only helps them find each other. Watch signaling, NAT discovery with STUN, the TURN fallback and the encrypted media.", "overview": "<p>WebRTC does not define <b>signaling<\/b>. Apps exchange <b>SDP<\/b> offers and answers through their own server, often over WebSocket. <b>ICE<\/b> collects possible addresses, called candidates. <b>STUN<\/b> tells each browser its public address behind NAT. If a direct path fails, a <b>TURN<\/b> server relays the media. Media is always encrypted with <b>DTLS<\/b> and <b>SRTP<\/b>.<\/p>", "nodes": {"a": {"label": "Asha browser", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "natA": {"label": "Asha router", "sub": "NAT", "icon": "router", "x": 2, "y": 1}, "sig": {"label": "Signaling server", "sub": "WebSocket", "icon": "server", "x": 4, "y": 0}, "stun": {"label": "STUN and TURN", "sub": "203.0.113.5", "icon": "server", "x": 4, "y": 3}, "natB": {"label": "Ben router", "sub": "NAT", "icon": "router", "x": 6, "y": 1}, "b": {"label": "Ben browser", "sub": "10.0.0.22", "icon": "laptop", "x": 8, "y": 1}}, "links": [["a", "natA"], ["natA", "sig"], ["natA", "stun"], ["natA", "natB"], ["natB", "sig"], ["natB", "stun"], ["natB", "b"]], "steps": [{"t": "Offer through signaling", "tag": "signaling", "d": "<p>Asha starts a call. Her browser makes an SDP offer that lists codecs and a DTLS fingerprint, and sends it to Ben through the app signaling server.<\/p>", "f": [], "p": [{"f": "a", "t": "sig", "m": "SDP offer", "k": "req", "fields": [["type", "offer"], ["sdp", "v=0, m=video 9 UDP/TLS/RTP/SAVPF 96, a=fingerprint sha-256 ..."], ["ice ufrag", "F7gI"]], "raw": null, "hex": null}, {"f": "sig", "t": "b", "m": "SDP offer", "k": "req", "fields": [["type", "offer"], ["note", "the signaling server forwards it unchanged"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Answer", "tag": "signaling", "d": "<p>Ben accepts. His browser sends an SDP answer back the same way.<\/p>", "f": [], "p": [{"f": "b", "t": "sig", "m": "SDP answer", "k": "res", "fields": [["type", "answer"], ["sdp", "v=0, m=video 9 UDP/TLS/RTP/SAVPF 96, a=setup active"], ["ice ufrag", "Kq2b"]], "raw": null, "hex": null}, {"f": "sig", "t": "a", "m": "SDP answer", "k": "res", "fields": [["type", "answer"], ["note", "forwarded to A"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Find public addresses with STUN", "tag": "ice", "d": "<p>Each browser asks the STUN server &quot;what address do you see me from?&quot;. The answer is its public IP and port after NAT. These become candidates, sent to the other side through signaling.<\/p>", "f": [], "p": [{"f": "a", "t": "stun", "m": "STUN Binding request", "k": "ctl", "fields": [["Message type", "0x0001 Binding Request"], ["Message length", "0"], ["Magic cookie", "0x2112A442"], ["Transaction ID", "0xa1b2c3d4e5f60718293a4b5c"], ["Attribute", "none"]], "raw": null, "hex": null}, {"f": "stun", "t": "a", "m": "you are 198.51.100.7:54321", "k": "ctl", "fields": [["Message type", "0x0101 Binding Success"], ["Message length", "12"], ["Magic cookie", "0x2112A442"], ["Transaction ID", "0xa1b2c3d4e5f60718293a4b5c"], ["Attribute", "XOR-MAPPED-ADDRESS 198.51.100.7:54321"]], "raw": null, "hex": null}, {"f": "b", "t": "stun", "m": "STUN Binding request", "k": "ctl", "fields": [["Message type", "0x0001 Binding Request"], ["Message length", "0"], ["Magic cookie", "0x2112A442"], ["Transaction ID", "0xa1b2c3d4e5f60718293a4b5c"], ["Attribute", "none"]], "raw": null, "hex": null}, {"f": "stun", "t": "b", "m": "you are 203.0.113.99:40112", "k": "ctl", "fields": [["Message type", "0x0101 Binding Success"], ["Message length", "12"], ["Magic cookie", "0x2112A442"], ["Transaction ID", "0xa1b2c3d4e5f60718293a4b5c"], ["Attribute", "XOR-MAPPED-ADDRESS 203.0.113.99:40112"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Connectivity checks", "tag": "ice", "d": "<p>ICE tries candidate pairs with STUN checks directly between the browsers. A direct pair works, so the call goes peer to peer. If none worked, both would use the TURN relay.<\/p>", "f": [], "p": [{"f": "a", "t": "b", "m": "STUN check", "k": "ctl", "fields": [["Message type", "0x0001 Binding Request"], ["Message length", "64"], ["Magic cookie", "0x2112A442"], ["Transaction ID", "0xa1b2c3d4e5f60718293a4b5c"], ["Attribute", "USERNAME Kq2b:F7gI, PRIORITY, MESSAGE-INTEGRITY"]], "raw": null, "hex": null}, {"f": "b", "t": "a", "m": "STUN check response", "k": "ctl", "fields": [["Message type", "0x0101 Binding Success"], ["Message length", "44"], ["Magic cookie", "0x2112A442"], ["Transaction ID", "0xa1b2c3d4e5f60718293a4b5c"], ["Attribute", "XOR-MAPPED-ADDRESS, MESSAGE-INTEGRITY"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Encrypted media", "tag": "media", "d": "<p>A DTLS handshake checks the fingerprints from the SDP and makes keys. Then audio and video flow as SRTP packets over UDP, directly between the two browsers.<\/p>", "f": [], "p": [{"f": "a", "t": "b", "m": "DTLS handshake", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0xfefd DTLS 1.2"], ["Epoch", "0"], ["Length", "190"], ["Note", "fingerprint must match the SDP"]], "raw": null, "hex": null}, {"f": "a", "t": "b", "m": "SRTP video", "k": "data", "fields": [["Version", "2"], ["Payload type", "96 VP8"], ["Sequence number", "4012"], ["Timestamp", "1795200"], ["SSRC", "0x5a3c11e2"], ["Payload", "encrypted with SRTP"]], "raw": null, "hex": null}, {"f": "b", "t": "a", "m": "SRTP video", "k": "data", "fields": [["Version", "2"], ["Payload type", "96 VP8"], ["Sequence number", "877"], ["Timestamp", "902400"], ["SSRC", "0x77a10b3f"], ["Payload", "encrypted with SRTP"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What does a TURN server do?", "opts": ["Encrypts the call", "Relays media when a direct path between peers is not possible", "Stores contacts"], "a": 1, "why": "STUN helps find a direct path. TURN is the fallback relay.", "type": "mcq"}, {"type": "fill", "q": "WebRTC describes codecs and settings in offers and answers written in ____.", "a": ["SDP", "session description protocol"], "why": "Session Description Protocol."}], "refs": ["MDN. <a href=\"https://developer.mozilla.org/en-US/docs/Web/API/WebRTC_API/Connectivity\" target=\"_blank\" rel=\"noopener\">WebRTC connectivity<\/a>.", "IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc8445\" target=\"_blank\" rel=\"noopener\">RFC 8445, ICE<\/a>."]}, {"id": "sip", "name": "SIP", "full": "Internet phone calls", "layer": 7, "cat": "app", "title": "SIP, setting up a phone call over the internet.", "port": "5060, 5061 for TLS", "transport": "UDP or TCP or TLS", "lede": "SIP is the signaling protocol for most office phones and phone networks. It looks a lot like HTTP. Watch registration, an INVITE that rings a phone, and the media that flows directly.", "overview": "<p>Phones first <b>REGISTER<\/b> with a registrar, so the system knows where to reach them. A call starts with <b>INVITE<\/b>, which carries an SDP offer. Responses use numbers like HTTP, such as <b>100 Trying<\/b>, <b>180 Ringing<\/b> and <b>200 OK<\/b>. The caller confirms with <b>ACK<\/b>. Voice then flows as <b>RTP<\/b>, usually directly between phones. <b>BYE<\/b> ends the call.<\/p>", "nodes": {"alice": {"label": "Alice phone", "sub": "ext 201", "icon": "phone", "x": 0, "y": 1}, "proxy": {"label": "SIP proxy", "sub": "pbx.example", "icon": "server", "x": 4, "y": 0}, "bob": {"label": "Bob phone", "sub": "ext 305", "icon": "phone", "x": 8, "y": 1}}, "links": [["alice", "proxy"], ["proxy", "bob"], ["alice", "bob"]], "steps": [{"t": "Register", "tag": "register", "d": "<p>Bob phone registers its current address with the proxy. The proxy asks for a digest login first.<\/p>", "f": [], "p": [{"f": "bob", "t": "proxy", "m": "REGISTER sip:305@pbx.example", "k": "req", "fields": [], "raw": "REGISTER sip:pbx.example SIP/2.0\r\nVia: SIP/2.0/UDP 192.168.1.50:5060\r\nFrom: <sip:305@pbx.example>\r\nTo: <sip:305@pbx.example>\r\nCSeq: 1 REGISTER\r\nContact: <sip:305@192.168.1.50>\r\nExpires: 3600\r\n\r\n", "hex": null}, {"f": "proxy", "t": "bob", "m": "401 Unauthorized (challenge)", "k": "ctl", "fields": [], "raw": "SIP/2.0 401 Unauthorized\r\nWWW-Authenticate: Digest realm=\"pbx.example\", nonce=\"7c1f2a\"\r\nCSeq: 1 REGISTER\r\n\r\n", "hex": null}, {"f": "bob", "t": "proxy", "m": "REGISTER with digest", "k": "req", "fields": [], "raw": "REGISTER sip:pbx.example SIP/2.0\r\nCSeq: 2 REGISTER\r\nAuthorization: Digest username=\"305\", nonce=\"7c1f2a\", response=\"9b2e...\"\r\n\r\n", "hex": null}, {"f": "proxy", "t": "bob", "m": "200 OK", "k": "res", "fields": [], "raw": "SIP/2.0 200 OK\r\nCSeq: 2 REGISTER\r\nExpires: 3600\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "INVITE", "tag": "call", "d": "<p>Alice dials 305. Her phone sends INVITE with an SDP offer to the proxy, which forwards it to Bob.<\/p>", "f": [], "p": [{"f": "alice", "t": "proxy", "m": "INVITE sip:305 + SDP", "k": "req", "fields": [], "raw": "INVITE sip:305@pbx.example SIP/2.0\r\nVia: SIP/2.0/UDP 192.168.1.40:5060\r\nFrom: <sip:201@pbx.example>\r\nTo: <sip:305@pbx.example>\r\nCall-ID: a84b4c76e66710\r\nCSeq: 1 INVITE\r\nContent-Type: application/sdp\r\n\r\n", "hex": null}, {"f": "proxy", "t": "alice", "m": "100 Trying", "k": "ctl", "fields": [], "raw": "SIP/2.0 100 Trying\r\nCSeq: 1 INVITE\r\n\r\n", "hex": null}, {"f": "proxy", "t": "bob", "m": "INVITE + SDP", "k": "req", "fields": [], "raw": "INVITE sip:305@192.168.1.50 SIP/2.0\r\nVia: SIP/2.0/UDP pbx.example:5060\r\nContent-Type: application/sdp\r\n\r\nm=audio 49170 RTP/AVP 0\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Ringing and answer", "tag": "call", "d": "<p>Bob phone rings and sends 180 Ringing. Bob picks up. His phone sends 200 OK with its SDP answer.<\/p>", "f": [], "p": [{"f": "bob", "t": "proxy", "m": "180 Ringing", "k": "res", "fields": [], "raw": "SIP/2.0 180 Ringing\r\nCSeq: 1 INVITE\r\n\r\n", "hex": null}, {"f": "proxy", "t": "alice", "m": "180 Ringing", "k": "res", "fields": [], "raw": "SIP/2.0 180 Ringing\r\nCSeq: 1 INVITE\r\n\r\n", "hex": null}, {"f": "bob", "t": "proxy", "m": "200 OK + SDP", "k": "res", "fields": [], "raw": "SIP/2.0 200 OK\r\nCSeq: 1 INVITE\r\nContent-Type: application/sdp\r\n\r\nm=audio 3456 RTP/AVP 0\r\n", "hex": null}, {"f": "proxy", "t": "alice", "m": "200 OK + SDP", "k": "res", "fields": [], "raw": "SIP/2.0 200 OK\r\nCSeq: 1 INVITE\r\nContent-Type: application/sdp\r\n\r\nm=audio 3456 RTP/AVP 0\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "ACK and voice", "tag": "media", "d": "<p>Alice sends ACK. Voice now flows as RTP packets directly between the two phones, using the addresses from the SDP.<\/p>", "f": [], "p": [{"f": "alice", "t": "bob", "m": "ACK", "k": "ctl", "fields": [], "raw": "ACK sip:305@192.168.1.50 SIP/2.0\r\nCSeq: 1 ACK\r\n\r\n", "hex": null}, {"f": "alice", "t": "bob", "m": "RTP voice", "k": "data", "fields": [["Version", "2"], ["Payload type", "0 PCMU"], ["Sequence number", "1"], ["Timestamp", "160"], ["SSRC", "0x1a2b3c4d"], ["Payload", "20 ms of voice, 160 bytes"]], "raw": null, "hex": null}, {"f": "bob", "t": "alice", "m": "RTP voice", "k": "data", "fields": [["Version", "2"], ["Payload type", "0 PCMU"], ["Sequence number", "1"], ["Timestamp", "160"], ["SSRC", "0x9e8d7c6b"], ["Payload", "20 ms of voice, 160 bytes"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Hang up", "tag": "end", "d": "<p>Bob hangs up and sends BYE. Alice answers 200 OK.<\/p>", "f": [], "p": [{"f": "bob", "t": "alice", "m": "BYE", "k": "ctl", "fields": [], "raw": "BYE sip:201@192.168.1.40 SIP/2.0\r\nCSeq: 2 BYE\r\n\r\n", "hex": null}, {"f": "alice", "t": "bob", "m": "200 OK", "k": "res", "fields": [], "raw": "SIP/2.0 200 OK\r\nCSeq: 2 BYE\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "The SIP request that starts a call is ____.", "a": ["INVITE"], "why": "The response sequence is 100, 180, 200, then the caller sends ACK."}, {"q": "How does voice travel once the call is set up?", "opts": ["Inside SIP messages", "As RTP, usually directly between the phones", "By email"], "a": 1, "why": "SIP only sets up and ends the call.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc3261\" target=\"_blank\" rel=\"noopener\">RFC 3261, SIP<\/a>."]}, {"id": "rtsp", "name": "RTSP", "full": "IP camera streams", "layer": 7, "cat": "app", "title": "RTSP, watching an IP camera.", "port": "554", "transport": "TCP for control, RTP for media", "lede": "Security cameras and video recorders often use RTSP. It is like a remote control for a stream. Describe, set up, play and stop.", "overview": "<p>RTSP looks like HTTP. <b>DESCRIBE<\/b> gets an SDP that lists the tracks. <b>SETUP<\/b> chooses how media travels, RTP over UDP ports or interleaved in the same TCP connection. <b>PLAY<\/b> starts the stream and <b>TEARDOWN<\/b> stops it. A <b>Session<\/b> header ties the requests together.<\/p>\n<div class=\"plain warn\"><span class=\"k\">Careful<\/span><p>Many cameras ship with default passwords and expose RTSP to the internet. Change the password and keep cameras on a private network.<\/p><\/div>", "nodes": {"nvr": {"label": "Video recorder", "sub": "192.168.10.5", "icon": "server", "x": 0, "y": 1}, "cam": {"label": "IP camera", "sub": "192.168.10.80", "icon": "camera", "x": 6, "y": 1}}, "links": [["nvr", "cam"]], "steps": [{"t": "DESCRIBE", "tag": "control", "d": "<p>The recorder asks what the stream contains. The camera answers with SDP, one H.264 video track and one audio track. It may first ask for a login with 401.<\/p>", "f": [], "p": [{"f": "nvr", "t": "cam", "m": "DESCRIBE rtsp://192.168.10.80/stream1", "k": "req", "fields": [], "raw": "DESCRIBE rtsp://192.168.10.80/stream1 RTSP/1.0\r\nCSeq: 2\r\nAccept: application/sdp\r\n\r\n", "hex": null}, {"f": "cam", "t": "nvr", "m": "200 OK + SDP", "k": "res", "fields": [], "raw": "RTSP/1.0 200 OK\r\nCSeq: 2\r\nContent-Type: application/sdp\r\n\r\nm=video 0 RTP/AVP 96\r\na=rtpmap:96 H264/90000\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "SETUP", "tag": "control", "d": "<p>The recorder asks for RTP over UDP on client ports 5000 and 5001. The camera answers with a Session id.<\/p>", "f": [["Transport", "RTP/AVP;unicast;client_port=5000-5001"], ["Session", "12345678"]], "p": [{"f": "nvr", "t": "cam", "m": "SETUP track1 client_port=5000-5001", "k": "req", "fields": [], "raw": "SETUP rtsp://192.168.10.80/stream1/track1 RTSP/1.0\r\nCSeq: 3\r\nTransport: RTP/AVP;unicast;client_port=5000-5001\r\n\r\n", "hex": null}, {"f": "cam", "t": "nvr", "m": "200 OK Session 12345678", "k": "res", "fields": [], "raw": "RTSP/1.0 200 OK\r\nCSeq: 3\r\nSession: 12345678\r\nTransport: RTP/AVP;unicast;client_port=5000-5001;server_port=6970-6971\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "PLAY", "tag": "control", "d": "<p>The recorder sends PLAY. The camera starts sending video.<\/p>", "f": [], "p": [{"f": "nvr", "t": "cam", "m": "PLAY Session 12345678", "k": "req", "fields": [], "raw": "PLAY rtsp://192.168.10.80/stream1 RTSP/1.0\r\nCSeq: 4\r\nSession: 12345678\r\n\r\n", "hex": null}, {"f": "cam", "t": "nvr", "m": "200 OK", "k": "res", "fields": [], "raw": "RTSP/1.0 200 OK\r\nCSeq: 4\r\nSession: 12345678\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "RTP media and RTCP reports", "tag": "media", "d": "<p>Video arrives in RTP packets with sequence numbers and timestamps. RTCP reports give quality feedback, such as lost packets.<\/p>", "f": [], "p": [{"f": "cam", "t": "nvr", "m": "RTP H.264 video", "k": "data", "fields": [["Version", "2"], ["Payload type", "96 H264"], ["Sequence number", "301"], ["Timestamp", "3003000"], ["SSRC", "0x2f1e0d0c"], ["Payload", "part of one video frame"]], "raw": null, "hex": null}, {"f": "nvr", "t": "cam", "m": "RTCP receiver report", "k": "ctl", "fields": [["Version", "2"], ["Packet type", "201 receiver report"], ["SSRC", "0x00c0ffee"], ["Fraction lost", "0"], ["Jitter", "12"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "TEARDOWN", "tag": "control", "d": "<p>The recorder stops the session.<\/p>", "f": [], "p": [{"f": "nvr", "t": "cam", "m": "TEARDOWN", "k": "req", "fields": [], "raw": "TEARDOWN rtsp://192.168.10.80/stream1 RTSP/1.0\r\nCSeq: 5\r\nSession: 12345678\r\n\r\n", "hex": null}, {"f": "cam", "t": "nvr", "m": "200 OK", "k": "res", "fields": [], "raw": "RTSP/1.0 200 OK\r\nCSeq: 5\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "RTSP uses TCP port ____ by default.", "a": ["554"], "why": "Media usually travels separately as RTP."}, {"q": "Which request returns the SDP description of the stream?", "opts": ["PLAY", "DESCRIBE", "TEARDOWN"], "a": 1, "why": "DESCRIBE, SETUP, PLAY, TEARDOWN.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc2326\" target=\"_blank\" rel=\"noopener\">RFC 2326, RTSP 1.0<\/a>."]}, {"id": "rtmp", "name": "RTMP", "full": "Live streaming upload", "layer": 7, "cat": "app", "title": "RTMP, sending a live stream to a platform.", "port": "1935", "transport": "TCP", "lede": "Streaming software such as OBS sends your live video to platforms with RTMP. The platform then turns it into HLS for viewers. Watch the handshake, connect and publish.", "overview": "<p>RTMP was made by Macromedia for Flash. Flash is gone, but RTMP is still the common way to <b>ingest<\/b> live video. The encoder sends a <b>stream key<\/b> in the publish command. Keep it secret, because anyone with it can broadcast on your channel. <b>RTMPS<\/b> wraps RTMP in TLS. Viewers do not receive RTMP. They watch HLS or DASH from a CDN.<\/p>", "nodes": {"obs": {"label": "Streaming PC", "sub": "OBS encoder", "icon": "laptop", "x": 0, "y": 1}, "ingest": {"label": "Ingest server", "sub": "live.example", "icon": "server", "x": 3, "y": 1}, "tc": {"label": "Transcoder", "sub": "many qualities", "icon": "server", "x": 5, "y": 1}, "cdn": {"label": "CDN", "sub": "HLS for viewers", "icon": "cloud", "x": 7, "y": 1}}, "links": [["obs", "ingest"], ["ingest", "tc"], ["tc", "cdn"]], "steps": [{"t": "Handshake", "tag": "handshake", "d": "<p>The encoder and the server exchange C0 and C1, S0, S1 and S2, then C2. These check the version and swap random data.<\/p>", "f": [], "p": [{"f": "obs", "t": "ingest", "m": "C0 + C1", "k": "ctl", "fields": [["C0 version", "3"], ["C1 time", "0"], ["C1 zero", "0"], ["C1 random", "1528 random bytes"]], "raw": null, "hex": null}, {"f": "ingest", "t": "obs", "m": "S0 + S1 + S2", "k": "ctl", "fields": [["S0 version", "3"], ["S1", "1536 bytes with server time and random data"], ["S2", "echo of C1"]], "raw": null, "hex": null}, {"f": "obs", "t": "ingest", "m": "C2", "k": "ctl", "fields": [["C2", "echo of S1, 1536 bytes"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Connect", "tag": "command", "d": "<p>The encoder sends a connect command, encoded in AMF, for the application <code>live<\/code>.<\/p>", "f": [], "p": [{"f": "obs", "t": "ingest", "m": "connect app=live", "k": "req", "fields": [["Message type", "20 AMF0 command"], ["Command", "connect"], ["Transaction ID", "1"], ["app", "live"], ["tcUrl", "rtmp://live.example/live"]], "raw": null, "hex": null}, {"f": "ingest", "t": "obs", "m": "_result NetConnection.Connect.Success", "k": "res", "fields": [["Message type", "20 AMF0 command"], ["Command", "_result"], ["Transaction ID", "1"], ["code", "NetConnection.Connect.Success"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Publish with the stream key", "tag": "command", "d": "<p>The encoder creates a stream and publishes it with the secret stream key. The server checks the key.<\/p>", "f": [["Command", "publish"], ["Stream key", "live_8f2...secret"], ["Type", "live"]], "p": [{"f": "obs", "t": "ingest", "m": "createStream", "k": "req", "fields": [["Message type", "20 AMF0 command"], ["Command", "createStream"], ["Transaction ID", "2"]], "raw": null, "hex": null}, {"f": "obs", "t": "ingest", "m": "publish live_8f2...", "k": "sec", "fields": [["Message type", "20 AMF0 command"], ["Command", "publish"], ["Stream key", "live_8f2...secret"], ["Type", "live"]], "raw": null, "hex": null}, {"f": "ingest", "t": "obs", "m": "onStatus NetStream.Publish.Start", "k": "res", "fields": [["Message type", "20 AMF0 command"], ["Command", "onStatus"], ["code", "NetStream.Publish.Start"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Audio and video", "tag": "media", "d": "<p>Audio and video messages flow, split into chunks. The server sends the stream to transcoders, which make several qualities, then to the CDN as HLS segments.<\/p>", "f": [], "p": [{"f": "obs", "t": "ingest", "m": "video and audio chunks", "k": "data", "fields": [["Message type", "9 video"], ["Chunk stream ID", "6"], ["Timestamp", "40"], ["Payload", "H.264 frame data"]], "raw": null, "hex": null}, {"f": "ingest", "t": "tc", "m": "stream", "k": "data", "fields": [["Renditions", "1080p, 720p, 480p"], ["Codec", "H.264 and AAC"]], "raw": null, "hex": null}, {"f": "tc", "t": "cdn", "m": "HLS segments", "k": "data", "fields": [["Format", "HLS"], ["Segment", "seg_00042.ts"], ["Duration", "4 seconds"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "RTMP uses TCP port ____ by default.", "a": ["1935"], "why": "RTMPS often uses 443."}, {"q": "Why must you keep the stream key secret?", "opts": ["It is your password for the website", "Anyone with it can broadcast on your channel", "It makes the stream faster"], "a": 1, "why": "The key authorizes publishing.", "type": "mcq"}], "refs": ["Wikipedia. <a href=\"https://en.wikipedia.org/wiki/Real-Time_Messaging_Protocol\" target=\"_blank\" rel=\"noopener\">Real-Time Messaging Protocol<\/a>."]}, {"id": "mqtt", "name": "MQTT", "full": "Messages for IoT devices", "layer": 7, "cat": "app", "title": "MQTT, sensors publish and apps subscribe.", "port": "1883, 8883 with TLS", "transport": "TCP", "lede": "MQTT is a tiny publish and subscribe protocol for sensors and devices on weak networks. Devices never talk to each other directly. A broker routes messages by topic.", "overview": "<p>Topics are paths such as <code>home/kitchen/temperature<\/code>. Subscribers can use wildcards, <code>+<\/code> for one level and <code>#<\/code> for many. <b>QoS 0<\/b> sends once, <b>QoS 1<\/b> at least once with PUBACK, <b>QoS 2<\/b> exactly once with a four step exchange. A <b>retained<\/b> message is kept for new subscribers. A <b>last will<\/b> message is sent if a device drops off.<\/p>", "nodes": {"sensor": {"label": "Temperature sensor", "sub": "192.168.1.60", "icon": "plc", "x": 0, "y": 1}, "broker": {"label": "MQTT broker", "sub": "192.168.1.2", "icon": "queue", "x": 4, "y": 1}, "app": {"label": "Phone app", "sub": "subscriber", "icon": "phone", "x": 8, "y": 0}, "dash": {"label": "Dashboard", "sub": "subscriber", "icon": "web", "x": 8, "y": 2}}, "links": [["sensor", "broker"], ["broker", "app"], ["broker", "dash"]], "steps": [{"t": "Connect", "tag": "connect", "d": "<p>Each client connects with a client id, a keep alive time and a login. The sensor also sets a last will, &quot;offline&quot;, on its status topic.<\/p>", "f": [], "p": [{"f": "sensor", "t": "broker", "m": "CONNECT id=sensor-7, will", "k": "req", "fields": [["Packet type", "0x10 CONNECT"], ["Remaining length", "58"], ["Protocol name", "MQTT"], ["Protocol level", "4"], ["Connect flags", "0x2e clean, will, will QoS 1"], ["Keep alive", "60"], ["Client ID", "sensor-7"], ["Will topic", "home/kitchen/status"]], "raw": null, "hex": null}, {"f": "broker", "t": "sensor", "m": "CONNACK", "k": "res", "fields": [["Packet type", "0x20 CONNACK"], ["Remaining length", "2"], ["Session present", "0"], ["Return code", "0 accepted"]], "raw": null, "hex": null}, {"f": "app", "t": "broker", "m": "CONNECT id=phone", "k": "req", "fields": [["Packet type", "0x10 CONNECT"], ["Remaining length", "17"], ["Protocol name", "MQTT"], ["Protocol level", "4"], ["Keep alive", "60"], ["Client ID", "phone"]], "raw": null, "hex": null}, {"f": "broker", "t": "app", "m": "CONNACK", "k": "res", "fields": [["Packet type", "0x20 CONNACK"], ["Remaining length", "2"], ["Session present", "0"], ["Return code", "0 accepted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Subscribe with a wildcard", "tag": "subscribe", "d": "<p>The app subscribes to <code>home/+/temperature<\/code> with QoS 1. It will get temperatures from every room.<\/p>", "f": [], "p": [{"f": "app", "t": "broker", "m": "SUBSCRIBE home/+/temperature QoS 1", "k": "req", "fields": [["Packet type", "0x82 SUBSCRIBE"], ["Remaining length", "29"], ["Packet ID", "1"], ["Topic filter", "home/+/temperature"], ["QoS", "1"]], "raw": null, "hex": null}, {"f": "broker", "t": "app", "m": "SUBACK", "k": "res", "fields": [["Packet type", "0x90 SUBACK"], ["Remaining length", "3"], ["Packet ID", "1"], ["Granted QoS", "1"]], "raw": null, "hex": null}, {"f": "dash", "t": "broker", "m": "SUBSCRIBE home/#", "k": "req", "fields": [["Packet type", "0x82 SUBSCRIBE"], ["Remaining length", "12"], ["Packet ID", "1"], ["Topic filter", "home/#"], ["QoS", "0"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Publish", "tag": "publish", "d": "<p>The sensor publishes 22.5 to <code>home/kitchen/temperature<\/code> with QoS 1 and the retain flag. The broker acknowledges with PUBACK.<\/p>", "f": [], "p": [{"f": "sensor", "t": "broker", "m": "PUBLISH home/kitchen/temperature 22.5", "k": "data", "fields": [["Packet type", "0x32 PUBLISH QoS 1"], ["Remaining length", "33"], ["Topic", "home/kitchen/temperature"], ["Packet ID", "7"], ["Payload", "22.5"]], "raw": null, "hex": null}, {"f": "broker", "t": "sensor", "m": "PUBACK", "k": "ctl", "fields": [["Packet type", "0x40 PUBACK"], ["Remaining length", "2"], ["Packet ID", "7"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Fan out", "tag": "deliver", "d": "<p>The broker sends the message to every subscriber whose filter matches.<\/p>", "f": [], "p": [{"f": "broker", "t": "app", "m": "PUBLISH 22.5", "k": "data", "fields": [["Packet type", "0x32 PUBLISH QoS 1"], ["Remaining length", "33"], ["Topic", "home/kitchen/temperature"], ["Packet ID", "3"], ["Payload", "22.5"]], "raw": null, "hex": null}, {"f": "broker", "t": "dash", "m": "PUBLISH 22.5", "k": "data", "fields": [["Packet type", "0x30 PUBLISH QoS 0"], ["Remaining length", "30"], ["Topic", "home/kitchen/temperature"], ["Payload", "22.5"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Keep alive and last will", "tag": "health", "d": "<p>The sensor sends PINGREQ when it is idle. If it loses power and misses its keep alive, the broker publishes its last will, &quot;offline&quot;.<\/p>", "f": [], "p": [{"f": "sensor", "t": "broker", "m": "PINGREQ", "k": "ctl", "fields": [["Packet type", "0xc0 PINGREQ"], ["Remaining length", "0"]], "raw": null, "hex": null}, {"f": "broker", "t": "sensor", "m": "PINGRESP", "k": "ctl", "fields": [["Packet type", "0xd0 PINGRESP"], ["Remaining length", "0"]], "raw": null, "hex": null}, {"f": "broker", "t": "dash", "m": "PUBLISH status offline (last will)", "k": "bad", "fields": [["Packet type", "0x30 PUBLISH QoS 0"], ["Remaining length", "26"], ["Topic", "home/kitchen/status"], ["Payload", "offline"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "Which topic filter matches home/kitchen/temperature and home/hall/temperature?", "opts": ["home/#/temperature", "home/+/temperature", "home/kitchen"], "a": 1, "why": "Plus matches exactly one level. Hash matches many levels and must be last.", "type": "mcq"}, {"type": "fill", "q": "MQTT over TLS uses port ____.", "a": ["8883"], "why": "Plain MQTT uses 1883."}], "refs": ["OASIS. <a href=\"https://docs.oasis-open.org/mqtt/mqtt/v5.0/mqtt-v5.0.html\" target=\"_blank\" rel=\"noopener\">MQTT version 5.0<\/a>.", "HiveMQ. <a href=\"https://www.hivemq.com/mqtt/\" target=\"_blank\" rel=\"noopener\">MQTT essentials<\/a>."]}, {"id": "amqp", "name": "AMQP", "full": "Message queues, RabbitMQ", "layer": 7, "cat": "app", "title": "AMQP, publishing to an exchange and consuming from a queue.", "port": "5672, 5671 with TLS", "transport": "TCP", "lede": "AMQP 0-9-1 is the protocol of RabbitMQ. Producers send to an exchange, the exchange routes to queues by bindings, and consumers acknowledge each message.", "overview": "<p>Producers never write to a queue directly. They publish to an <b>exchange<\/b> with a <b>routing key<\/b>. <b>Bindings<\/b> connect exchanges to queues. A <b>direct<\/b> exchange matches the key exactly, a <b>topic<\/b> exchange matches patterns such as <code>order.*<\/code>, a <b>fanout<\/b> exchange copies to every bound queue. Consumers send <b>ack<\/b> after work, so a crash means redelivery, not loss.<\/p>", "nodes": {"prod": {"label": "Order service", "sub": "producer", "icon": "server", "x": 0, "y": 1}, "ex": {"label": "Exchange orders", "sub": "topic", "icon": "queue", "x": 3, "y": 1}, "q1": {"label": "Queue emails", "sub": "bound order.*", "icon": "queue", "x": 5, "y": 0}, "q2": {"label": "Queue billing", "sub": "bound order.paid", "icon": "queue", "x": 5, "y": 2}, "cons": {"label": "Email worker", "sub": "consumer", "icon": "server", "x": 8, "y": 0}}, "links": [["prod", "ex"], ["ex", "q1"], ["ex", "q2"], ["q1", "cons"]], "steps": [{"t": "Open the connection", "tag": "connect", "d": "<p>The client sends the protocol header, then Connection.Start, Start-Ok with credentials, Tune and Open. Then it opens a channel. Many channels share one TCP connection.<\/p>", "f": [], "p": [{"f": "prod", "t": "ex", "m": "AMQP 0-9-1 header", "k": "ctl", "fields": [], "raw": "AMQP\u0000\u0000\t\u0001", "hex": null}, {"f": "ex", "t": "prod", "m": "Connection.Start", "k": "ctl", "fields": [["Frame type", "1 method"], ["Channel", "0"], ["Class ID", "10 connection"], ["Method ID", "10 start"], ["Mechanisms", "PLAIN AMQPLAIN"], ["Frame end", "0xce"]], "raw": null, "hex": null}, {"f": "prod", "t": "ex", "m": "Start-Ok, Tune-Ok, Open, Channel.Open", "k": "ctl", "fields": [["Frame type", "1 method"], ["Channel", "0"], ["Class ID", "10 connection"], ["Method ID", "11 start-ok"], ["Then", "tune-ok, open, channel open"], ["Frame end", "0xce"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Publish", "tag": "publish", "d": "<p>The order service publishes a message to exchange <code>orders<\/code> with routing key <code>order.created<\/code>, marked persistent.<\/p>", "f": [["Exchange", "orders"], ["Routing key", "order.created"], ["Delivery mode", "2 persistent"]], "p": [{"f": "prod", "t": "ex", "m": "Basic.Publish order.created", "k": "data", "fields": [["Frame type", "1 method"], ["Channel", "1"], ["Class ID", "60 basic"], ["Method ID", "40 publish"], ["Exchange", "orders"], ["Routing key", "order.created"], ["Delivery mode", "2 persistent"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Route by binding", "tag": "route", "d": "<p>The emails queue is bound with <code>order.*<\/code>, so it matches. The billing queue is bound with <code>order.paid<\/code>, so it does not.<\/p>", "f": [], "p": [{"f": "ex", "t": "q1", "m": "route order.created", "k": "data", "fields": [["Binding", "order.* matches order.created"], ["Queue", "q1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Deliver and acknowledge", "tag": "consume", "d": "<p>The email worker consumes from the queue. It gets Basic.Deliver, sends the email, then Basic.Ack. Without the ack, RabbitMQ would redeliver the message.<\/p>", "f": [], "p": [{"f": "q1", "t": "cons", "m": "Basic.Deliver", "k": "data", "fields": [["Frame type", "1 method"], ["Channel", "1"], ["Class ID", "60 basic"], ["Method ID", "60 deliver"], ["Delivery tag", "1"], ["Routing key", "order.created"]], "raw": null, "hex": null}, {"f": "cons", "t": "q1", "m": "Basic.Ack", "k": "ctl", "fields": [["Frame type", "1 method"], ["Channel", "1"], ["Class ID", "60 basic"], ["Method ID", "80 ack"], ["Delivery tag", "1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "Where does a producer publish in AMQP 0-9-1?", "opts": ["Directly to a queue", "To an exchange, which routes to queues by bindings", "To the consumer"], "a": 1, "why": "Exchanges and bindings decide routing.", "type": "mcq"}, {"type": "fill", "q": "An exchange that copies every message to all bound queues is a ____ exchange.", "a": ["fanout"], "why": "Direct, topic, fanout and headers are the types."}], "refs": ["RabbitMQ. <a href=\"https://www.rabbitmq.com/tutorials/amqp-concepts\" target=\"_blank\" rel=\"noopener\">AMQP 0-9-1 model explained<\/a>."]}, {"id": "quic", "name": "QUIC", "full": "HTTP/3 over UDP", "layer": 4, "cat": "core", "title": "QUIC, a faster secure transport on UDP.", "port": "443", "transport": "UDP", "lede": "QUIC joins the transport and TLS handshakes into one round trip, runs many streams without blocking each other, and survives a change of network. HTTP/3 runs on it.", "overview": "<p>QUIC is defined in RFC 9000. It runs in user space on top of UDP. TLS 1.3 is built in, so almost everything is encrypted, even most transport headers. Streams are independent. A lost packet only delays its own stream, not all of them.<\/p>\n<p>Each connection has <b>connection IDs<\/b>, not only addresses. When your phone moves from Wi-Fi to mobile data, the connection can continue.<\/p>", "nodes": {"phone": {"label": "Phone", "sub": "192.168.1.20", "icon": "phone", "x": 0, "y": 1}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 3, "y": 1}, "srv": {"label": "Web server", "sub": "203.0.113.90", "icon": "web", "x": 6, "y": 1}}, "links": [["phone", "net"], ["net", "srv"]], "steps": [{"t": "Initial packet with ClientHello", "tag": "handshake", "d": "<p>The client sends a QUIC Initial packet over UDP. Inside a CRYPTO frame is a TLS 1.3 ClientHello with ALPN <code>h3<\/code>. There is no separate TCP handshake.<\/p>", "f": [["Packet", "Initial"], ["ALPN", "h3"], ["Size", "at least 1200 bytes"]], "p": [{"f": "phone", "t": "srv", "m": "Initial: ClientHello", "k": "sec", "fields": [["Header form", "1 long"], ["Packet type", "0 Initial"], ["Version", "0x00000001"], ["Destination connection ID", "0x8394c8f03e515708"], ["Contains", "CRYPTO frame with TLS ClientHello, ALPN h3, padded to at least 1200 bytes"]], "raw": null, "hex": null}], "on": [], "good": "The first packet is padded to at least 1200 bytes. This stops attackers from using small spoofed packets to make the server send large replies.", "bad": []}, {"t": "Server Initial and Handshake", "tag": "handshake", "d": "<p>The server answers with ServerHello in an Initial packet and the rest of the TLS handshake in Handshake packets. Keys are ready after this one round trip.<\/p>", "f": [], "p": [{"f": "srv", "t": "phone", "m": "Initial: ServerHello", "k": "sec", "fields": [["Header form", "1 long"], ["Packet type", "0 Initial"], ["Version", "0x00000001"], ["Destination connection ID", "0x8394c8f03e515708"], ["Contains", "CRYPTO frame with TLS ServerHello"]], "raw": null, "hex": null}, {"f": "srv", "t": "phone", "m": "Handshake: Certificate, Finished", "k": "sec", "fields": [["Header form", "1 long"], ["Packet type", "2 Handshake"], ["Version", "0x00000001"], ["Destination connection ID", "0x8394c8f03e515708"], ["Contains", "CRYPTO frames with Certificate, CertificateVerify, Finished, encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Finished and the first request", "tag": "data", "d": "<p>The client sends Finished and, in the same flight, the HTTP/3 request on stream 0, protected with the new keys.<\/p>", "f": [], "p": [{"f": "phone", "t": "srv", "m": "Handshake: Finished", "k": "sec", "fields": [["Header form", "1 long"], ["Packet type", "2 Handshake"], ["Version", "0x00000001"], ["Destination connection ID", "0x8394c8f03e515708"], ["Contains", "CRYPTO frame with client Finished"]], "raw": null, "hex": null}, {"f": "phone", "t": "srv", "m": "1-RTT: stream 0 GET /", "k": "req", "fields": [["Header form", "0 short"], ["Destination connection ID", "0x8394c8f03e515708"], ["Packet number", "2"], ["Frames", "STREAM id 0, HTTP/3 HEADERS GET /"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Independent streams", "tag": "streams", "d": "<p>Responses for streams 0, 4 and 8 arrive. One UDP packet for stream 4 is lost. Only stream 4 waits for the resend. Streams 0 and 8 carry on.<\/p>", "f": [], "p": [{"f": "srv", "t": "phone", "m": "stream 0 data", "k": "res", "fields": [["Header form", "0 short"], ["Destination connection ID", "0x5c1f0a22"], ["Packet number", "7"], ["Frames", "STREAM id 0, offset 0"]], "raw": null, "hex": null}, {"f": "srv", "t": "phone", "m": "stream 4 data (lost)", "k": "bad", "fields": [["Header form", "0 short"], ["Destination connection ID", "0x5c1f0a22"], ["Packet number", "8"], ["Frames", "STREAM id 4, lost"]], "raw": null, "hex": null}, {"f": "srv", "t": "phone", "m": "stream 8 data", "k": "res", "fields": [["Header form", "0 short"], ["Destination connection ID", "0x5c1f0a22"], ["Packet number", "9"], ["Frames", "STREAM id 8, delivered without waiting for stream 4"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Change of network", "tag": "migration", "d": "<p>The phone leaves Wi-Fi and gets a new IP on mobile data. It keeps sending with the same connection ID. The server checks the new path and the download continues.<\/p>", "f": [["Old IP", "192.168.1.20"], ["New IP", "100.64.12.7"], ["Connection ID", "same"]], "p": [{"f": "phone", "t": "srv", "m": "same connection ID, new address", "k": "ctl", "fields": [["Header form", "0 short"], ["Destination connection ID", "0x8394c8f03e515708"], ["Packet number", "31"], ["Src IP", "100.64.12.7"], ["Note", "new address, same connection"]], "raw": null, "hex": null}, {"f": "srv", "t": "phone", "m": "path challenge and response", "k": "ctl", "fields": [["Header form", "0 short"], ["Frames", "PATH_CHALLENGE 0x2f7a1c9e and PATH_RESPONSE"], ["Packet number", "40"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "On which protocol does QUIC run?", "opts": ["TCP", "UDP", "ICMP"], "a": 1, "why": "QUIC builds reliability and streams on top of UDP.", "type": "mcq"}, {"type": "fill", "q": "HTTP over QUIC is called HTTP/____.", "a": ["3"], "why": "HTTP/3 is defined in RFC 9114."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc9000\" target=\"_blank\" rel=\"noopener\">RFC 9000, QUIC<\/a>.", "Cloudflare. <a href=\"https://www.cloudflare.com/learning/performance/what-is-http3/\" target=\"_blank\" rel=\"noopener\">What is HTTP/3?<\/a>"]}, {"id": "tcp", "name": "TCP", "full": "Transmission Control Protocol", "layer": 4, "cat": "core", "title": "TCP, a reliable conversation over an unreliable network.", "port": "any", "transport": "IP", "lede": "TCP turns lost and out of order packets into a clean, ordered byte stream. Watch the handshake, the data with acknowledgements, a lost segment and the polite close.", "overview": "<p>TCP numbers every byte with a <b>sequence number<\/b>. The receiver sends back an <b>acknowledgement<\/b> with the next byte it expects. Lost data is sent again. A <b>window<\/b> says how much data may be in flight, which gives flow control. Congestion control slows down when the network is busy.<\/p>", "nodes": {"client": {"label": "Client", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 3, "y": 1}, "srv": {"label": "Server", "sub": "203.0.113.10", "icon": "server", "x": 6, "y": 1}}, "links": [["client", "net"], ["net", "srv"]], "steps": [{"t": "SYN", "tag": "handshake", "d": "<p>The client picks a random initial sequence number, here 1000, and sends a segment with the SYN flag.<\/p>", "f": [["Flags", "SYN"], ["Seq", "1000"], ["Window", "64240"]], "p": [{"f": "client", "t": "srv", "m": "SYN seq=1000", "k": "ctl", "fields": [["Flags", "SYN"], ["Seq", "1000"], ["Window", "64240"], ["MSS", "1460"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "SYN-ACK", "tag": "handshake", "d": "<p>The server picks its own number, 5000, and acknowledges the client SYN with ack 1001.<\/p>", "f": [["Flags", "SYN, ACK"], ["Seq", "5000"], ["Ack", "1001"]], "p": [{"f": "srv", "t": "client", "m": "SYN-ACK seq=5000 ack=1001", "k": "ctl", "fields": [["Src port", "443"], ["Dst port", "51000"], ["Flags", "SYN ACK"], ["Seq", "5000"], ["Ack", "1001"], ["Window", "65160"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "ACK, connection open", "tag": "handshake", "d": "<p>The client acknowledges with ack 5001. Both sides now know the starting numbers of the other.<\/p>", "f": [], "p": [{"f": "client", "t": "srv", "m": "ACK ack=5001", "k": "ctl", "fields": [["Src port", "51000"], ["Dst port", "443"], ["Flags", "ACK"], ["Seq", "1001"], ["Ack", "5001"], ["Window", "502"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Data and acknowledgements", "tag": "data", "d": "<p>The client sends 100 bytes starting at 1001. The server acknowledges with ack 1101, the next byte it expects.<\/p>", "f": [["Seq", "1001"], ["Length", "100"], ["Ack from server", "1101"]], "p": [{"f": "client", "t": "srv", "m": "seq=1001 len=100", "k": "data", "fields": [["Src port", "51000"], ["Dst port", "443"], ["Flags", "PSH ACK"], ["Seq", "1001"], ["Ack", "5001"], ["Window", "502"], ["Length", "100"]], "raw": null, "hex": null}, {"f": "srv", "t": "client", "m": "ACK ack=1101", "k": "ctl", "fields": [["Src port", "443"], ["Dst port", "51000"], ["Flags", "ACK"], ["Seq", "5001"], ["Ack", "1101"], ["Window", "509"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "A segment is lost", "tag": "retransmit", "d": "<p>The next segment is lost on the way. The server keeps sending ack 1101. After duplicate acks or a timeout, the client sends the segment again.<\/p>", "f": [], "p": [{"f": "client", "t": "srv", "m": "seq=1101 len=100 (lost)", "k": "bad", "fields": [["Src port", "51000"], ["Dst port", "443"], ["Flags", "PSH ACK"], ["Seq", "1101"], ["Ack", "5001"], ["Window", "502"], ["Length", "100"]], "raw": null, "hex": null}, {"f": "srv", "t": "client", "m": "ACK ack=1101 (duplicate)", "k": "ctl", "fields": [["Src port", "443"], ["Dst port", "51000"], ["Flags", "ACK"], ["Seq", "5001"], ["Ack", "1101"], ["Window", "509"]], "raw": null, "hex": null}, {"f": "client", "t": "srv", "m": "seq=1101 len=100 (resent)", "k": "data", "fields": [["Src port", "51000"], ["Dst port", "443"], ["Flags", "PSH ACK"], ["Seq", "1101"], ["Ack", "5001"], ["Window", "502"], ["Length", "100"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Close", "tag": "close", "d": "<p>Each side closes its own direction with FIN, and the other side acknowledges it.<\/p>", "f": [], "p": [{"f": "client", "t": "srv", "m": "FIN", "k": "ctl", "fields": [["Src port", "51000"], ["Dst port", "443"], ["Flags", "FIN ACK"], ["Seq", "1201"], ["Ack", "5001"]], "raw": null, "hex": null}, {"f": "srv", "t": "client", "m": "ACK", "k": "ctl", "fields": [["Src port", "443"], ["Dst port", "51000"], ["Flags", "ACK"], ["Seq", "5001"], ["Ack", "1202"]], "raw": null, "hex": null}, {"f": "srv", "t": "client", "m": "FIN", "k": "ctl", "fields": [["Src port", "443"], ["Dst port", "51000"], ["Flags", "FIN ACK"], ["Seq", "5001"], ["Ack", "1202"]], "raw": null, "hex": null}, {"f": "client", "t": "srv", "m": "ACK", "k": "ctl", "fields": [["Src port", "51000"], ["Dst port", "443"], ["Flags", "ACK"], ["Seq", "1202"], ["Ack", "5002"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "The client sent SYN with seq 7000. What ack does the server send in its SYN-ACK?", "opts": ["7000", "7001", "0"], "a": 1, "why": "The ack is the next byte expected. A SYN counts as one byte.", "type": "mcq"}, {"type": "fill", "q": "The three messages that open a TCP connection are SYN, SYN-ACK and ____.", "a": ["ACK"], "why": "This is the three way handshake."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc9293\" target=\"_blank\" rel=\"noopener\">RFC 9293, TCP<\/a>.", "Ilya Grigorik. <a href=\"https://hpbn.co/building-blocks-of-tcp/\" target=\"_blank\" rel=\"noopener\">High Performance Browser Networking, building blocks of TCP<\/a>."]}, {"id": "udp", "name": "UDP", "full": "User Datagram Protocol", "layer": 4, "cat": "core", "title": "UDP, send and hope, very fast.", "port": "any", "transport": "IP", "lede": "UDP sends single messages called datagrams. There is no handshake, no order and no resend. It is simple and fast, so DNS, games, voice and QUIC use it.", "overview": "<p>A UDP header has only four fields. Source port, destination port, length and checksum, 8 bytes in total. Compare that with at least 20 bytes for TCP. If the application needs reliability, it must build it itself, as QUIC does.<\/p>", "nodes": {"game": {"label": "Game client", "sub": "192.168.1.30", "icon": "laptop", "x": 0, "y": 1}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 3, "y": 1}, "srv": {"label": "Game server", "sub": "203.0.113.100", "icon": "server", "x": 6, "y": 1}}, "links": [["game", "net"], ["net", "srv"]], "steps": [{"t": "No handshake", "tag": "data", "d": "<p>The game client sends its position at once. No connection setup.<\/p>", "f": [["Source port", "50000"], ["Destination port", "27015"], ["Header", "8 bytes"]], "p": [{"f": "game", "t": "srv", "m": "position x=10 y=4 (tick 1)", "k": "data", "fields": [["Src port", "50000"], ["Dst port", "27015"], ["Length", "28"], ["Checksum", "0x4c1a"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Keep sending", "tag": "data", "d": "<p>The client sends a new position every tick, about 30 to 60 times a second.<\/p>", "f": [], "p": [{"f": "game", "t": "srv", "m": "position (tick 2)", "k": "data", "fields": [["Src port", "50001"], ["Dst port", "27015"], ["Length", "40"], ["Checksum", "0x7c3a"], ["Payload", "tick 2, x 10.4, y 3.1"]], "raw": null, "hex": null}, {"f": "game", "t": "srv", "m": "position (tick 3)", "k": "data", "fields": [["Src port", "50001"], ["Dst port", "27015"], ["Length", "40"], ["Checksum", "0x7c3a"], ["Payload", "tick 3, x 10.6, y 3.1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "One is lost, nobody waits", "tag": "loss", "d": "<p>Tick 4 is lost. UDP does not resend it. Tick 5 arrives, and it is newer anyway. For live data, waiting for old data would be worse.<\/p>", "f": [], "p": [{"f": "game", "t": "srv", "m": "position (tick 4, lost)", "k": "bad", "fields": [["Src port", "50001"], ["Dst port", "27015"], ["Length", "40"], ["Checksum", "0x7c3a"], ["Payload", "tick 4, lost on the way"]], "raw": null, "hex": null}, {"f": "game", "t": "srv", "m": "position (tick 5)", "k": "data", "fields": [["Src port", "50001"], ["Dst port", "27015"], ["Length", "40"], ["Checksum", "0x7c3a"], ["Payload", "tick 5, x 11.0, y 3.2"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Server updates", "tag": "data", "d": "<p>The server sends world updates back the same way.<\/p>", "f": [], "p": [{"f": "srv", "t": "game", "m": "world state", "k": "data", "fields": [["Src port", "27015"], ["Dst port", "50001"], ["Length", "520"], ["Checksum", "0x7c3a"], ["Payload", "world state for tick 5"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "Which is true about UDP?", "opts": ["It guarantees order", "It has no handshake and does not resend lost datagrams", "It is slower than TCP"], "a": 1, "why": "Applications add reliability if they need it.", "type": "mcq"}, {"type": "num", "q": "How many bytes is a UDP header?", "a": 8, "tol": 0, "unit": "bytes", "why": "Four fields of 2 bytes each."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc768\" target=\"_blank\" rel=\"noopener\">RFC 768, User Datagram Protocol<\/a>."]}, {"id": "ip", "name": "IP", "full": "Internet Protocol", "layer": 3, "cat": "core", "title": "IP, one packet hops across the internet.", "port": "none, IP has no ports", "transport": "-", "lede": "IP gives every machine an address and moves packets hop by hop toward the destination. Each router looks only at the destination and picks the next hop.", "overview": "<p>An IPv4 packet header has a source and destination address, a <b>TTL<\/b>, the protocol inside, such as 6 for TCP or 17 for UDP, and a checksum. Each router lowers the TTL by one. If it reaches zero, the router drops the packet and sends an ICMP message back. This stops packets from looping forever.<\/p>\n<p>Home networks use private addresses such as 192.168.x.x. The home router does <b>NAT<\/b>. It swaps the private source address for its public address on the way out.<\/p>", "nodes": {"pc": {"label": "Laptop", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 2}, "home": {"label": "Home router", "sub": "198.51.100.7 public", "icon": "router", "x": 2, "y": 2}, "isp": {"label": "ISP router", "sub": "AS 64500", "icon": "router", "x": 4, "y": 1}, "core": {"label": "Core router", "sub": "AS 64510", "icon": "router", "x": 6, "y": 1}, "srv": {"label": "Server", "sub": "203.0.113.10", "icon": "server", "x": 8, "y": 2}}, "links": [["pc", "home"], ["home", "isp"], ["isp", "core"], ["core", "srv"]], "steps": [{"t": "Build the packet", "tag": "send", "d": "<p>The laptop puts the TCP segment in an IP packet. Source 192.168.1.10, destination 203.0.113.10, TTL 64. The destination is not local, so it sends the packet to its default gateway, the home router.<\/p>", "f": [["Src", "192.168.1.10"], ["Dst", "203.0.113.10"], ["TTL", "64"], ["Protocol", "6 TCP"]], "p": [{"f": "pc", "t": "home", "m": "IP 192.168.1.10 to 203.0.113.10 TTL 64", "k": "data", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "64"], ["Protocol", "6 TCP"], ["Src", "192.168.1.10"], ["Dst", "203.0.113.10"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "NAT at home", "tag": "nat", "d": "<p>The home router replaces the private source with its public address 198.51.100.7 and remembers the mapping, so replies can come back. It lowers the TTL to 63.<\/p>", "f": [["Src after NAT", "198.51.100.7"], ["TTL", "63"]], "p": [{"f": "home", "t": "isp", "m": "IP 198.51.100.7 to 203.0.113.10 TTL 63", "k": "data", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "63"], ["Protocol", "6 TCP"], ["Src", "198.51.100.7"], ["Dst", "203.0.113.10"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Hop by hop", "tag": "route", "d": "<p>Each router looks up the destination in its routing table and forwards the packet to the next hop. TTL drops at each hop.<\/p>", "f": [], "p": [{"f": "isp", "t": "core", "m": "TTL 62", "k": "data", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "62"], ["Protocol", "6 TCP"], ["Src", "198.51.100.7"], ["Dst", "203.0.113.10"]], "raw": null, "hex": null}, {"f": "core", "t": "srv", "m": "TTL 61", "k": "data", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "61"], ["Protocol", "6 TCP"], ["Src", "198.51.100.7"], ["Dst", "203.0.113.10"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The reply comes back", "tag": "route", "d": "<p>The server replies to 198.51.100.7. The home router finds the mapping and sends the reply to 192.168.1.10.<\/p>", "f": [], "p": [{"f": "srv", "t": "home", "m": "IP 203.0.113.10 to 198.51.100.7", "k": "res", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "64"], ["Protocol", "6 TCP"], ["Src", "203.0.113.10"], ["Dst", "198.51.100.7"]], "raw": null, "hex": null}, {"f": "home", "t": "pc", "m": "IP to 192.168.1.10 (NAT reversed)", "k": "res", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "63"], ["Protocol", "6 TCP"], ["Src", "203.0.113.10"], ["Dst", "192.168.1.10"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What happens when the TTL reaches 0 at a router?", "opts": ["The packet is delivered", "The router drops it and usually sends an ICMP time exceeded message", "The TTL resets to 64"], "a": 1, "why": "This is how traceroute discovers each hop.", "type": "mcq"}, {"type": "fill", "q": "Swapping private addresses for a public address at the home router is called ____.", "a": ["NAT", "network address translation"], "why": "NAT lets many devices share one public IPv4 address."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc791\" target=\"_blank\" rel=\"noopener\">RFC 791, Internet Protocol<\/a>.", "Cloudflare. <a href=\"https://www.cloudflare.com/learning/network-layer/what-is-routing/\" target=\"_blank\" rel=\"noopener\">What is routing?<\/a>"]}, {"id": "ipv6", "name": "IPv6", "full": "Address setup, neighbour discovery", "layer": 3, "cat": "core", "title": "IPv6, a device gives itself an address.", "port": "none", "transport": "-", "lede": "IPv6 has enough addresses for every device. Watch how a laptop joins a network, learns the prefix from the router and builds its own address, with no DHCP server needed.", "overview": "<p>IPv6 addresses are 128 bits, written in hexadecimal groups, such as <code>2001:db8:1:1::25<\/code>. Hosts use <b>SLAAC<\/b>, stateless address autoconfiguration. They learn the network prefix from <b>Router Advertisements<\/b> and build the rest themselves. <b>Neighbor Discovery<\/b>, part of ICMPv6, replaces ARP.<\/p>", "nodes": {"pc": {"label": "Laptop", "sub": "fe80::a1b2", "icon": "laptop", "x": 0, "y": 1}, "sw": {"label": "Switch", "sub": "", "icon": "switch", "x": 3, "y": 1}, "rtr": {"label": "Router", "sub": "2001:db8:1:1::1", "icon": "router", "x": 6, "y": 1}, "peer": {"label": "Printer", "sub": "2001:db8:1:1::9", "icon": "server", "x": 3, "y": 3}}, "links": [["pc", "sw"], ["sw", "rtr"], ["sw", "peer"]], "steps": [{"t": "Link local address", "tag": "setup", "d": "<p>The laptop first makes a link local address that starts with <code>fe80::<\/code>. It works only on this local link.<\/p>", "f": [["Link local", "fe80::a1b2:c3ff:fed4:e5f6"]], "p": [], "on": [], "good": "", "bad": []}, {"t": "Router Solicitation", "tag": "ndp", "d": "<p>The laptop sends a Router Solicitation to the all routers multicast address <code>ff02::2<\/code>.<\/p>", "f": [], "p": [{"f": "pc", "t": "rtr", "m": "ICMPv6 Router Solicitation to ff02::2", "k": "ctl", "fields": [["Version", "6"], ["Next header", "58 ICMPv6"], ["Hop limit", "255"], ["Src", "fe80::a1b2"], ["Dst", "ff02::2"], ["ICMPv6 type", "133 Router Solicitation"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Router Advertisement", "tag": "ndp", "d": "<p>The router answers with a Router Advertisement. It gives the prefix <code>2001:db8:1:1::/64<\/code> and says it is the default gateway. DNS server addresses can also come in the advertisement.<\/p>", "f": [["Prefix", "2001:db8:1:1::/64"], ["Gateway", "router link local address"]], "p": [{"f": "rtr", "t": "pc", "m": "ICMPv6 Router Advertisement prefix /64", "k": "res", "fields": [["Version", "6"], ["Next header", "58 ICMPv6"], ["Hop limit", "255"], ["Src", "fe80::1"], ["Dst", "ff02::1"], ["ICMPv6 type", "134 Router Advertisement"], ["Prefix", "2001:db8:1:1::"], ["Prefix length", "64"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Build and check the address", "tag": "slaac", "d": "<p>The laptop adds its own 64 bit interface id to the prefix, often random for privacy. Before it uses the address, it checks nobody else has it with Duplicate Address Detection.<\/p>", "f": [["New address", "2001:db8:1:1:5d2e:91a4:7b3c:10f2"]], "p": [{"f": "pc", "t": "sw", "m": "Neighbor Solicitation (duplicate check)", "k": "ctl", "fields": [["Version", "6"], ["Next header", "58 ICMPv6"], ["Hop limit", "255"], ["Src", "::"], ["Dst", "ff02::1:ff3c:10f2"], ["ICMPv6 type", "135 Neighbor Solicitation"], ["Target", "2001:db8:1:1:5d2e:91a4:7b3c:10f2"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Find a neighbour", "tag": "ndp", "d": "<p>To print, the laptop needs the printer link layer address. It sends a Neighbor Solicitation. The printer answers with a Neighbor Advertisement. This replaces ARP.<\/p>", "f": [], "p": [{"f": "pc", "t": "peer", "m": "Neighbor Solicitation who has ::9", "k": "ctl", "fields": [["Version", "6"], ["Next header", "58 ICMPv6"], ["Hop limit", "255"], ["Src", "2001:db8:1:1:5d2e:91a4:7b3c:10f2"], ["Dst", "ff02::1:ff00:9"], ["ICMPv6 type", "135 Neighbor Solicitation"], ["Target", "2001:db8:1:1::9"]], "raw": null, "hex": null}, {"f": "peer", "t": "pc", "m": "Neighbor Advertisement MAC 00:1b:...", "k": "res", "fields": [["Version", "6"], ["Next header", "58 ICMPv6"], ["Hop limit", "255"], ["Src", "2001:db8:1:1::9"], ["Dst", "2001:db8:1:1:5d2e:91a4:7b3c:10f2"], ["ICMPv6 type", "136 Neighbor Advertisement"], ["Target MAC", "00:1b:44:11:3a:b7"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "num", "q": "How many bits long is an IPv6 address?", "a": 128, "tol": 0, "unit": "bits", "why": "IPv4 has 32 bits."}, {"q": "Which protocol replaces ARP in IPv6?", "opts": ["DHCP", "Neighbor Discovery, part of ICMPv6", "BGP"], "a": 1, "why": "Neighbor Solicitation and Advertisement find link layer addresses.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc4861\" target=\"_blank\" rel=\"noopener\">RFC 4861, Neighbor Discovery<\/a>.", "IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc4862\" target=\"_blank\" rel=\"noopener\">RFC 4862, IPv6 stateless address autoconfiguration<\/a>."]}, {"id": "bgp", "name": "BGP", "full": "Routing between networks", "layer": 7, "cat": "core", "title": "BGP, how networks tell each other where addresses live.", "port": "179", "transport": "TCP", "lede": "The internet is tens of thousands of networks. BGP is how they announce which address blocks they can reach. A wrong announcement can send traffic to the wrong place.", "overview": "<p>Each large network is an <b>autonomous system<\/b>, with an AS number. Routers in different systems open a BGP session over TCP port 179. They exchange <b>UPDATE<\/b> messages that announce prefixes with an <b>AS path<\/b>. Each router chooses the best path by policy and rules, such as the shortest AS path.<\/p>\n<p>BGP trusts announcements by default. <b>RPKI<\/b> lets networks sign which AS may announce a prefix, so others can reject hijacks.<\/p>", "nodes": {"a": {"label": "Router AS 64500", "sub": "ISP A", "icon": "router", "x": 0, "y": 1}, "b": {"label": "Router AS 64510", "sub": "ISP B", "icon": "router", "x": 4, "y": 0}, "c": {"label": "Router AS 64520", "sub": "Hosting", "icon": "router", "x": 8, "y": 1}, "bad": {"label": "Router AS 64666", "sub": "misconfigured", "icon": "router", "x": 4, "y": 3}}, "links": [["a", "b"], ["b", "c"], ["a", "bad"], ["bad", "c"]], "steps": [{"t": "Open a session", "tag": "session", "d": "<p>Routers in AS 64510 and AS 64520 open TCP 179 and send OPEN messages with their AS numbers and a hold time.<\/p>", "f": [["Transport", "TCP 179"], ["Hold time", "90 s"]], "p": [{"f": "b", "t": "c", "m": "OPEN AS 64510", "k": "ctl", "fields": [["Marker", "ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff"], ["Length", "29"], ["Type", "1 OPEN"], ["Version", "4"], ["My AS", "64510"], ["Hold time", "90"], ["BGP identifier", "198.51.100.1"]], "raw": null, "hex": null}, {"f": "c", "t": "b", "m": "OPEN AS 64520", "k": "ctl", "fields": [["Marker", "ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff"], ["Length", "29"], ["Type", "1 OPEN"], ["Version", "4"], ["My AS", "64520"], ["Hold time", "90"], ["BGP identifier", "203.0.113.1"]], "raw": null, "hex": null}, {"f": "b", "t": "c", "m": "KEEPALIVE", "k": "ctl", "fields": [["Marker", "ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff"], ["Length", "19"], ["Type", "4 KEEPALIVE"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Announce a prefix", "tag": "update", "d": "<p>AS 64520 hosts 203.0.113.0/24. It sends an UPDATE with that prefix and AS path 64520.<\/p>", "f": [["Prefix", "203.0.113.0/24"], ["AS path", "64520"]], "p": [{"f": "c", "t": "b", "m": "UPDATE 203.0.113.0/24 path 64520", "k": "data", "fields": [["Marker", "ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff"], ["Length", "52"], ["Type", "2 UPDATE"], ["AS PATH", "64520"], ["NEXT HOP", "203.0.113.1"], ["NLRI", "203.0.113.0/24"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Pass it on", "tag": "update", "d": "<p>AS 64510 adds its own number and tells AS 64500. Now ISP A knows how to reach the prefix, through B.<\/p>", "f": [["AS path at A", "64510 64520"]], "p": [{"f": "b", "t": "a", "m": "UPDATE 203.0.113.0/24 path 64510 64520", "k": "data", "fields": [["Marker", "ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff"], ["Length", "56"], ["Type", "2 UPDATE"], ["AS PATH", "64510 64520"], ["NEXT HOP", "198.51.100.1"], ["NLRI", "203.0.113.0/24"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "A bad announcement", "tag": "hijack", "d": "<p>A misconfigured AS 64666 announces a more specific prefix, 203.0.113.0/25. Routers prefer more specific prefixes, so half the traffic now goes the wrong way.<\/p>", "f": [], "p": [{"f": "bad", "t": "a", "m": "UPDATE 203.0.113.0/25 path 64666", "k": "bad", "fields": [["Marker", "ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff"], ["Length", "52"], ["Type", "2 UPDATE"], ["AS PATH", "64666"], ["NLRI", "203.0.113.0/25"], ["Note", "more specific prefix wins, so traffic goes the wrong way"]], "raw": null, "hex": null}], "on": [], "good": "RPKI route origin validation would mark this announcement invalid, because AS 64666 is not allowed to originate the prefix.", "bad": ["bad"]}], "quiz": [{"type": "fill", "q": "BGP sessions run over TCP port ____.", "a": ["179"], "why": "BGP uses TCP for reliable delivery."}, {"q": "Why did traffic follow the bad announcement?", "opts": ["It had a longer AS path", "It was a more specific prefix, and routers prefer the longest match", "BGP picks at random"], "a": 1, "why": "Longest prefix match wins in routing tables.", "type": "mcq"}], "refs": ["Cloudflare. <a href=\"https://www.cloudflare.com/learning/security/glossary/what-is-bgp/\" target=\"_blank\" rel=\"noopener\">What is BGP?<\/a>", "MANRS. <a href=\"https://manrs.org/\" target=\"_blank\" rel=\"noopener\">Mutually agreed norms for routing security<\/a>."]}, {"id": "dns", "name": "DNS", "full": "Domain Name System", "layer": 7, "cat": "core", "title": "DNS, from a name to an address.", "port": "53", "transport": "UDP and TCP", "lede": "Your device asks a resolver, and the resolver asks the root, the top level domain servers and the authoritative server, then caches the answer.", "overview": "<p>A <b>stub resolver<\/b> on your device asks a <b>recursive resolver<\/b>, often run by your ISP or a public service. The recursive resolver walks the tree. <b>Root<\/b> servers point to the <code>.com<\/code> servers. The <code>.com<\/code> servers point to the domain&#x27;s <b>authoritative<\/b> name servers, which give the final answer. Every answer has a <b>TTL<\/b> that says how long to cache it.<\/p>\n<p>Common record types are A for IPv4, AAAA for IPv6, CNAME for an alias, MX for mail servers and TXT for text such as SPF.<\/p>", "nodes": {"pc": {"label": "Laptop", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 2}, "res": {"label": "Recursive resolver", "sub": "198.51.100.53", "icon": "dns", "x": 3, "y": 2}, "root": {"label": "Root server", "sub": "a.root-servers.net", "icon": "globe", "x": 6, "y": 0}, "tld": {"label": ".com server", "sub": "a.gtld-servers.net", "icon": "dns", "x": 7, "y": 2}, "auth": {"label": "Authoritative server", "sub": "ns1.example.com", "icon": "dns", "x": 6, "y": 4}}, "links": [["pc", "res"], ["res", "root"], ["res", "tld"], ["res", "auth"]], "steps": [{"t": "Ask the resolver", "tag": "query", "d": "<p>The laptop asks its resolver for the A record of www.example.com, with recursion desired.<\/p>", "f": [["Query", "www.example.com A"], ["Flags", "RD"], ["Transport", "UDP 53"]], "p": [{"f": "pc", "t": "res", "m": "query www.example.com A", "k": "req", "fields": [["Transaction ID", "0x1a2b"], ["Flags", "0x0100 standard query, recursion desired"], ["Questions", "1"], ["Name", "www.example.com"], ["QTYPE", "1 A"], ["QCLASS", "1 IN"]], "raw": null, "hex": "1a 2b 01 00 00 01 00 00 00 00 00 00 03 77 77 77 07 65 78 61 6d 70 6c 65 03 63 6f 6d 00 00 01 00 01"}], "on": [], "good": "", "bad": []}, {"t": "Ask a root server", "tag": "iterate", "d": "<p>The resolver has no cached answer. It asks a root server. The root does not know the answer, but refers it to the .com servers.<\/p>", "f": [], "p": [{"f": "res", "t": "root", "m": "query www.example.com A", "k": "req", "fields": [["Transaction ID", "0x5e21"], ["Flags", "0x0000 standard query"], ["Questions", "1"], ["Answer RRs", "0"], ["Authority RRs", "0"], ["Additional RRs", "1"], ["Contains", "www.example.com A"]], "raw": null, "hex": null}, {"f": "root", "t": "res", "m": "referral to .com NS", "k": "res", "fields": [["Transaction ID", "0x5e21"], ["Flags", "0x8000 response"], ["Questions", "1"], ["Answer RRs", "0"], ["Authority RRs", "13"], ["Additional RRs", "11"], ["Contains", "NS a.gtld-servers.net and 12 more for com"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Ask the .com server", "tag": "iterate", "d": "<p>The .com server refers it to the authoritative servers for example.com.<\/p>", "f": [], "p": [{"f": "res", "t": "tld", "m": "query www.example.com A", "k": "req", "fields": [["Transaction ID", "0x77b0"], ["Flags", "0x0000 standard query"], ["Questions", "1"], ["Answer RRs", "0"], ["Authority RRs", "0"], ["Additional RRs", "1"], ["Contains", "www.example.com A"]], "raw": null, "hex": null}, {"f": "tld", "t": "res", "m": "referral to ns1.example.com", "k": "res", "fields": [["Transaction ID", "0x77b0"], ["Flags", "0x8000 response"], ["Questions", "1"], ["Answer RRs", "0"], ["Authority RRs", "2"], ["Additional RRs", "2"], ["Contains", "NS ns1.example.com, NS ns2.example.com, glue A records"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Ask the authoritative server", "tag": "answer", "d": "<p>The authoritative server gives the real answer, 203.0.113.10, with a TTL of 300 seconds.<\/p>", "f": [["Answer", "203.0.113.10"], ["TTL", "300"], ["Flag", "AA authoritative"]], "p": [{"f": "res", "t": "auth", "m": "query www.example.com A", "k": "req", "fields": [["Transaction ID", "0x0c19"], ["Flags", "0x0000 standard query"], ["Questions", "1"], ["Answer RRs", "0"], ["Authority RRs", "0"], ["Additional RRs", "1"], ["Contains", "www.example.com A"]], "raw": null, "hex": null}, {"f": "auth", "t": "res", "m": "A 203.0.113.10 TTL 300", "k": "res", "fields": [["Transaction ID", "0x0c19"], ["Flags", "0x8400 response, authoritative"], ["Questions", "1"], ["Answer RRs", "1"], ["Authority RRs", "0"], ["Additional RRs", "0"], ["Contains", "www.example.com A 203.0.113.10 TTL 300"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Answer and cache", "tag": "cache", "d": "<p>The resolver sends the answer to the laptop and caches it, and the referrals too. The next user who asks within 300 seconds gets an instant answer.<\/p>", "f": [], "p": [{"f": "res", "t": "pc", "m": "A 203.0.113.10", "k": "res", "fields": [["Transaction ID", "0x1a2b"], ["Flags", "0x8180 response, recursion available"], ["Questions", "1"], ["Answer RRs", "1"], ["Authority RRs", "0"], ["Additional RRs", "0"], ["Contains", "www.example.com A 203.0.113.10"]], "raw": null, "hex": null}], "on": [], "good": "Lower TTLs before you move a site. Old answers live in caches until their TTL ends.", "bad": []}], "quiz": [{"q": "Which server gives the final answer for www.example.com?", "opts": ["The root server", "The authoritative server for example.com", "The laptop"], "a": 1, "why": "Root and TLD servers only refer the resolver onward.", "type": "mcq"}, {"type": "fill", "q": "The DNS record type for an IPv6 address is ____.", "a": ["AAAA"], "why": "A is for IPv4, AAAA for IPv6."}], "refs": ["Cloudflare. <a href=\"https://www.cloudflare.com/learning/dns/what-is-dns/\" target=\"_blank\" rel=\"noopener\">What is DNS?<\/a>", "IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc1035\" target=\"_blank\" rel=\"noopener\">RFC 1035, domain names<\/a>."]}, {"id": "dhcp", "name": "DHCP", "full": "Dynamic Host Configuration Protocol", "layer": 7, "cat": "core", "title": "DHCP, a new device gets its network settings.", "port": "67 and 68", "transport": "UDP", "lede": "A device that joins a network knows nothing, not even its own IP address. DHCP gives it an address, the gateway and DNS servers in four messages, called DORA.", "overview": "<p>DORA means <b>Discover, Offer, Request, Acknowledge<\/b>. The client starts with no address, so it broadcasts. The server leases an address for a time, such as 24 hours. The client renews the lease before it ends.<\/p>\n<p>A rogue DHCP server on a network can hand out a fake gateway and DNS server. Switches protect against this with <b>DHCP snooping<\/b>.<\/p>", "nodes": {"pc": {"label": "New laptop", "sub": "0.0.0.0", "icon": "laptop", "x": 0, "y": 1}, "sw": {"label": "Switch", "sub": "", "icon": "switch", "x": 3, "y": 1}, "srv": {"label": "DHCP server", "sub": "192.168.1.1", "icon": "router", "x": 6, "y": 1}}, "links": [["pc", "sw"], ["sw", "srv"]], "steps": [{"t": "Discover", "tag": "dora", "d": "<p>The laptop has no address. It broadcasts a Discover from 0.0.0.0 port 68 to 255.255.255.255 port 67, with its MAC address.<\/p>", "f": [["Src", "0.0.0.0:68"], ["Dst", "255.255.255.255:67"], ["Client MAC", "a4:5e:60:12:34:56"]], "p": [{"f": "pc", "t": "srv", "m": "DHCPDISCOVER (broadcast)", "k": "req", "fields": [["op", "1 BOOTREQUEST"], ["htype", "1"], ["hlen", "6"], ["xid", "0x3903f326"], ["yiaddr", "0.0.0.0"], ["chaddr", "a4:5e:60:12:34:56"], ["Magic cookie", "0x63825363"], ["Message type", "1 DHCPDISCOVER"], ["Src", "0.0.0.0:68"], ["Dst", "255.255.255.255:67"], ["Flags", "0x8000 broadcast"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Offer", "tag": "dora", "d": "<p>The server offers 192.168.1.42 for 24 hours, plus the subnet mask, the gateway and DNS servers.<\/p>", "f": [["Offered IP", "192.168.1.42"], ["Lease", "86400 s"], ["Router", "192.168.1.1"], ["DNS", "192.168.1.1"]], "p": [{"f": "srv", "t": "pc", "m": "DHCPOFFER 192.168.1.42", "k": "res", "fields": [["op", "2 BOOTREPLY"], ["htype", "1"], ["hlen", "6"], ["xid", "0x3903f326"], ["yiaddr", "192.168.1.42"], ["chaddr", "a4:5e:60:12:34:56"], ["Magic cookie", "0x63825363"], ["Message type", "2 DHCPOFFER"], ["Lease time", "86400"], ["Router", "192.168.1.1"], ["DNS", "192.168.1.1"], ["Server ID", "192.168.1.1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Request", "tag": "dora", "d": "<p>The laptop broadcasts a Request for 192.168.1.42. Broadcasting tells any other servers that offered addresses that it chose this one.<\/p>", "f": [], "p": [{"f": "pc", "t": "srv", "m": "DHCPREQUEST 192.168.1.42", "k": "req", "fields": [["op", "1 BOOTREQUEST"], ["htype", "1"], ["hlen", "6"], ["xid", "0x3903f326"], ["yiaddr", "0.0.0.0"], ["chaddr", "a4:5e:60:12:34:56"], ["Magic cookie", "0x63825363"], ["Message type", "3 DHCPREQUEST"], ["Requested IP", "192.168.1.42"], ["Server ID", "192.168.1.1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Acknowledge", "tag": "dora", "d": "<p>The server confirms with an ACK. The laptop sets its address, mask, gateway and DNS. It will renew at half the lease time.<\/p>", "f": [["Renew at", "12 hours"]], "p": [{"f": "srv", "t": "pc", "m": "DHCPACK 192.168.1.42", "k": "res", "fields": [["op", "2 BOOTREPLY"], ["htype", "1"], ["hlen", "6"], ["xid", "0x3903f326"], ["yiaddr", "192.168.1.42"], ["chaddr", "a4:5e:60:12:34:56"], ["Magic cookie", "0x63825363"], ["Message type", "5 DHCPACK"], ["Lease time", "86400"], ["Router", "192.168.1.1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "The four DHCP steps are Discover, Offer, Request and ____.", "a": ["Acknowledge", "ACK", "Acknowledgement"], "why": "DORA."}, {"q": "Why does the client broadcast the first message?", "opts": ["It is faster", "It has no IP address and does not know the server address yet", "Broadcasts are encrypted"], "a": 1, "why": "Broadcast reaches every device on the local network.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc2131\" target=\"_blank\" rel=\"noopener\">RFC 2131, DHCP<\/a>."]}, {"id": "icmp", "name": "ICMP", "full": "Internet Control Message", "layer": 3, "cat": "core", "title": "ICMP, ping and traceroute.", "port": "none", "transport": "IP protocol 1", "lede": "ICMP carries error and test messages for IP. Ping uses echo request and reply. Traceroute uses expiring TTLs to find each router on the path.", "overview": "<p>Common ICMP types are <b>8 echo request<\/b>, <b>0 echo reply<\/b>, <b>3 destination unreachable<\/b> and <b>11 time exceeded<\/b>. Path MTU discovery relies on ICMP too, so blocking all ICMP can break connections in strange ways.<\/p>", "nodes": {"pc": {"label": "Laptop", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "r1": {"label": "Router 1", "sub": "192.168.1.1", "icon": "router", "x": 2, "y": 1}, "r2": {"label": "Router 2", "sub": "198.51.100.1", "icon": "router", "x": 4, "y": 1}, "srv": {"label": "Server", "sub": "203.0.113.10", "icon": "server", "x": 6, "y": 1}}, "links": [["pc", "r1"], ["r1", "r2"], ["r2", "srv"]], "steps": [{"t": "Ping, echo request", "tag": "ping", "d": "<p><code>ping 203.0.113.10<\/code> sends an ICMP echo request, type 8, with an id and a sequence number.<\/p>", "f": [["Type", "8 echo request"], ["Seq", "1"]], "p": [{"f": "pc", "t": "srv", "m": "ICMP echo request seq=1", "k": "req", "fields": [["Type", "8 echo request"], ["Code", "0"], ["Identifier", "0x1234"], ["Sequence", "1"], ["Data", "32 bytes, abcdefghijklmnopqrstuvwabcdefghi"]], "raw": null, "hex": "08 00 3b 27 12 34 00 01 61 62 63 64 65 66 67 68 69 6a 6b 6c 6d 6e 6f 70 71 72 73 74 75 76 77 61 62 63 64 65 66 67 68 69"}], "on": [], "good": "", "bad": []}, {"t": "Echo reply", "tag": "ping", "d": "<p>The server answers with type 0, echo reply. Ping shows the round trip time, such as 24 ms.<\/p>", "f": [["Type", "0 echo reply"], ["RTT", "24 ms"]], "p": [{"f": "srv", "t": "pc", "m": "ICMP echo reply seq=1", "k": "res", "fields": [["Type", "0 echo reply"], ["Code", "0"], ["Identifier", "0x1234"], ["Sequence", "1"], ["Data", "the same 32 bytes sent back"]], "raw": null, "hex": "00 00 43 27 12 34 00 01 61 62 63 64 65 66 67 68 69 6a 6b 6c 6d 6e 6f 70 71 72 73 74 75 76 77 61 62 63 64 65 66 67 68 69"}], "on": [], "good": "", "bad": []}, {"t": "Traceroute, TTL 1", "tag": "traceroute", "d": "<p>Traceroute sends a probe with TTL 1. Router 1 lowers it to 0, drops the packet and sends back time exceeded, type 11. Now we know hop 1.<\/p>", "f": [], "p": [{"f": "pc", "t": "r1", "m": "probe TTL 1", "k": "req", "fields": [["Protocol", "17 UDP"], ["TTL", "1"], ["Dst", "203.0.113.10"], ["Dst port", "33434"]], "raw": null, "hex": null}, {"f": "r1", "t": "pc", "m": "ICMP time exceeded (hop 1)", "k": "ctl", "fields": [["Type", "11 time exceeded"], ["Code", "0"], ["Checksum", "0x4d5a"], ["Src", "192.168.1.1"], ["Inside", "first bytes of the probe that died"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "TTL 2, then 3", "tag": "traceroute", "d": "<p>With TTL 2, router 2 answers. With TTL 3 the probe reaches the server, which answers. The list of answers is the path.<\/p>", "f": [], "p": [{"f": "pc", "t": "r2", "m": "probe TTL 2", "k": "req", "fields": [["Protocol", "17 UDP"], ["TTL", "2"], ["Dst", "203.0.113.10"], ["Dst port", "33435"]], "raw": null, "hex": null}, {"f": "r2", "t": "pc", "m": "ICMP time exceeded (hop 2)", "k": "ctl", "fields": [["Type", "11 time exceeded"], ["Code", "0"], ["Checksum", "0x4d5a"], ["Src", "198.51.100.1"], ["Inside", "first bytes of the probe that died"]], "raw": null, "hex": null}, {"f": "pc", "t": "srv", "m": "probe TTL 3", "k": "req", "fields": [["Protocol", "17 UDP"], ["TTL", "3"], ["Dst", "203.0.113.10"], ["Dst port", "33436"]], "raw": null, "hex": null}, {"f": "srv", "t": "pc", "m": "reply from destination", "k": "res", "fields": [["Type", "3 destination unreachable"], ["Code", "3"], ["Checksum", "0x4d5a"], ["Src", "203.0.113.10"], ["Meaning", "port unreachable, so we reached the end"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "The ICMP type number of an echo request is ____.", "a": ["8"], "why": "Echo reply is type 0."}, {"q": "Which ICMP message does traceroute rely on?", "opts": ["Echo reply only", "Time exceeded from each router", "Redirect"], "a": 1, "why": "Each router that drops a TTL 0 packet reveals itself.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc792\" target=\"_blank\" rel=\"noopener\">RFC 792, ICMP<\/a>."]}, {"id": "igmp", "name": "IGMP", "full": "Multicast and TV channels", "layer": 3, "cat": "core", "title": "IGMP, joining a TV channel on the network.", "port": "none", "transport": "IP protocol 2", "lede": "Multicast sends one stream to many receivers at the same time. IGMP is how a device tells the local router &quot;I want this group&quot;. IPTV uses it.", "overview": "<p>A multicast group is an address such as 239.1.1.1. Hosts send <b>Membership Reports<\/b> to join. Routers send <b>Queries<\/b> to check who still listens. With IGMPv2 and later, hosts send <b>Leave<\/b> messages. Switches use <b>IGMP snooping<\/b> to send the stream only to ports that joined.<\/p>", "nodes": {"tv": {"label": "Set top box", "sub": "192.168.1.50", "icon": "tv", "x": 0, "y": 1}, "tv2": {"label": "Second TV", "sub": "192.168.1.51", "icon": "tv", "x": 0, "y": 3}, "sw": {"label": "Switch", "sub": "IGMP snooping", "icon": "switch", "x": 3, "y": 2}, "rtr": {"label": "Router", "sub": "192.168.1.1", "icon": "router", "x": 6, "y": 2}, "src": {"label": "TV head end", "sub": "239.1.1.1 source", "icon": "server", "x": 8, "y": 2}}, "links": [["tv", "sw"], ["tv2", "sw"], ["sw", "rtr"], ["rtr", "src"]], "steps": [{"t": "Join a channel", "tag": "join", "d": "<p>You select channel 1. The set top box sends a Membership Report for group 239.1.1.1.<\/p>", "f": [["Group", "239.1.1.1"], ["Message", "Membership Report"]], "p": [{"f": "tv", "t": "rtr", "m": "IGMP join 239.1.1.1", "k": "req", "fields": [["Type", "0x16 v2 Membership Report"], ["Max resp time", "0"], ["Checksum", "0x0e2c"], ["Group address", "239.1.1.1"], ["Dst", "239.1.1.1"], ["TTL", "1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The stream flows", "tag": "stream", "d": "<p>The router starts forwarding the group. The switch snoops the join and sends the stream only to the port of the set top box.<\/p>", "f": [], "p": [{"f": "src", "t": "rtr", "m": "multicast video 239.1.1.1", "k": "data", "fields": [["Protocol", "17 UDP"], ["Src", "10.0.0.5"], ["Dst", "239.1.1.1"], ["Dst port", "5004"], ["TTL", "16"]], "raw": null, "hex": null}, {"f": "rtr", "t": "tv", "m": "multicast video", "k": "data", "fields": [["Dst MAC", "01:00:5e:01:01:01"], ["Dst", "239.1.1.1"], ["Payload", "MPEG-TS video"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Query", "tag": "query", "d": "<p>Every so often, the router sends a General Query to 224.0.0.1, all hosts. Members answer to say they still listen.<\/p>", "f": [], "p": [{"f": "rtr", "t": "tv", "m": "General Query", "k": "ctl", "fields": [["Type", "0x11 Membership Query"], ["Max resp time", "100"], ["Group address", "0.0.0.0"], ["Dst", "224.0.0.1"]], "raw": null, "hex": null}, {"f": "tv", "t": "rtr", "m": "Report 239.1.1.1", "k": "ctl", "fields": [["Type", "0x16 v2 Membership Report"], ["Max resp time", "0"], ["Checksum", "0x0e2c"], ["Group address", "239.1.1.1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Leave", "tag": "leave", "d": "<p>You change channel. The box sends a Leave Group to 224.0.0.2. The router checks if anyone else still listens, then stops the stream.<\/p>", "f": [], "p": [{"f": "tv", "t": "rtr", "m": "IGMP leave 239.1.1.1", "k": "ctl", "fields": [["Type", "0x17 Leave Group"], ["Max resp time", "0"], ["Checksum", "0x0e2c"], ["Group address", "239.1.1.1"], ["Dst", "224.0.0.2"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What does IGMP snooping on a switch do?", "opts": ["Encrypts video", "Sends multicast only to ports whose devices joined the group", "Blocks all multicast"], "a": 1, "why": "Without snooping, the switch would flood the stream to every port.", "type": "mcq"}, {"type": "fill", "q": "IPv4 multicast addresses are in the range 224.0.0.0 to ____.", "a": ["239.255.255.255"], "why": "224.0.0.0/4."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc3376\" target=\"_blank\" rel=\"noopener\">RFC 3376, IGMPv3<\/a>."]}, {"id": "ntp", "name": "NTP", "full": "Network Time Protocol", "layer": 7, "cat": "core", "title": "NTP, setting the clock across the network.", "port": "123", "transport": "UDP", "lede": "Logs, certificates and distributed systems need correct time. NTP measures four timestamps to work out both the network delay and the clock error.", "overview": "<p>NTP servers form layers called <b>strata<\/b>. Stratum 0 is a reference clock, such as GPS or an atomic clock. Stratum 1 servers connect to it. Each level below adds one. Clients adjust their clocks smoothly, a little at a time, so time does not jump.<\/p>\n<p>Offset is ((T2 minus T1) plus (T3 minus T4)) divided by 2. Delay is (T4 minus T1) minus (T3 minus T2).<\/p>", "nodes": {"pc": {"label": "Server clock", "sub": "slightly fast", "icon": "clock", "x": 0, "y": 1}, "ntp": {"label": "NTP server", "sub": "stratum 2", "icon": "clock", "x": 4, "y": 1}, "gps": {"label": "Stratum 1 server", "sub": "GPS clock", "icon": "globe", "x": 7, "y": 1}}, "links": [["pc", "ntp"], ["ntp", "gps"]], "steps": [{"t": "Send the request, T1", "tag": "measure", "d": "<p>The client notes its own send time, T1, and sends a request.<\/p>", "f": [["T1", "10:00:00.000 client clock"]], "p": [{"f": "pc", "t": "ntp", "m": "NTP request (T1)", "k": "req", "fields": [["LI VN Mode", "0x23 version 4, mode 3 client"], ["Transmit timestamp T1", "0xece3a1e000000000 in NTP seconds since 1900"]], "raw": null, "hex": "23 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 ec e3 a1 e0 00 00 00 00"}], "on": [], "good": "", "bad": []}, {"t": "Server timestamps, T2 and T3", "tag": "measure", "d": "<p>The server notes when the request arrived, T2, and when it sends the reply, T3. Both are in the server clock.<\/p>", "f": [["T2", "09:59:59.920 server clock"], ["T3", "09:59:59.921 server clock"]], "p": [{"f": "ntp", "t": "pc", "m": "NTP reply (T2, T3)", "k": "res", "fields": [["LI VN Mode", "0x24 version 4, mode 4 server"], ["Stratum", "2"], ["Origin T1", "copied from the request"], ["Receive T2", "09:59:59.920 server clock"], ["Transmit T3", "09:59:59.921 server clock"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Arrival, T4, and the math", "tag": "compute", "d": "<p>The client notes arrival, T4 = 10:00:00.041. Delay is 41 minus 1 = 40 ms. Offset is ((-80) + (-120)) divided by 2 = -100 ms. The client clock is 100 ms fast.<\/p>", "f": [["Delay", "40 ms"], ["Offset", "-100 ms"]], "p": [], "on": [], "good": "", "bad": []}, {"t": "Adjust slowly", "tag": "adjust", "d": "<p>The client slows its clock a little until it matches, called slewing, instead of jumping back. It repeats the exchange every few minutes.<\/p>", "f": [], "p": [], "on": [], "good": "Clocks that jump backwards break software that assumes time only moves forward. That is why NTP prefers to slew.", "bad": []}], "quiz": [{"type": "fill", "q": "NTP uses UDP port ____.", "a": ["123"], "why": "Both client and server use port 123 by default."}, {"q": "What is a stratum 1 server?", "opts": ["A server connected directly to a reference clock such as GPS", "The slowest server", "A client"], "a": 0, "why": "Stratum 0 is the reference clock itself.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc5905\" target=\"_blank\" rel=\"noopener\">RFC 5905, NTPv4<\/a>."]}, {"id": "ethernet", "name": "Ethernet", "full": "Frames and switches", "layer": 2, "cat": "core", "title": "Ethernet, a switch learns where everyone is.", "port": "none", "transport": "-", "lede": "On a local network, data travels in Ethernet frames addressed by MAC address. A switch learns which device sits on which port, then sends each frame only where it must go.", "overview": "<p>A frame has a destination MAC, a source MAC, an <b>EtherType<\/b> that says what is inside, such as 0x0800 for IPv4, the payload and a checksum called the FCS. A switch keeps a <b>MAC address table<\/b>. It learns from source addresses, forwards known destinations to one port and floods unknown ones to all ports.<\/p>", "nodes": {"a": {"label": "PC A", "sub": "aa:aa:aa:00:00:01", "icon": "laptop", "x": 0, "y": 0}, "b": {"label": "PC B", "sub": "bb:bb:bb:00:00:02", "icon": "laptop", "x": 0, "y": 2}, "sw": {"label": "Switch", "sub": "MAC table", "icon": "switch", "x": 3, "y": 1}, "c": {"label": "Printer C", "sub": "cc:cc:cc:00:00:03", "icon": "server", "x": 6, "y": 0}, "d": {"label": "PC D", "sub": "dd:dd:dd:00:00:04", "icon": "laptop", "x": 6, "y": 2}}, "links": [["a", "sw"], ["b", "sw"], ["c", "sw"], ["d", "sw"]], "steps": [{"t": "A sends a frame to C", "tag": "learn", "d": "<p>A sends a frame to C. The switch learns that A is on port 1. It does not know C yet.<\/p>", "f": [["Dst MAC", "cc:cc:cc:00:00:03"], ["Src MAC", "aa:aa:aa:00:00:01"], ["EtherType", "0x0800 IPv4"]], "p": [{"f": "a", "t": "sw", "m": "frame to cc:..:03", "k": "data", "fields": [["Dst MAC", "cc:cc:cc:00:00:03"], ["Src MAC", "aa:aa:aa:00:00:01"], ["EtherType", "0x0800 IPv4"], ["Then", "the IP packet and a 4 byte FCS"]], "raw": null, "hex": "cc cc cc 00 00 03 aa aa aa 00 00 01 08 00"}], "on": [], "good": "", "bad": []}, {"t": "Flood", "tag": "flood", "d": "<p>Unknown destination, so the switch floods the frame to every other port. B and D ignore it, because the MAC is not theirs.<\/p>", "f": [], "p": [{"f": "sw", "t": "b", "m": "frame (flooded)", "k": "data", "fields": [["Dst MAC", "cc:cc:cc:00:00:03"], ["Src MAC", "aa:aa:aa:00:00:01"], ["EtherType", "0x0800 IPv4"], ["Note", "unknown destination, so the switch floods it"]], "raw": null, "hex": null}, {"f": "sw", "t": "c", "m": "frame (flooded)", "k": "data", "fields": [["Dst MAC", "cc:cc:cc:00:00:03"], ["Src MAC", "aa:aa:aa:00:00:01"], ["EtherType", "0x0800 IPv4"], ["Note", "unknown destination, so the switch floods it"]], "raw": null, "hex": null}, {"f": "sw", "t": "d", "m": "frame (flooded)", "k": "data", "fields": [["Dst MAC", "cc:cc:cc:00:00:03"], ["Src MAC", "aa:aa:aa:00:00:01"], ["EtherType", "0x0800 IPv4"], ["Note", "unknown destination, so the switch floods it"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "C replies", "tag": "learn", "d": "<p>C answers A. The switch learns that C is on port 3. It already knows A, so it sends the reply only to port 1.<\/p>", "f": [], "p": [{"f": "c", "t": "sw", "m": "frame to aa:..:01", "k": "data", "fields": [["Dst MAC", "aa:aa:aa:00:00:01"], ["Src MAC", "cc:cc:cc:00:00:03"], ["EtherType", "0x0800 IPv4"]], "raw": null, "hex": null}, {"f": "sw", "t": "a", "m": "frame to A only", "k": "data", "fields": [["Dst MAC", "aa:aa:aa:00:00:01"], ["Src MAC", "cc:cc:cc:00:00:03"], ["EtherType", "0x0800 IPv4"], ["Note", "switch learned A is on port 1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "From now on, direct", "tag": "forward", "d": "<p>Every frame between A and C now goes only to the right port. Entries age out after a few minutes if unused.<\/p>", "f": [["MAC table", "A port 1, C port 3"]], "p": [{"f": "a", "t": "sw", "m": "frame to C", "k": "data", "fields": [["Dst MAC", "cc:cc:cc:00:00:03"], ["Src MAC", "aa:aa:aa:00:00:01"], ["EtherType", "0x0800 IPv4"]], "raw": null, "hex": null}, {"f": "sw", "t": "c", "m": "frame to C only", "k": "data", "fields": [["Dst MAC", "cc:cc:cc:00:00:03"], ["Src MAC", "aa:aa:aa:00:00:01"], ["EtherType", "0x0800 IPv4"], ["Note", "sent only out of port 3"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What does a switch do with a frame for an unknown MAC address?", "opts": ["Drops it", "Floods it to all other ports", "Sends it to the router"], "a": 1, "why": "Then it learns the location from the reply.", "type": "mcq"}, {"type": "fill", "q": "The EtherType value for IPv4 is 0x____.", "a": ["0800", "800"], "why": "0x86DD is IPv6 and 0x0806 is ARP."}], "refs": ["Cisco. <a href=\"https://www.cisco.com/c/en/us/support/docs/lan-switching/spanning-tree-protocol/10556-16.html\" target=\"_blank\" rel=\"noopener\">How LAN switches work<\/a>."]}, {"id": "arp", "name": "ARP", "full": "Address Resolution Protocol", "layer": 2, "cat": "core", "title": "ARP, finding the MAC address for an IP.", "port": "none", "transport": "Ethernet", "lede": "To send an IP packet on the local network, a device needs the MAC address of the next hop. ARP asks the whole network &quot;who has this IP?&quot; and the owner answers.", "overview": "<p>An ARP request is a broadcast, &quot;who has 192.168.1.1, tell 192.168.1.10&quot;. The owner replies directly. The result goes into an <b>ARP cache<\/b> for a few minutes.<\/p>\n<p>ARP has no authentication. An attacker can send fake replies and pretend to be the gateway. This is <b>ARP spoofing<\/b>. Switches defend with Dynamic ARP Inspection.<\/p>", "nodes": {"pc": {"label": "Laptop", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "sw": {"label": "Switch", "sub": "", "icon": "switch", "x": 3, "y": 1}, "gw": {"label": "Gateway", "sub": "192.168.1.1", "icon": "router", "x": 6, "y": 0}, "x": {"label": "Other device", "sub": "192.168.1.77", "icon": "laptop", "x": 6, "y": 2}}, "links": [["pc", "sw"], ["sw", "gw"], ["sw", "x"]], "steps": [{"t": "Who has 192.168.1.1?", "tag": "request", "d": "<p>The laptop wants to send to the internet, through the gateway. It broadcasts an ARP request to ff:ff:ff:ff:ff:ff.<\/p>", "f": [["Dst MAC", "ff:ff:ff:ff:ff:ff"], ["Question", "who has 192.168.1.1"]], "p": [{"f": "pc", "t": "sw", "m": "ARP who has 192.168.1.1?", "k": "req", "fields": [["Dst MAC", "ff:ff:ff:ff:ff:ff"], ["Src MAC", "a4:5e:60:12:34:56"], ["EtherType", "0x0806 ARP"], ["Opcode", "1 request"], ["Sender IP", "192.168.1.10"], ["Target IP", "192.168.1.1"]], "raw": null, "hex": "ff ff ff ff ff ff a4 5e 60 12 34 56 08 06 00 01 08 00 06 04 00 01 a4 5e 60 12 34 56 c0 a8 01 0a 00 00 00 00 00 00 c0 a8 01 01"}, {"f": "sw", "t": "gw", "m": "ARP request (broadcast)", "k": "req", "fields": [["Dst MAC", "ff:ff:ff:ff:ff:ff"], ["Src MAC", "a4:5e:60:12:34:56"], ["EtherType", "0x0806 ARP"], ["Opcode", "1 request"], ["Sender IP", "192.168.1.10"], ["Target IP", "192.168.1.1"]], "raw": null, "hex": "ff ff ff ff ff ff a4 5e 60 12 34 56 08 06 00 01 08 00 06 04 00 01 a4 5e 60 12 34 56 c0 a8 01 0a 00 00 00 00 00 00 c0 a8 01 01"}, {"f": "sw", "t": "x", "m": "ARP request (broadcast)", "k": "req", "fields": [["Dst MAC", "ff:ff:ff:ff:ff:ff"], ["Src MAC", "a4:5e:60:12:34:56"], ["EtherType", "0x0806 ARP"], ["Opcode", "1 request"], ["Sender IP", "192.168.1.10"], ["Target IP", "192.168.1.1"]], "raw": null, "hex": "ff ff ff ff ff ff a4 5e 60 12 34 56 08 06 00 01 08 00 06 04 00 01 a4 5e 60 12 34 56 c0 a8 01 0a 00 00 00 00 00 00 c0 a8 01 01"}], "on": [], "good": "", "bad": []}, {"t": "The owner replies", "tag": "reply", "d": "<p>Only the gateway owns that IP. It replies straight to the laptop with its MAC address.<\/p>", "f": [], "p": [{"f": "gw", "t": "pc", "m": "ARP 192.168.1.1 is at 3c:22:fb:00:00:01", "k": "res", "fields": [["Hardware type", "1 Ethernet"], ["Protocol type", "0x0800 IPv4"], ["Opcode", "2 reply"], ["Sender MAC", "3c:22:fb:00:00:01"], ["Sender IP", "192.168.1.1"], ["Target MAC", "a4:5e:60:12:34:56"], ["Target IP", "192.168.1.10"]], "raw": null, "hex": "00 01 08 00 06 04 00 02 3c 22 fb 00 00 01 c0 a8 01 01 a4 5e 60 12 34 56 c0 a8 01 0a"}], "on": [], "good": "", "bad": []}, {"t": "Cache and send", "tag": "cache", "d": "<p>The laptop saves the answer in its ARP cache and sends the IP packet in a frame to that MAC.<\/p>", "f": [["ARP cache", "192.168.1.1 at 3c:22:fb:00:00:01"]], "p": [{"f": "pc", "t": "gw", "m": "IP packet in frame to 3c:22:fb:..", "k": "data", "fields": [["Dst MAC", "3c:22:fb:00:00:01"], ["Src MAC", "a4:5e:60:12:34:56"], ["EtherType", "0x0800 IPv4"], ["Inside", "IP packet for 203.0.113.10"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "A spoofing attempt", "tag": "attack", "d": "<p>Another device sends unasked ARP replies that say &quot;192.168.1.1 is at my MAC&quot;. If the laptop accepts them, its traffic goes through the attacker. Dynamic ARP Inspection on the switch blocks these replies.<\/p>", "f": [], "p": [{"f": "x", "t": "pc", "m": "fake ARP 192.168.1.1 is at 66:66:..", "k": "bad", "fields": [["Hardware type", "1 Ethernet"], ["Protocol type", "0x0800 IPv4"], ["Opcode", "2 reply, not asked for"], ["Sender MAC", "66:66:66:00:00:66"], ["Sender IP", "192.168.1.1 a lie"], ["Target MAC", "a4:5e:60:12:34:56"], ["Target IP", "192.168.1.10"]], "raw": null, "hex": "00 01 08 00 06 04 00 02 66 66 66 00 00 66 c0 a8 01 01 a4 5e 60 12 34 56 c0 a8 01 0a"}], "on": [], "good": "", "bad": ["x"]}], "quiz": [{"q": "Where does an ARP request go?", "opts": ["Only to the gateway", "To every device on the local network, as a broadcast", "To a DNS server"], "a": 1, "why": "The sender does not know the target MAC yet.", "type": "mcq"}, {"type": "fill", "q": "Sending fake ARP replies to redirect traffic is called ARP ____.", "a": ["spoofing", "poisoning"], "why": "Also called ARP cache poisoning."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc826\" target=\"_blank\" rel=\"noopener\">RFC 826, ARP<\/a>."]}, {"id": "pppoe", "name": "PPPoE", "full": "Broadband logins", "layer": 2, "cat": "core", "title": "PPPoE, a home router logs in to the ISP.", "port": "none", "transport": "Ethernet", "lede": "Many DSL and fibre connections use PPPoE. The router finds the ISP access concentrator, opens a session, logs in with a username and password, and gets a public IP.", "overview": "<p>PPPoE puts PPP, an old point to point protocol, inside Ethernet frames. Discovery has four packets, <b>PADI, PADO, PADR, PADS<\/b>. Then PPP negotiates the link with <b>LCP<\/b>, authenticates with <b>PAP<\/b> or <b>CHAP<\/b>, and gets an IP with <b>IPCP<\/b>. PPPoE adds 8 bytes of headers, so the MTU drops from 1500 to 1492.<\/p>", "nodes": {"rtr": {"label": "Home router", "sub": "PPPoE client", "icon": "router", "x": 0, "y": 1}, "ont": {"label": "Fibre box", "sub": "ONT", "icon": "switch", "x": 3, "y": 1}, "bras": {"label": "Access concentrator", "sub": "ISP BRAS", "icon": "server", "x": 6, "y": 1}, "radius": {"label": "ISP RADIUS", "sub": "accounts", "icon": "key", "x": 8, "y": 1}}, "links": [["rtr", "ont"], ["ont", "bras"], ["bras", "radius"]], "steps": [{"t": "PADI, looking for a server", "tag": "discovery", "d": "<p>The router broadcasts a PPPoE Active Discovery Initiation.<\/p>", "f": [], "p": [{"f": "rtr", "t": "bras", "m": "PADI (broadcast)", "k": "req", "fields": [["Ver type", "0x11"], ["Code", "0x09 PADI"], ["Session ID", "0x0000"], ["Dst MAC", "ff:ff:ff:ff:ff:ff"], ["Tag", "Service-Name any"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "PADO, an offer", "tag": "discovery", "d": "<p>The access concentrator answers with an Offer and its name.<\/p>", "f": [], "p": [{"f": "bras", "t": "rtr", "m": "PADO", "k": "res", "fields": [["Ver type", "0x11"], ["Code", "0x07 PADO"], ["Session ID", "0x0000"], ["Tag", "AC-Name bras-7"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "PADR and PADS, a session", "tag": "discovery", "d": "<p>The router requests a session. The concentrator confirms it with a session id.<\/p>", "f": [["Session ID", "0x2a1f"]], "p": [{"f": "rtr", "t": "bras", "m": "PADR", "k": "req", "fields": [["Ver type", "0x11"], ["Code", "0x19 PADR"], ["Session ID", "0x0000"], ["Tag", "Service-Name internet"]], "raw": null, "hex": null}, {"f": "bras", "t": "rtr", "m": "PADS session 0x2a1f", "k": "res", "fields": [["Ver type", "0x11"], ["Code", "0x65 PADS"], ["Session ID", "0x2a1f"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Log in with CHAP", "tag": "auth", "d": "<p>LCP sets link options. Then CHAP authentication. The concentrator sends a challenge, the router answers with a hash of the challenge and password. The concentrator checks it with RADIUS.<\/p>", "f": [], "p": [{"f": "bras", "t": "rtr", "m": "CHAP challenge", "k": "sec", "fields": [["PPP protocol", "0xc223 CHAP"], ["Code", "1 Challenge"], ["Identifier", "1"], ["Value", "16 random bytes"]], "raw": null, "hex": null}, {"f": "rtr", "t": "bras", "m": "CHAP response (hash)", "k": "sec", "fields": [["PPP protocol", "0xc223 CHAP"], ["Code", "2 Response"], ["Identifier", "1"], ["Value", "MD5 hash of id, password and challenge"], ["Name", "user@isp"]], "raw": null, "hex": null}, {"f": "bras", "t": "radius", "m": "Access-Request", "k": "sec", "fields": [["Code", "1 Access-Request"], ["Identifier", "44"], ["User Name", "user@isp"], ["CHAP Password", "the hash from the router"]], "raw": null, "hex": null}, {"f": "radius", "t": "bras", "m": "Access-Accept", "k": "sec", "fields": [["Code", "2 Access-Accept"], ["Identifier", "44"], ["Framed IP Address", "198.51.100.7"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Get an IP with IPCP", "tag": "ipcp", "d": "<p>IPCP gives the router its public IP and DNS servers. The router is online.<\/p>", "f": [["Public IP", "198.51.100.7"], ["MTU", "1492"]], "p": [{"f": "bras", "t": "rtr", "m": "IPCP 198.51.100.7", "k": "res", "fields": [["PPP protocol", "0x8021 IPCP"], ["Code", "3 Configure-Nak"], ["IP Address", "198.51.100.7"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "num", "q": "What is the usual MTU on a PPPoE link, in bytes?", "a": 1492, "tol": 0, "unit": "bytes", "why": "1500 minus 8 bytes of PPPoE and PPP headers."}, {"q": "Which PPP part assigns the IP address?", "opts": ["LCP", "IPCP", "CHAP"], "a": 1, "why": "LCP sets up the link, CHAP authenticates, IPCP configures IP.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc2516\" target=\"_blank\" rel=\"noopener\">RFC 2516, PPPoE<\/a>."]}, {"id": "tls", "name": "TLS/SSL", "full": "Transport Layer Security", "layer": 6, "cat": "security", "title": "TLS 1.3, two parties agree on secret keys in public.", "port": "any, such as 443", "transport": "TCP", "lede": "TLS lets two machines that have never met agree on secret keys while an attacker watches, and lets the client prove who the server is.", "overview": "<p>SSL is the old name. SSL 2.0 and 3.0 and TLS 1.0 and 1.1 are broken or deprecated. Use TLS 1.2 or 1.3.<\/p>\n<p>TLS 1.3 uses <b>ephemeral Diffie Hellman<\/b>, usually X25519. Each side sends a public key share. Each side combines its own private key with the other public share and gets the same secret. An eavesdropper cannot compute it. New keys every session give <b>forward secrecy<\/b>. A stolen server key later cannot decrypt old traffic.<\/p>", "nodes": {"c": {"label": "Client", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "eve": {"label": "Eavesdropper", "sub": "sees all bytes", "icon": "user", "x": 3, "y": 3}, "s": {"label": "Server", "sub": "203.0.113.20", "icon": "server", "x": 6, "y": 1}}, "links": [["c", "s"], ["c", "eve"], ["eve", "s"]], "steps": [{"t": "ClientHello with a key share", "tag": "hello", "d": "<p>The client sends random bytes, the cipher suites it supports and an X25519 public key share. It guesses the group the server will pick, which saves a round trip.<\/p>", "f": [["Version", "1.3"], ["Cipher suite offer", "TLS_AES_128_GCM_SHA256, TLS_CHACHA20_POLY1305_SHA256"], ["Key share", "X25519 public key"]], "p": [{"f": "c", "t": "s", "m": "ClientHello + key share", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "512"], ["Handshake type", "0x01 ClientHello"], ["Legacy version", "0x0303"], ["Cipher suites", "0x1301, 0x1303"], ["Supported versions", "0x0304 TLS 1.3"], ["Key share", "X25519, 32 bytes"], ["Server name", "shop.example"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "ServerHello with a key share", "tag": "hello", "d": "<p>The server picks a suite and sends its own public share. Now both sides compute the same shared secret with Diffie Hellman. The eavesdropper saw both public shares, but cannot compute the secret.<\/p>", "f": [["Chosen suite", "TLS_AES_128_GCM_SHA256"], ["Shared secret", "known to client and server only"]], "p": [{"f": "s", "t": "c", "m": "ServerHello + key share", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "122"], ["Handshake type", "0x02 ServerHello"], ["Cipher suite", "0x1301 TLS_AES_128_GCM_SHA256"], ["Supported versions", "0x0304 TLS 1.3"], ["Key share", "X25519, 32 bytes"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Encrypted handshake", "tag": "auth", "d": "<p>From here everything is encrypted with handshake keys. The server sends EncryptedExtensions, its Certificate, a CertificateVerify signature over the handshake so far, and Finished, a MAC over the whole handshake.<\/p>", "f": [], "p": [{"f": "s", "t": "c", "m": "EncryptedExtensions, Certificate", "k": "sec", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "2890"], ["Payload", "EncryptedExtensions and Certificate, encrypted with handshake keys"]], "raw": null, "hex": null}, {"f": "s", "t": "c", "m": "CertificateVerify, Finished", "k": "sec", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "330"], ["Payload", "CertificateVerify and server Finished, encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Client checks and finishes", "tag": "auth", "d": "<p>The client checks the certificate chain and name, checks the signature with the public key in the certificate, then sends its own Finished. Any change by an attacker would break the Finished MAC.<\/p>", "f": [], "p": [{"f": "c", "t": "s", "m": "Finished", "k": "sec", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "74"], ["Payload", "client Finished, encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Application data", "tag": "data", "d": "<p>Both sides derive traffic keys from the shared secret with HKDF and send application data protected with AES GCM. The eavesdropper sees only random looking records.<\/p>", "f": [], "p": [{"f": "c", "t": "s", "m": "application data (encrypted)", "k": "data", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "517"], ["Payload", "request bytes plus a 16 byte tag"]], "raw": null, "hex": null}, {"f": "s", "t": "c", "m": "application data (encrypted)", "k": "data", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "1400"], ["Payload", "response bytes plus a 16 byte tag"]], "raw": null, "hex": null}, {"f": "eve", "t": "eve", "m": "cannot read", "k": "bad", "fields": [["Sees", "IP addresses, ports, sizes, timing, server name"], ["Cannot see", "content, cookies, passwords"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": ["eve"]}], "quiz": [{"q": "What gives TLS 1.3 forward secrecy?", "opts": ["Long certificates", "New ephemeral Diffie Hellman keys for every session", "Passwords"], "a": 1, "why": "Old sessions stay safe even if the server private key leaks later.", "type": "mcq"}, {"type": "fill", "q": "The last handshake message, a MAC over the whole handshake, is called ____.", "a": ["Finished"], "why": "It detects any tampering with earlier messages."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc8446\" target=\"_blank\" rel=\"noopener\">RFC 8446, TLS 1.3<\/a>.", "Michael Driscoll. <a href=\"https://tls13.xargs.org/\" target=\"_blank\" rel=\"noopener\">The illustrated TLS 1.3 connection<\/a>."]}, {"id": "ssh", "name": "SSH", "full": "Secure Shell", "layer": 7, "cat": "security", "title": "SSH, a secure login to a remote machine.", "port": "22", "transport": "TCP", "lede": "SSH sets up an encrypted channel, proves the server is the one you know, logs you in with a key, and runs your commands. Watch each stage.", "overview": "<p>SSH has three layers. The <b>transport<\/b> layer does key exchange, encryption and server authentication. The <b>user authentication<\/b> layer logs you in, best with a public key. The <b>connection<\/b> layer carries channels, such as a shell, a command, port forwarding or SFTP.<\/p>\n<p>The first time you connect, SSH shows the server key fingerprint. If you accept, it saves it in <code>known_hosts<\/code>. If it ever changes, SSH warns you loudly. That may be an attack.<\/p>", "nodes": {"me": {"label": "Your laptop", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "srv": {"label": "Server", "sub": "web-1 203.0.113.30", "icon": "terminal", "x": 6, "y": 1}}, "links": [["me", "srv"]], "steps": [{"t": "Version exchange", "tag": "hello", "d": "<p>After TCP connects to port 22, both sides send a version line in plain text.<\/p>", "f": [], "p": [{"f": "srv", "t": "me", "m": "SSH-2.0-OpenSSH_9.6", "k": "ctl", "fields": [], "raw": "SSH-2.0-OpenSSH_9.6\r\n", "hex": null}, {"f": "me", "t": "srv", "m": "SSH-2.0-OpenSSH_9.8", "k": "ctl", "fields": [], "raw": "SSH-2.0-OpenSSH_9.8\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Algorithm negotiation", "tag": "kex", "d": "<p>Each side sends KEXINIT with its list of key exchange, host key, cipher and MAC algorithms. They pick the first match from the client list.<\/p>", "f": [["Key exchange", "curve25519-sha256"], ["Host key", "ssh-ed25519"], ["Cipher", "chacha20-poly1305"]], "p": [{"f": "me", "t": "srv", "m": "KEXINIT", "k": "sec", "fields": [["Packet length", "1500"], ["Padding length", "6"], ["Message number", "20 KEXINIT"], ["Contents", "curve25519-sha256, ssh-ed25519, chacha20-poly1305@openssh.com, and more choices"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "KEXINIT", "k": "sec", "fields": [["Packet length", "1080"], ["Padding length", "6"], ["Message number", "20 KEXINIT"], ["Contents", "the server's list of choices, the first match wins"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Key exchange and host key", "tag": "kex", "d": "<p>The client sends an ephemeral public key. The server answers with its ephemeral key, its long term host key and a signature. The client checks the host key against <code>known_hosts<\/code>. Both sides send NEWKEYS and switch to encryption.<\/p>", "f": [["Host key fingerprint", "SHA256:k3X...9Qw"], ["known_hosts", "match"]], "p": [{"f": "me", "t": "srv", "m": "KEX_ECDH_INIT (ephemeral key)", "k": "sec", "fields": [["Packet length", "44"], ["Padding length", "6"], ["Message number", "30 KEX_ECDH_INIT"], ["Contents", "client ephemeral public key, 32 bytes"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "KEX_ECDH_REPLY (host key, signature)", "k": "sec", "fields": [["Packet length", "188"], ["Padding length", "6"], ["Message number", "31 KEX_ECDH_REPLY"], ["Contents", "host key, server ephemeral key, signature over the exchange hash"]], "raw": null, "hex": null}, {"f": "me", "t": "srv", "m": "NEWKEYS", "k": "sec", "fields": [["Packet length", "12"], ["Padding length", "6"], ["Message number", "21 NEWKEYS"], ["Contents", "from now on, everything is encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Public key login", "tag": "auth", "d": "<p>The client asks to log in as deploy with its ed25519 key. It signs data tied to this session with the private key. The server checks the signature with the public key in <code>authorized_keys<\/code>. The private key never leaves the laptop.<\/p>", "f": [], "p": [{"f": "me", "t": "srv", "m": "USERAUTH_REQUEST deploy publickey + signature", "k": "sec", "fields": [["Packet length", "588"], ["Padding length", "6"], ["Message number", "50 USERAUTH_REQUEST"], ["Contents", "user deploy, method publickey, ssh-ed25519 key and signature, encrypted"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "USERAUTH_SUCCESS", "k": "res", "fields": [["Packet length", "12"], ["Padding length", "6"], ["Message number", "52 USERAUTH_SUCCESS"], ["Contents", "encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Open a channel and run a command", "tag": "channel", "d": "<p>The client opens a session channel and asks to run <code>uptime<\/code>. The output comes back in the encrypted channel.<\/p>", "f": [], "p": [{"f": "me", "t": "srv", "m": "CHANNEL_OPEN session, exec uptime", "k": "req", "fields": [["Packet length", "44"], ["Padding length", "6"], ["Message number", "90 CHANNEL_OPEN"], ["Contents", "session, then 98 CHANNEL_REQUEST exec uptime"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "CHANNEL_DATA  12:01 up 41 days", "k": "res", "fields": [["Packet length", "60"], ["Padding length", "6"], ["Message number", "94 CHANNEL_DATA"], ["Contents", "12:01 up 41 days"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "SSH uses TCP port ____ by default.", "a": ["22"], "why": "Some teams move it, but 22 is standard."}, {"q": "SSH warns that the host key changed. What should you do?", "opts": ["Delete known_hosts and continue", "Stop and check with the server owner, because it may be an attack or a rebuilt server", "Ignore it"], "a": 1, "why": "A changed key can mean a man in the middle.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc4253\" target=\"_blank\" rel=\"noopener\">RFC 4253, SSH transport layer<\/a>.", "OpenSSH. <a href=\"https://www.openssh.com/manual.html\" target=\"_blank\" rel=\"noopener\">Manual pages<\/a>."]}, {"id": "sftp", "name": "SFTP and SCP", "full": "File transfer over SSH", "layer": 7, "cat": "security", "title": "SFTP, copying files inside SSH.", "port": "22", "transport": "SSH", "lede": "SFTP runs as a subsystem inside an SSH connection, so the files and the login are encrypted. It is not FTP over TLS. It is a different protocol.", "overview": "<p>After SSH logs you in, the client asks for the <b>sftp subsystem<\/b>. Then it sends binary SFTP packets, such as OPEN, READ, WRITE and CLOSE, each with a request id.<\/p>\n<p><b>SCP<\/b> is an older tool for copying over SSH. Since OpenSSH 9.0, the <code>scp<\/code> command uses the SFTP protocol by default.<\/p>", "nodes": {"me": {"label": "Your laptop", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "srv": {"label": "File server", "sub": "203.0.113.31", "icon": "folder", "x": 6, "y": 1}}, "links": [["me", "srv"]], "steps": [{"t": "SSH first", "tag": "ssh", "d": "<p>The client does the full SSH handshake and logs in with a key, exactly as in the SSH animation.<\/p>", "f": [], "p": [{"f": "me", "t": "srv", "m": "SSH handshake and login", "k": "sec", "fields": [["Layer", "SSH"], ["Steps", "version, key exchange, user auth"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Start the sftp subsystem", "tag": "start", "d": "<p>The client opens a session channel and requests the <code>sftp<\/code> subsystem. Then it sends INIT with version 3. The server answers VERSION 3.<\/p>", "f": [], "p": [{"f": "me", "t": "srv", "m": "subsystem sftp", "k": "req", "fields": [["SSH message", "98 CHANNEL_REQUEST"], ["Request", "subsystem"], ["Name", "sftp"]], "raw": null, "hex": null}, {"f": "me", "t": "srv", "m": "SSH_FXP_INIT v3", "k": "req", "fields": [["Length", "5"], ["Type", "1 SSH_FXP_INIT"], ["Version", "3"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "SSH_FXP_VERSION 3", "k": "res", "fields": [["Length", "5"], ["Type", "2 SSH_FXP_VERSION"], ["Version", "3"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Open the file", "tag": "transfer", "d": "<p>The client opens <code>/reports/may.csv<\/code> for reading. The server answers with a handle, a short id for the open file.<\/p>", "f": [], "p": [{"f": "me", "t": "srv", "m": "SSH_FXP_OPEN /reports/may.csv", "k": "req", "fields": [["Length", "38"], ["Type", "3 SSH_FXP_OPEN"], ["Request ID", "1"], ["Path", "/reports/may.csv"], ["Flags", "0x00000001 READ"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "SSH_FXP_HANDLE h1", "k": "res", "fields": [["Length", "11"], ["Type", "102 SSH_FXP_HANDLE"], ["Request ID", "1"], ["Handle", "h1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Read in pieces", "tag": "transfer", "d": "<p>The client sends several READ requests at once, each for a piece of the file. The server answers with DATA. Many requests in flight keep the transfer fast.<\/p>", "f": [], "p": [{"f": "me", "t": "srv", "m": "SSH_FXP_READ h1 offset 0", "k": "req", "fields": [["Length", "23"], ["Type", "5 SSH_FXP_READ"], ["Request ID", "2"], ["Handle", "h1"], ["Offset", "0"], ["Len", "32768"]], "raw": null, "hex": null}, {"f": "me", "t": "srv", "m": "SSH_FXP_READ h1 offset 32768", "k": "req", "fields": [["Length", "23"], ["Type", "5 SSH_FXP_READ"], ["Request ID", "3"], ["Handle", "h1"], ["Offset", "32768"], ["Len", "32768"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "SSH_FXP_DATA", "k": "data", "fields": [["Length", "32777"], ["Type", "103 SSH_FXP_DATA"], ["Request ID", "2"], ["Data", "32768 bytes"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "SSH_FXP_DATA", "k": "data", "fields": [["Length", "9817"], ["Type", "103 SSH_FXP_DATA"], ["Request ID", "3"], ["Data", "9808 bytes, end of file"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Close", "tag": "close", "d": "<p>The client closes the handle. The server answers STATUS OK.<\/p>", "f": [], "p": [{"f": "me", "t": "srv", "m": "SSH_FXP_CLOSE h1", "k": "req", "fields": [["Length", "11"], ["Type", "4 SSH_FXP_CLOSE"], ["Request ID", "4"], ["Handle", "h1"]], "raw": null, "hex": null}, {"f": "srv", "t": "me", "m": "SSH_FXP_STATUS OK", "k": "res", "fields": [["Length", "21"], ["Type", "101 SSH_FXP_STATUS"], ["Request ID", "4"], ["Code", "0 SSH_FX_OK"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "Is SFTP the same as FTP over TLS?", "opts": ["Yes", "No, SFTP is a separate protocol that runs inside SSH"], "a": 1, "why": "FTP over TLS is called FTPS.", "type": "mcq"}, {"type": "fill", "q": "SFTP runs as a ____ of an SSH connection.", "a": ["subsystem"], "why": "The sftp subsystem."}], "refs": ["OpenSSH. <a href=\"https://www.openssh.com/txt/release-9.0\" target=\"_blank\" rel=\"noopener\">OpenSSH 9.0 release notes, scp uses SFTP<\/a>.", "IETF draft. <a href=\"https://datatracker.ietf.org/doc/html/draft-ietf-secsh-filexfer-02\" target=\"_blank\" rel=\"noopener\">SSH File Transfer Protocol, version 3<\/a>."]}, {"id": "doh", "name": "DNS over HTTPS", "full": "Private DNS lookups", "layer": 7, "cat": "security", "title": "DNS over HTTPS, hiding your lookups.", "port": "443", "transport": "HTTPS", "lede": "Normal DNS travels in plain text, so anyone on the path sees which sites you look up. DoH sends DNS questions inside HTTPS to a resolver you trust.", "overview": "<p>DoH is defined in RFC 8484. The DNS message itself is the same binary format. It travels in an HTTPS POST or GET to a path such as <code>/dns-query<\/code>, with content type <code>application/dns-message<\/code>. <b>DNS over TLS<\/b>, DoT, does the same over TLS on port 853.<\/p>\n<p>DoH hides lookups from the local network and the ISP, but the DoH resolver still sees them. Choose one you trust.<\/p>", "nodes": {"pc": {"label": "Browser", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "isp": {"label": "Local network and ISP", "sub": "can watch", "icon": "router", "x": 3, "y": 1}, "doh": {"label": "DoH resolver", "sub": "198.51.100.53", "icon": "dns", "x": 6, "y": 1}}, "links": [["pc", "isp"], ["isp", "doh"]], "steps": [{"t": "Plain DNS, for comparison", "tag": "compare", "d": "<p>With normal DNS, the question &quot;where is clinic.example&quot; crosses the local network in plain text on UDP 53. Anyone on the path can read and even change it.<\/p>", "f": [], "p": [{"f": "pc", "t": "isp", "m": "DNS query clinic.example (plain)", "k": "bad", "fields": [["Transaction ID", "0x3f10"], ["Flags", "0x0100 standard query, recursion desired"], ["Questions", "1"], ["Answer RRs", "0"], ["Authority RRs", "0"], ["Additional RRs", "0"], ["Contains", "clinic.example A, readable by anyone on the path"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": ["isp"]}, {"t": "Open HTTPS to the resolver", "tag": "tls", "d": "<p>With DoH, the browser opens a TLS connection to its DoH resolver on port 443, or reuses one.<\/p>", "f": [], "p": [{"f": "pc", "t": "doh", "m": "TLS handshake", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "512"], ["Handshake type", "0x01 ClientHello"], ["Server name", "dns.example"], ["ALPN", "h2"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Ask inside HTTPS", "tag": "query", "d": "<p>The browser sends the DNS message as the body of a POST. The network sees only encrypted HTTPS to the resolver.<\/p>", "f": [["Method", "POST"], ["Path", "/dns-query"], ["Content-Type", "application/dns-message"]], "p": [{"f": "pc", "t": "doh", "m": "POST /dns-query (encrypted)", "k": "sec", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "180"], ["Payload", "HTTP/2 POST /dns-query, content-type application/dns-message, the DNS question"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Answer inside HTTPS", "tag": "answer", "d": "<p>The resolver answers with the DNS response in the body. The browser connects to the site as usual.<\/p>", "f": [], "p": [{"f": "doh", "t": "pc", "m": "200 application/dns-message (encrypted)", "k": "res", "fields": [["Content type", "0x17 application data"], ["Version", "0x0303"], ["Length", "140"], ["Payload", "HTTP/2 200, content-type application/dns-message, the DNS answer"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "The content type of a DoH message is application/____.", "a": ["dns-message"], "why": "The body is a normal binary DNS message."}, {"q": "Who can still see your DoH lookups?", "opts": ["Your ISP", "The DoH resolver you send them to", "Nobody"], "a": 1, "why": "DoH moves trust to the resolver.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc8484\" target=\"_blank\" rel=\"noopener\">RFC 8484, DNS queries over HTTPS<\/a>."]}, {"id": "dnssec", "name": "DNSSEC", "full": "Signed DNS answers", "layer": 7, "cat": "security", "title": "DNSSEC, a chain of signatures from the root.", "port": "53", "transport": "UDP and TCP", "lede": "DNSSEC lets a resolver check that a DNS answer really comes from the domain owner and was not changed. It signs answers. It does not hide them.", "overview": "<p>Each signed zone has keys in <b>DNSKEY<\/b> records and signatures in <b>RRSIG<\/b> records. The parent zone holds a <b>DS<\/b> record, a hash of the child key. So the root vouches for .com, .com vouches for example.com, and so on. The resolver trusts only the root key, called the <b>trust anchor<\/b>.<\/p>\n<p>DNSSEC gives integrity and authenticity, not privacy. For privacy, use DoH or DoT.<\/p>", "nodes": {"res": {"label": "Validating resolver", "sub": "trusts root key", "icon": "dns", "x": 0, "y": 2}, "root": {"label": "Root zone", "sub": "DNSKEY", "icon": "globe", "x": 3, "y": 0}, "com": {"label": ".com zone", "sub": "DS and DNSKEY", "icon": "dns", "x": 6, "y": 1}, "ex": {"label": "example.com zone", "sub": "DS and DNSKEY", "icon": "dns", "x": 6, "y": 3}, "bad": {"label": "Forged answer", "sub": "attacker", "icon": "user", "x": 3, "y": 4}}, "links": [["res", "root"], ["res", "com"], ["res", "ex"], ["res", "bad"]], "steps": [{"t": "Get the answer and its signature", "tag": "query", "d": "<p>The resolver asks for www.example.com A with the DO bit set. The answer comes with an RRSIG signed by the example.com zone key.<\/p>", "f": [], "p": [{"f": "res", "t": "ex", "m": "query A, DO bit", "k": "req", "fields": [["Transaction ID", "0x2b1c"], ["Flags", "0x0010 checking disabled off, EDNS DO bit set"], ["Questions", "1"], ["Answer RRs", "0"], ["Additional RRs", "1"], ["Contains", "example.com A"]], "raw": null, "hex": null}, {"f": "ex", "t": "res", "m": "A 203.0.113.10 + RRSIG", "k": "res", "fields": [["Transaction ID", "0x2b1c"], ["Flags", "0x8400 authoritative"], ["Questions", "1"], ["Answer RRs", "2"], ["Additional RRs", "1"], ["Contains", "A 203.0.113.10 and RRSIG type 46"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Check the zone key", "tag": "chain", "d": "<p>The resolver gets the example.com DNSKEY and checks the RRSIG with it. Then it must trust that key.<\/p>", "f": [], "p": [{"f": "res", "t": "ex", "m": "query DNSKEY", "k": "req", "fields": [["Transaction ID", "0x2b1d"], ["Flags", "0x0000 query"], ["Questions", "1"], ["Answer RRs", "0"], ["Additional RRs", "1"], ["Contains", "example.com DNSKEY"]], "raw": null, "hex": null}, {"f": "ex", "t": "res", "m": "DNSKEY + RRSIG", "k": "res", "fields": [["Transaction ID", "0x2b1d"], ["Flags", "0x8400 authoritative"], ["Questions", "1"], ["Answer RRs", "3"], ["Additional RRs", "1"], ["Contains", "DNSKEY 256 ZSK, DNSKEY 257 KSK, RRSIG"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Walk up the chain", "tag": "chain", "d": "<p>The .com zone has a DS record, a hash of the example.com key, signed by .com. The root has a DS for .com, signed by the root key, which the resolver already trusts.<\/p>", "f": [], "p": [{"f": "res", "t": "com", "m": "query DS example.com", "k": "req", "fields": [["Transaction ID", "0x2b1e"], ["Flags", "0x0000 query"], ["Questions", "1"], ["Answer RRs", "0"], ["Additional RRs", "1"], ["Contains", "example.com DS"]], "raw": null, "hex": null}, {"f": "com", "t": "res", "m": "DS + RRSIG", "k": "res", "fields": [["Transaction ID", "0x2b1e"], ["Flags", "0x8400 authoritative"], ["Questions", "1"], ["Answer RRs", "2"], ["Additional RRs", "1"], ["Contains", "DS key tag 31406 SHA-256 digest, RRSIG"]], "raw": null, "hex": null}, {"f": "res", "t": "root", "m": "query DS com", "k": "req", "fields": [["Transaction ID", "0x2b1f"], ["Flags", "0x0000 query"], ["Questions", "1"], ["Answer RRs", "0"], ["Additional RRs", "1"], ["Contains", "com DS"]], "raw": null, "hex": null}, {"f": "root", "t": "res", "m": "DS + RRSIG", "k": "res", "fields": [["Transaction ID", "0x2b1f"], ["Flags", "0x8400 authoritative"], ["Questions", "1"], ["Answer RRs", "2"], ["Additional RRs", "1"], ["Contains", "DS for com, RRSIG by the root key"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Answer is valid", "tag": "valid", "d": "<p>Every link checks out. The resolver returns the answer with the AD flag, authenticated data.<\/p>", "f": [], "p": [], "on": [], "good": "", "bad": []}, {"t": "A forged answer fails", "tag": "attack", "d": "<p>An attacker injects a fake answer. It has no valid signature from the zone key, so the resolver rejects it and returns SERVFAIL instead of a lie.<\/p>", "f": [], "p": [{"f": "bad", "t": "res", "m": "A 198.51.100.66 (no valid RRSIG)", "k": "bad", "fields": [["Transaction ID", "0x2b1c"], ["Flags", "0x8400 authoritative"], ["Questions", "1"], ["Answer RRs", "1"], ["Additional RRs", "1"], ["Contains", "A 198.51.100.66 with no valid RRSIG, so it fails validation"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": ["bad"]}], "quiz": [{"q": "Does DNSSEC encrypt DNS?", "opts": ["Yes", "No, it signs answers so they cannot be forged"], "a": 1, "why": "Use DoH or DoT for privacy.", "type": "mcq"}, {"type": "fill", "q": "The record in the parent zone that holds a hash of the child key is the ____ record.", "a": ["DS"], "why": "Delegation Signer."}], "refs": ["Cloudflare. <a href=\"https://www.cloudflare.com/learning/dns/dnssec/how-dnssec-works/\" target=\"_blank\" rel=\"noopener\">How DNSSEC works<\/a>.", "IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc4033\" target=\"_blank\" rel=\"noopener\">RFC 4033, DNSSEC introduction<\/a>."]}, {"id": "wifi", "name": "Wi-Fi", "full": "Joining a network (WPA2)", "layer": 2, "cat": "security", "title": "Joining a WPA2 Wi-Fi network.", "port": "none", "transport": "802.11", "lede": "Your phone finds the network, associates, then proves it knows the password with the 4 way handshake. The password itself never goes over the air.", "overview": "<p>In WPA2 Personal, both sides turn the password and the network name into the same <b>PMK<\/b>, using PBKDF2 with 4096 rounds. The <b>4 way handshake<\/b> mixes the PMK with two random numbers, ANonce and SNonce, into a fresh <b>PTK<\/b> for this session. A <b>GTK<\/b> protects broadcast traffic.<\/p>\n<p>Weakness. Anyone who captures the 4 way handshake can try password guesses offline. Use a long password, or WPA3.<\/p>", "nodes": {"phone": {"label": "Phone", "sub": "a4:..:01", "icon": "phone", "x": 0, "y": 1}, "ap": {"label": "Access point", "sub": "SSID HomeNet", "icon": "ap", "x": 4, "y": 1}, "eve": {"label": "Listener", "sub": "nearby", "icon": "user", "x": 4, "y": 3}}, "links": [["phone", "ap"], ["ap", "eve"], ["phone", "eve"]], "steps": [{"t": "Find the network", "tag": "discover", "d": "<p>The access point sends beacons about 10 times a second with the SSID and its security settings. The phone can also send a probe request.<\/p>", "f": [], "p": [{"f": "ap", "t": "phone", "m": "Beacon SSID HomeNet, WPA2", "k": "ctl", "fields": [["Frame control", "0x8000 management, beacon"], ["BSSID", "3c:22:fb:aa:00:01"], ["SSID", "HomeNet"], ["RSN", "WPA2, AES-CCMP, PSK"], ["Interval", "100 TU"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Authenticate and associate", "tag": "join", "d": "<p>An open system authentication exchange, then association. These do not check the password. They just start the link.<\/p>", "f": [], "p": [{"f": "phone", "t": "ap", "m": "Authentication request", "k": "ctl", "fields": [["Frame control", "0xb000 management, authentication"], ["Algorithm", "0 open system"], ["Sequence", "1"]], "raw": null, "hex": null}, {"f": "ap", "t": "phone", "m": "Authentication response", "k": "ctl", "fields": [["Frame control", "0xb000 management, authentication"], ["Algorithm", "0 open system"], ["Sequence", "2"], ["Status", "0 success"]], "raw": null, "hex": null}, {"f": "phone", "t": "ap", "m": "Association request", "k": "ctl", "fields": [["Frame control", "0x0000 management, association request"], ["SSID", "HomeNet"], ["RSN", "WPA2 PSK, CCMP"]], "raw": null, "hex": null}, {"f": "ap", "t": "phone", "m": "Association response", "k": "ctl", "fields": [["Frame control", "0x1000 management, association response"], ["Status", "0 success"], ["AID", "1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "4 way handshake, messages 1 and 2", "tag": "handshake", "d": "<p>The AP sends a random ANonce. The phone makes a random SNonce, computes the PTK from the PMK, both nonces and both MAC addresses, and sends SNonce with a MIC. The MIC proves it knows the PMK.<\/p>", "f": [], "p": [{"f": "ap", "t": "phone", "m": "M1 ANonce", "k": "sec", "fields": [["EtherType", "0x888e EAPOL"], ["Descriptor", "2 RSN"], ["Key info", "0x008a"], ["Message", "M1"], ["Replay counter", "1"], ["ANonce", "32 random bytes"]], "raw": null, "hex": null}, {"f": "phone", "t": "ap", "m": "M2 SNonce + MIC", "k": "sec", "fields": [["EtherType", "0x888e EAPOL"], ["Descriptor", "2 RSN"], ["Key info", "0x010a"], ["Message", "M2"], ["Replay counter", "1"], ["SNonce", "32 random bytes"], ["MIC", "16 bytes"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Messages 3 and 4", "tag": "handshake", "d": "<p>The AP checks the MIC, sends the GTK encrypted with the new keys, and the phone confirms. Both install the keys. Traffic is now encrypted with AES CCMP.<\/p>", "f": [], "p": [{"f": "ap", "t": "phone", "m": "M3 GTK (encrypted) + MIC", "k": "sec", "fields": [["EtherType", "0x888e EAPOL"], ["Descriptor", "2 RSN"], ["Key info", "0x13ca"], ["Message", "M3"], ["Replay counter", "2"], ["Key data", "GTK, encrypted"], ["MIC", "16 bytes"]], "raw": null, "hex": null}, {"f": "phone", "t": "ap", "m": "M4 ACK", "k": "sec", "fields": [["EtherType", "0x888e EAPOL"], ["Descriptor", "2 RSN"], ["Key info", "0x030a"], ["Message", "M4"], ["Replay counter", "2"], ["MIC", "16 bytes"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The offline guessing risk", "tag": "risk", "d": "<p>A listener who captured M1 and M2 can try millions of password guesses offline and check each against the MIC. Short passwords fall quickly.<\/p>", "f": [], "p": [{"f": "eve", "t": "eve", "m": "offline guesses vs captured MIC", "k": "bad", "fields": [["Attack", "offline dictionary"], ["Needs", "M1 and M2 from the air"], ["Speed", "limited only by the attacker's hardware"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": ["eve"]}], "quiz": [{"q": "Does the Wi-Fi password travel over the air in WPA2?", "opts": ["Yes, encrypted", "No, both sides derive keys from it and prove it with a MIC"], "a": 1, "why": "The handshake proves knowledge without sending the password.", "type": "mcq"}, {"type": "fill", "q": "The two random numbers in the 4 way handshake are the ANonce and the ____.", "a": ["SNonce"], "why": "One from the AP, one from the station."}], "refs": ["Wi-Fi Alliance. <a href=\"https://www.wi-fi.org/discover-wi-fi/security\" target=\"_blank\" rel=\"noopener\">Wi-Fi security<\/a>."]}, {"id": "wpa3", "name": "WPA3", "full": "Wi-Fi Protected Access 3", "layer": 2, "cat": "security", "title": "WPA3, a handshake that stops offline guessing.", "port": "none", "transport": "802.11", "lede": "WPA3 Personal replaces the shared key step with SAE, also called Dragonfly. An attacker who records the handshake can no longer test password guesses offline.", "overview": "<p>In <b>SAE<\/b>, simultaneous authentication of equals, both sides use the password to do a special key exchange. Each guess needs a live exchange with the access point, so offline dictionary attacks stop. SAE also gives <b>forward secrecy<\/b>. <b>Protected Management Frames<\/b> are required, which blocks fake disconnect messages.<\/p>", "nodes": {"phone": {"label": "Phone", "sub": "", "icon": "phone", "x": 0, "y": 1}, "ap": {"label": "Access point", "sub": "WPA3 Personal", "icon": "ap", "x": 4, "y": 1}, "eve": {"label": "Listener", "sub": "nearby", "icon": "user", "x": 4, "y": 3}}, "links": [["phone", "ap"], ["ap", "eve"], ["phone", "eve"]], "steps": [{"t": "SAE Commit", "tag": "sae", "d": "<p>Both sides turn the password into a secret point on an elliptic curve, then each sends a Commit with a random scalar and element. Nothing here lets a listener test guesses.<\/p>", "f": [], "p": [{"f": "phone", "t": "ap", "m": "SAE Commit", "k": "sec", "fields": [["Frame control", "0xb000 management, authentication"], ["Algorithm", "3 SAE"], ["Sequence", "1 commit"], ["Status", "0"], ["Contents", "group 19, scalar and element, 96 bytes"]], "raw": null, "hex": null}, {"f": "ap", "t": "phone", "m": "SAE Commit", "k": "sec", "fields": [["Frame control", "0xb000 management, authentication"], ["Algorithm", "3 SAE"], ["Sequence", "1 commit"], ["Status", "0"], ["Contents", "group 19, scalar and element, 96 bytes"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "SAE Confirm", "tag": "sae", "d": "<p>Each side sends a Confirm that proves it derived the same key. If the password were wrong, the confirm would fail. The result is a fresh PMK.<\/p>", "f": [], "p": [{"f": "phone", "t": "ap", "m": "SAE Confirm", "k": "sec", "fields": [["Frame control", "0xb000 management, authentication"], ["Algorithm", "3 SAE"], ["Sequence", "2 confirm"], ["Status", "0"], ["Contents", "send confirm counter, confirm hash"]], "raw": null, "hex": null}, {"f": "ap", "t": "phone", "m": "SAE Confirm", "k": "sec", "fields": [["Frame control", "0xb000 management, authentication"], ["Algorithm", "3 SAE"], ["Sequence", "2 confirm"], ["Status", "0"], ["Contents", "send confirm counter, confirm hash"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Association and 4 way handshake", "tag": "handshake", "d": "<p>The phone associates, then the usual 4 way handshake runs with the new PMK to make session keys.<\/p>", "f": [], "p": [{"f": "phone", "t": "ap", "m": "Association", "k": "ctl", "fields": [["Frame control", "0x0000 management, association request"], ["RSN", "WPA3 SAE, PMF required"]], "raw": null, "hex": null}, {"f": "ap", "t": "phone", "m": "4 way handshake M1 to M4", "k": "sec", "fields": [["EtherType", "0x888e EAPOL"], ["Descriptor", "2 RSN"], ["Key info", "0x008a"], ["Message", "M1 to M4"], ["Note", "same 4 way handshake, keys come from SAE so offline guessing fails"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Recording does not help", "tag": "risk", "d": "<p>The listener recorded everything, but cannot test password guesses offline. Each guess needs a full live exchange with the access point, which can rate limit.<\/p>", "f": [], "p": [], "on": [], "good": "Protected Management Frames also stop the fake disconnect frames that attackers once used to force reconnects.", "bad": []}], "quiz": [{"q": "What does SAE stop?", "opts": ["Fast connections", "Offline dictionary attacks on a captured handshake", "Encryption"], "a": 1, "why": "Each guess needs a live exchange.", "type": "mcq"}, {"type": "fill", "q": "WPA3 Personal uses a key exchange called ____, also known as Dragonfly.", "a": ["SAE"], "why": "Simultaneous Authentication of Equals."}], "refs": ["Wi-Fi Alliance. <a href=\"https://www.wi-fi.org/discover-wi-fi/security\" target=\"_blank\" rel=\"noopener\">WPA3 specification<\/a>."]}, {"id": "radius", "name": "RADIUS", "full": "802.1X Enterprise Wi-Fi", "layer": 2, "cat": "security", "title": "Enterprise Wi-Fi, a personal login per user with 802.1X.", "port": "1812 and 1813", "transport": "EAPOL and UDP", "lede": "In offices, each person logs in with their own account or certificate, not one shared password. The access point passes the login to a RADIUS server, which decides.", "overview": "<p>Three roles. The <b>supplicant<\/b> is your device. The <b>authenticator<\/b> is the access point or switch. The <b>authentication server<\/b> is RADIUS. Between device and AP, EAP messages travel in <b>EAPOL<\/b> frames. Between AP and RADIUS, they travel inside RADIUS packets on UDP 1812.<\/p>\n<p>Common methods are <b>EAP-TLS<\/b>, with client certificates, and <b>PEAP<\/b>, with a password inside a TLS tunnel.<\/p>", "nodes": {"laptop": {"label": "Laptop", "sub": "supplicant", "icon": "laptop", "x": 0, "y": 1}, "ap": {"label": "Access point", "sub": "authenticator", "icon": "ap", "x": 3, "y": 1}, "rad": {"label": "RADIUS server", "sub": "authentication server", "icon": "key", "x": 6, "y": 1}, "dir": {"label": "Directory", "sub": "user accounts", "icon": "db", "x": 8, "y": 1}}, "links": [["laptop", "ap"], ["ap", "rad"], ["rad", "dir"]], "steps": [{"t": "Start", "tag": "eap", "d": "<p>The laptop associates and sends EAPOL-Start. The AP blocks all other traffic until the login succeeds.<\/p>", "f": [], "p": [{"f": "laptop", "t": "ap", "m": "EAPOL-Start", "k": "ctl", "fields": [["EtherType", "0x888e EAPOL"], ["Version", "2"], ["Packet type", "1 EAPOL-Start"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Identity", "tag": "eap", "d": "<p>The AP asks for an identity. The laptop answers. The AP wraps the answer in a RADIUS Access-Request.<\/p>", "f": [], "p": [{"f": "ap", "t": "laptop", "m": "EAP Request Identity", "k": "ctl", "fields": [["EtherType", "0x888e EAPOL"], ["Code", "1 Request"], ["Type", "1 Identity"], ["Identifier", "1"]], "raw": null, "hex": null}, {"f": "laptop", "t": "ap", "m": "EAP Response Identity asha", "k": "req", "fields": [["EtherType", "0x888e EAPOL"], ["Code", "2 Response"], ["Type", "1 Identity"], ["Identifier", "1"], ["Identity", "asha"]], "raw": null, "hex": null}, {"f": "ap", "t": "rad", "m": "Access-Request (EAP inside)", "k": "req", "fields": [["Code", "1 Access-Request"], ["Identifier", "7"], ["Authenticator", "16 bytes"], ["User Name", "asha"], ["EAP Message", "EAP Response Identity"], ["Message Authenticator", "HMAC-MD5"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The EAP method runs", "tag": "tls", "d": "<p>RADIUS and the laptop run EAP-TLS through the AP, in several Access-Challenge rounds. They build a TLS session and check each other&#x27;s certificates.<\/p>", "f": [], "p": [{"f": "rad", "t": "ap", "m": "Access-Challenge", "k": "sec", "fields": [["Code", "11 Access-Challenge"], ["Identifier", "7"], ["Authenticator", "16 bytes"], ["EAP Message", "EAP Request, type 13 EAP-TLS start"]], "raw": null, "hex": null}, {"f": "ap", "t": "laptop", "m": "EAP TLS ServerHello, certificate", "k": "sec", "fields": [["EtherType", "0x888e EAPOL"], ["Code", "1 Request"], ["Type", "13 EAP-TLS"], ["Contains", "TLS ServerHello and RADIUS server certificate"]], "raw": null, "hex": null}, {"f": "laptop", "t": "ap", "m": "EAP TLS client certificate", "k": "sec", "fields": [["EtherType", "0x888e EAPOL"], ["Code", "2 Response"], ["Type", "13 EAP-TLS"], ["Contains", "TLS client certificate and key exchange"]], "raw": null, "hex": null}, {"f": "ap", "t": "rad", "m": "Access-Request", "k": "sec", "fields": [["Code", "1 Access-Request"], ["Identifier", "8"], ["Authenticator", "16 bytes"], ["EAP Message", "EAP-TLS client data"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Accept and keys", "tag": "accept", "d": "<p>RADIUS checks the account in the directory and sends Access-Accept with key material for the AP, and maybe a VLAN for this user.<\/p>", "f": [["Result", "Access-Accept"], ["VLAN", "20 staff"]], "p": [{"f": "rad", "t": "dir", "m": "check account", "k": "req", "fields": [["Message ID", "1"], ["Operation", "3 SearchRequest"], ["Filter", "(sAMAccountName=asha)"], ["Attributes", "memberOf, userAccountControl"]], "raw": null, "hex": null}, {"f": "rad", "t": "ap", "m": "Access-Accept + keys + VLAN 20", "k": "res", "fields": [["Code", "2 Access-Accept"], ["Identifier", "8"], ["Authenticator", "16 bytes"], ["MS MPPE Recv Key", "encrypted key for the AP"], ["Tunnel Private Group ID", "20"], ["EAP Message", "EAP Success"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "4 way handshake and access", "tag": "handshake", "d": "<p>The AP and the laptop run the 4 way handshake with the new key. The port opens. Each user has their own keys, and IT can disable one account without changing a shared password.<\/p>", "f": [], "p": [{"f": "ap", "t": "laptop", "m": "4 way handshake", "k": "sec", "fields": [["EtherType", "0x888e EAPOL"], ["Descriptor", "2 RSN"], ["Key info", "0x008a"], ["Message", "M1 to M4"], ["Note", "keys come from the EAP-TLS session"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "RADIUS authentication uses UDP port ____.", "a": ["1812"], "why": "Accounting uses 1813."}, {"q": "In 802.1X, which device decides if a user may connect?", "opts": ["The access point", "The RADIUS authentication server", "The laptop"], "a": 1, "why": "The AP only passes messages and enforces the result.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc3579\" target=\"_blank\" rel=\"noopener\">RFC 3579, RADIUS support for EAP<\/a>."]}, {"id": "captive", "name": "Captive Portal", "full": "Hotel and cafe Wi-Fi logins", "layer": 7, "cat": "security", "title": "Captive portal, the hotel Wi-Fi login page.", "port": "80 and 443", "transport": "HTTP", "lede": "On hotel or airport Wi-Fi, a login page pops up before you can browse. The network catches your first web request and sends you to its portal until you agree.", "overview": "<p>After you join, the operating system makes a test request to a known URL, such as Android&#x27;s <code>connectivitycheck.gstatic.com/generate_204<\/code>, which normally returns 204. If something else comes back, such as a redirect, the OS knows there is a portal and opens a mini browser.<\/p>\n<p>Newer networks announce the portal directly with DHCP option 114, the captive portal API in RFC 8910.<\/p>\n<div class=\"plain warn\"><span class=\"k\">Careful<\/span><p>Open hotel Wi-Fi is not encrypted. Use HTTPS sites and a VPN.<\/p><\/div>", "nodes": {"phone": {"label": "Phone", "sub": "10.20.0.55", "icon": "phone", "x": 0, "y": 1}, "gw": {"label": "Hotel gateway", "sub": "firewall", "icon": "router", "x": 3, "y": 1}, "portal": {"label": "Portal page", "sub": "login.hotel.example", "icon": "web", "x": 3, "y": 3}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 6, "y": 1}}, "links": [["phone", "gw"], ["gw", "portal"], ["gw", "net"]], "steps": [{"t": "Join and get an address", "tag": "join", "d": "<p>The phone joins the open network and gets an IP with DHCP. The gateway lets it reach DNS and the portal only.<\/p>", "f": [], "p": [], "on": [], "good": "", "bad": []}, {"t": "Connectivity check", "tag": "probe", "d": "<p>The phone requests <code>http://connectivitycheck.gstatic.com/generate_204<\/code>. It expects 204 No Content.<\/p>", "f": [], "p": [{"f": "phone", "t": "gw", "m": "GET /generate_204", "k": "req", "fields": [], "raw": "GET /generate_204 HTTP/1.1\r\nHost: connectivitycheck.gstatic.com\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Intercepted", "tag": "redirect", "d": "<p>The gateway intercepts the request and answers with a 302 redirect to the portal. Not a 204, so the phone opens the login sheet.<\/p>", "f": [], "p": [{"f": "gw", "t": "phone", "m": "302 Location login.hotel.example", "k": "bad", "fields": [], "raw": "HTTP/1.1 302 Found\r\nLocation: https://login.hotel.example/?mac=a4:5e:60:12:34:56\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Log in", "tag": "login", "d": "<p>You enter your room number and accept the terms. The portal tells the gateway to allow your device by its MAC and IP.<\/p>", "f": [], "p": [{"f": "phone", "t": "portal", "m": "POST room 412, accept terms", "k": "req", "fields": [["Method", "POST"], ["Path", "/login"], ["Body", "room=412&name=asha&accept=yes"], ["Transport", "HTTPS"]], "raw": null, "hex": null}, {"f": "portal", "t": "gw", "m": "allow 10.20.0.55", "k": "ctl", "fields": [["Rule", "allow"], ["Client IP", "10.20.0.55"], ["Client MAC", "a4:5e:60:12:34:56"], ["Duration", "24 hours"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Online", "tag": "done", "d": "<p>The connectivity check now reaches the real server and gets 204. Normal browsing works.<\/p>", "f": [], "p": [{"f": "phone", "t": "net", "m": "GET /generate_204", "k": "req", "fields": [], "raw": "GET /generate_204 HTTP/1.1\r\nHost: connectivitycheck.gstatic.com\r\n\r\n", "hex": null}, {"f": "net", "t": "phone", "m": "204 No Content", "k": "res", "fields": [], "raw": "HTTP/1.1 204 No Content\r\nContent-Length: 0\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "How does a phone detect a captive portal?", "opts": ["It reads the SSID", "It requests a known test URL and checks for the expected answer, such as 204", "It asks the user"], "a": 1, "why": "Any other answer, often a redirect, means a portal is in the way.", "type": "mcq"}, {"type": "fill", "q": "The DHCP option for the captive portal API is option ____.", "a": ["114"], "why": "RFC 8910."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc8910\" target=\"_blank\" rel=\"noopener\">RFC 8910, captive portal identification<\/a>."]}, {"id": "wireguard", "name": "WireGuard", "full": "A modern VPN", "layer": 3, "cat": "security", "title": "WireGuard, a fast VPN with one round trip.", "port": "often 51820", "transport": "UDP", "lede": "WireGuard sets up an encrypted tunnel with a single round trip, using public keys like SSH. Then it carries whole IP packets through the tunnel.", "overview": "<p>Each peer has a key pair. You list the public keys of the peers you trust and which IP ranges belong to each, called <b>AllowedIPs<\/b>. This is <b>cryptokey routing<\/b>. The handshake follows the <b>Noise IK<\/b> pattern. Data uses ChaCha20 Poly1305. Keys are renewed every two minutes.<\/p>\n<p>WireGuard does not answer packets that are not authenticated, so a scanner cannot even tell it is there.<\/p>", "nodes": {"laptop": {"label": "Laptop", "sub": "tunnel 10.8.0.2", "icon": "laptop", "x": 0, "y": 1}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 3, "y": 1}, "vpn": {"label": "VPN server", "sub": "198.51.100.40", "icon": "lock", "x": 5, "y": 1}, "db": {"label": "Office database", "sub": "10.0.5.20", "icon": "db", "x": 8, "y": 1}}, "links": [["laptop", "net"], ["net", "vpn"], ["vpn", "db"]], "steps": [{"t": "Handshake initiation", "tag": "handshake", "d": "<p>The laptop sends one message with an ephemeral public key, its own static public key encrypted, and an encrypted timestamp that stops replays.<\/p>", "f": [["Message", "Handshake Initiation"], ["Size", "148 bytes"], ["Contains", "ephemeral key, encrypted static key, encrypted timestamp, MACs"]], "p": [{"f": "laptop", "t": "vpn", "m": "Handshake Initiation", "k": "sec", "fields": [["Message type", "1 handshake initiation"], ["Reserved", "0"], ["Sender index", "0x9a1c3e07"], ["Ephemeral", "32 bytes"], ["Static", "encrypted, 48 bytes"], ["Timestamp", "encrypted, 28 bytes"], ["MACs", "mac1 and mac2, 16 bytes each"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Handshake response", "tag": "handshake", "d": "<p>The server knows the laptop public key, so it can check the message. It replies with its own ephemeral key. Both sides now derive the session keys.<\/p>", "f": [["Message", "Handshake Response"], ["Size", "92 bytes"]], "p": [{"f": "vpn", "t": "laptop", "m": "Handshake Response", "k": "sec", "fields": [["Message type", "2 handshake response"], ["Reserved", "0"], ["Sender index", "0x4f2d8b11"], ["Receiver index", "0x9a1c3e07"], ["Ephemeral", "32 bytes"], ["Empty", "encrypted, 16 bytes"], ["MACs", "mac1 and mac2"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Tunnel a packet", "tag": "data", "d": "<p>The laptop sends an IP packet for 10.0.5.20. WireGuard encrypts the whole packet and sends it in UDP to the server. The server decrypts it and checks the inner source is in the AllowedIPs of this peer.<\/p>", "f": [], "p": [{"f": "laptop", "t": "vpn", "m": "Transport data (encrypted IP packet)", "k": "data", "fields": [["Message type", "4 transport data"], ["Reserved", "0"], ["Receiver index", "0x9a1c3e07"], ["Counter", "0"], ["Packet", "inner IP packet, encrypted with ChaCha20-Poly1305"]], "raw": null, "hex": null}, {"f": "vpn", "t": "db", "m": "IP packet 10.8.0.2 to 10.0.5.20", "k": "data", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "63"], ["Protocol", "6 TCP"], ["Src", "10.8.0.2"], ["Dst", "10.0.5.20"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Reply through the tunnel", "tag": "data", "d": "<p>The reply goes back the same way. After two minutes the peers do a new handshake for fresh keys.<\/p>", "f": [], "p": [{"f": "db", "t": "vpn", "m": "IP reply", "k": "res", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "64"], ["Protocol", "6 TCP"], ["Src", "10.0.5.20"], ["Dst", "10.8.0.2"]], "raw": null, "hex": null}, {"f": "vpn", "t": "laptop", "m": "Transport data (encrypted)", "k": "data", "fields": [["Message type", "4 transport data"], ["Reserved", "0"], ["Receiver index", "0x4f2d8b11"], ["Counter", "0"], ["Packet", "inner reply, encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What is cryptokey routing?", "opts": ["Routing by MAC address", "Each peer public key is tied to the IP ranges it may use", "Routing by DNS"], "a": 1, "why": "AllowedIPs ties keys to addresses in both directions.", "type": "mcq"}, {"type": "fill", "q": "WireGuard runs over ____.", "a": ["UDP"], "why": "It sends encrypted IP packets inside UDP."}], "refs": ["WireGuard. <a href=\"https://www.wireguard.com/protocol/\" target=\"_blank\" rel=\"noopener\">Protocol and cryptography<\/a>.", "Jason Donenfeld. <a href=\"https://www.wireguard.com/papers/wireguard.pdf\" target=\"_blank\" rel=\"noopener\">WireGuard whitepaper<\/a>."]}, {"id": "ipsec", "name": "IPsec", "full": "IKEv2 and ESP", "layer": 3, "cat": "security", "title": "IPsec, a site to site tunnel with IKEv2 and ESP.", "port": "500 and 4500", "transport": "UDP 500 and 4500, ESP", "lede": "IPsec connects whole offices securely. IKEv2 agrees on keys and checks identities, then ESP encrypts every IP packet between the sites.", "overview": "<p><b>IKEv2<\/b> runs on UDP 500. <b>IKE_SA_INIT<\/b> does a Diffie Hellman exchange and picks algorithms. <b>IKE_AUTH<\/b> proves identities with certificates or a pre shared key and sets up the first <b>Child SA<\/b>, the tunnel for data. Data uses <b>ESP<\/b>, IP protocol 50. When NAT is in the way, IKE moves to UDP 4500 and ESP goes inside UDP 4500 too, called NAT traversal.<\/p>", "nodes": {"pc": {"label": "Office A PC", "sub": "10.1.0.15", "icon": "laptop", "x": 0, "y": 1}, "gwa": {"label": "Gateway A", "sub": "198.51.100.10", "icon": "lock", "x": 2, "y": 1}, "net": {"label": "Internet", "sub": "", "icon": "cloud", "x": 4, "y": 1}, "gwb": {"label": "Gateway B", "sub": "203.0.113.10", "icon": "lock", "x": 6, "y": 1}, "srv": {"label": "Office B server", "sub": "10.2.0.20", "icon": "server", "x": 8, "y": 1}}, "links": [["pc", "gwa"], ["gwa", "net"], ["net", "gwb"], ["gwb", "srv"]], "steps": [{"t": "IKE_SA_INIT", "tag": "ike", "d": "<p>Gateway A proposes algorithms and sends a Diffie Hellman key share and a nonce. B picks algorithms and sends its own. Now they share a secret for the next messages.<\/p>", "f": [], "p": [{"f": "gwa", "t": "gwb", "m": "IKE_SA_INIT SA, KE, Ni", "k": "sec", "fields": [["Initiator SPI", "0x8a1f00d4c3b2a190"], ["Version", "0x20"], ["Exchange type", "34 IKE_SA_INIT"], ["Flags", "0x08 initiator"], ["Message ID", "0"], ["Payloads", "SA, KE group 19, Nonce"]], "raw": null, "hex": null}, {"f": "gwb", "t": "gwa", "m": "IKE_SA_INIT SA, KE, Nr", "k": "sec", "fields": [["Initiator SPI", "0x8a1f00d4c3b2a190"], ["Version", "0x20"], ["Exchange type", "34 IKE_SA_INIT"], ["Flags", "0x20 response"], ["Message ID", "0"], ["Payloads", "SA, KE group 19, Nonce, CERTREQ"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "IKE_AUTH", "tag": "ike", "d": "<p>Encrypted now, each gateway proves its identity with a certificate signature. They agree on traffic selectors, 10.1.0.0/16 to 10.2.0.0/16, and set up the Child SA.<\/p>", "f": [["Traffic selectors", "10.1.0.0/16 <-> 10.2.0.0/16"], ["Auth", "certificates"]], "p": [{"f": "gwa", "t": "gwb", "m": "IKE_AUTH IDi, AUTH, SA, TS", "k": "sec", "fields": [["Initiator SPI", "0x8a1f00d4c3b2a190"], ["Version", "0x20"], ["Exchange type", "35 IKE_AUTH"], ["Flags", "0x08 initiator"], ["Message ID", "1"], ["Payloads", "SK with IDi, CERT, AUTH, SA, TSi, TSr"]], "raw": null, "hex": null}, {"f": "gwb", "t": "gwa", "m": "IKE_AUTH IDr, AUTH, SA, TS", "k": "sec", "fields": [["Initiator SPI", "0x8a1f00d4c3b2a190"], ["Version", "0x20"], ["Exchange type", "35 IKE_AUTH"], ["Flags", "0x20 response"], ["Message ID", "1"], ["Payloads", "SK with IDr, CERT, AUTH, SA, TSi, TSr"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "ESP carries the data", "tag": "esp", "d": "<p>The office PC sends a normal packet to 10.2.0.20. Gateway A encrypts the whole packet in ESP tunnel mode, with a new outer header between the gateway addresses.<\/p>", "f": [], "p": [{"f": "pc", "t": "gwa", "m": "IP 10.1.0.15 to 10.2.0.20", "k": "data", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "64"], ["Protocol", "6 TCP"], ["Src", "10.1.0.15"], ["Dst", "10.2.0.20"]], "raw": null, "hex": null}, {"f": "gwa", "t": "gwb", "m": "ESP (encrypted inner packet)", "k": "data", "fields": [["Outer src", "198.51.100.10"], ["Outer dst", "203.0.113.10"], ["Protocol", "50 ESP"], ["SPI", "0xc0de0001"], ["Sequence number", "1"], ["Payload", "encrypted inner packet and an integrity tag"]], "raw": null, "hex": null}, {"f": "gwb", "t": "srv", "m": "IP 10.1.0.15 to 10.2.0.20", "k": "data", "fields": [["Version", "4"], ["IHL", "5"], ["Total length", "60"], ["Identification", "0x1c46"], ["TTL", "63"], ["Protocol", "6 TCP"], ["Src", "10.1.0.15"], ["Dst", "10.2.0.20"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Rekey", "tag": "ike", "d": "<p>Before the keys get old, the gateways run CREATE_CHILD_SA to make new ones, with no break in traffic.<\/p>", "f": [], "p": [{"f": "gwa", "t": "gwb", "m": "CREATE_CHILD_SA", "k": "sec", "fields": [["Initiator SPI", "0x8a1f00d4c3b2a190"], ["Version", "0x20"], ["Exchange type", "36 CREATE_CHILD_SA"], ["Flags", "0x08 initiator"], ["Message ID", "2"], ["Payloads", "SK with SA, Nonce, KE, rekey"]], "raw": null, "hex": null}, {"f": "gwb", "t": "gwa", "m": "CREATE_CHILD_SA", "k": "sec", "fields": [["Initiator SPI", "0x8a1f00d4c3b2a190"], ["Version", "0x20"], ["Exchange type", "36 CREATE_CHILD_SA"], ["Flags", "0x20 response"], ["Message ID", "2"], ["Payloads", "SK with SA, Nonce, KE"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "ESP is IP protocol number ____.", "a": ["50"], "why": "AH is protocol 51, rarely used today."}, {"q": "When does IKEv2 move to UDP port 4500?", "opts": ["Always", "When NAT is detected between the peers", "Never"], "a": 1, "why": "NAT traversal puts ESP inside UDP so NAT devices can pass it.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc7296\" target=\"_blank\" rel=\"noopener\">RFC 7296, IKEv2<\/a>."]}, {"id": "kerberos", "name": "Kerberos", "full": "Tickets for single sign on", "layer": 7, "cat": "security", "title": "Kerberos, logging in once and using tickets.", "port": "88", "transport": "UDP and TCP", "lede": "In a Windows domain, you type your password once. Kerberos then gives you tickets that prove who you are to each service, without sending your password again.", "overview": "<p>The <b>KDC<\/b>, key distribution center, has two parts. The <b>authentication service<\/b> gives you a <b>TGT<\/b>, a ticket granting ticket. The <b>ticket granting service<\/b> swaps the TGT for <b>service tickets<\/b>. Each ticket is encrypted with the key of the service it is for, so only that service can read it. Clocks must be close, usually within 5 minutes.<\/p>", "nodes": {"pc": {"label": "User PC", "sub": "asha", "icon": "laptop", "x": 0, "y": 1}, "kdc": {"label": "Domain controller", "sub": "KDC", "icon": "key", "x": 4, "y": 0}, "web": {"label": "Intranet web app", "sub": "HTTP/intranet", "icon": "web", "x": 4, "y": 2}}, "links": [["pc", "kdc"], ["pc", "web"]], "steps": [{"t": "AS-REQ", "tag": "login", "d": "<p>At login, the PC sends AS-REQ with a timestamp encrypted with a key made from your password. This is pre authentication.<\/p>", "f": [], "p": [{"f": "pc", "t": "kdc", "m": "AS-REQ (encrypted timestamp)", "k": "sec", "fields": [["pvno", "5"], ["msg type", "10 AS-REQ"], ["realm", "CORP.EXAMPLE"], ["cname", "asha"], ["sname", "krbtgt/CORP.EXAMPLE"], ["padata", "PA-ENC-TIMESTAMP, AES256"], ["etype", "18 aes256-cts"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "AS-REP with a TGT", "tag": "login", "d": "<p>The KDC decrypts the timestamp with its copy of your key, so it knows you. It returns a TGT, encrypted with the KDC own key, plus a session key encrypted with your key.<\/p>", "f": [["TGT", "encrypted with krbtgt key"], ["Session key", "encrypted with user key"], ["Lifetime", "about 10 hours"]], "p": [{"f": "kdc", "t": "pc", "m": "AS-REP (TGT + session key)", "k": "sec", "fields": [["pvno", "5"], ["msg type", "11 AS-REP"], ["realm", "CORP.EXAMPLE"], ["cname", "asha"], ["ticket", "TGT, encrypted with the krbtgt key"], ["enc part", "session key, encrypted with the user key"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "TGS-REQ for a service", "tag": "ticket", "d": "<p>You open the intranet. The PC sends the TGT and an authenticator to the KDC and asks for a ticket for <code>HTTP/intranet.corp.example<\/code>.<\/p>", "f": [], "p": [{"f": "pc", "t": "kdc", "m": "TGS-REQ (TGT, SPN HTTP/intranet)", "k": "sec", "fields": [["pvno", "5"], ["msg type", "12 TGS-REQ"], ["realm", "CORP.EXAMPLE"], ["sname", "HTTP/intranet"], ["padata", "AP-REQ with the TGT and an authenticator"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "TGS-REP with a service ticket", "tag": "ticket", "d": "<p>The KDC returns a service ticket encrypted with the web app key. The PC cannot read it. It only passes it on.<\/p>", "f": [], "p": [{"f": "kdc", "t": "pc", "m": "TGS-REP (service ticket)", "k": "sec", "fields": [["pvno", "5"], ["msg type", "13 TGS-REP"], ["realm", "CORP.EXAMPLE"], ["sname", "HTTP/intranet"], ["ticket", "service ticket, encrypted with the web service key"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "AP-REQ to the service", "tag": "access", "d": "<p>The browser sends the service ticket and an authenticator in the HTTP Authorization header. The web app decrypts the ticket with its own key and knows it is you. No password was sent to the web app.<\/p>", "f": [], "p": [{"f": "pc", "t": "web", "m": "AP-REQ (Authorization Negotiate)", "k": "sec", "fields": [["Header", "Authorization: Negotiate"], ["Token", "SPNEGO wrapping AP-REQ"], ["msg type", "14 AP-REQ"]], "raw": null, "hex": null}, {"f": "web", "t": "pc", "m": "200 OK, welcome asha", "k": "res", "fields": [], "raw": "HTTP/1.1 200 OK\r\nWWW-Authenticate: Negotiate oRQwEqADCgEA...\r\nContent-Type: text/html\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "Who can read a service ticket?", "opts": ["The user", "Only the service it is for, because it is encrypted with that service key", "Anyone on the network"], "a": 1, "why": "The user just carries it.", "type": "mcq"}, {"type": "fill", "q": "The ticket you get at login, used to request other tickets, is the ____.", "a": ["TGT", "ticket granting ticket"], "why": "Ticket granting ticket."}], "refs": ["MIT. <a href=\"https://web.mit.edu/kerberos/\" target=\"_blank\" rel=\"noopener\">Kerberos, the network authentication protocol<\/a>.", "IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc4120\" target=\"_blank\" rel=\"noopener\">RFC 4120, Kerberos V5<\/a>."]}, {"id": "ldap", "name": "LDAP", "full": "Directory lookups and logins", "layer": 7, "cat": "security", "title": "LDAP, asking the company directory.", "port": "389, 636 for LDAPS", "transport": "TCP", "lede": "LDAP is how apps look up users and groups in a directory such as Active Directory or OpenLDAP, and how many apps check passwords.", "overview": "<p>Entries live in a tree. Each entry has a <b>distinguished name<\/b>, such as <code>uid=asha,ou=people,dc=corp,dc=example<\/code>. Apps <b>bind<\/b>, which means log in, then <b>search<\/b> with a filter, such as <code>(uid=asha)<\/code>.<\/p>\n<p>A simple bind sends the password as it is. Always use <b>StartTLS<\/b> on port 389 or <b>LDAPS<\/b> on port 636.<\/p>", "nodes": {"app": {"label": "Web app", "sub": "10.0.1.40", "icon": "web", "x": 0, "y": 1}, "ldap": {"label": "Directory server", "sub": "10.0.0.10", "icon": "db", "x": 6, "y": 1}}, "links": [["app", "ldap"]], "steps": [{"t": "StartTLS", "tag": "tls", "d": "<p>The app connects to port 389 and asks to upgrade to TLS with the StartTLS extended operation. Then it does a TLS handshake.<\/p>", "f": [], "p": [{"f": "app", "t": "ldap", "m": "ExtendedRequest StartTLS", "k": "sec", "fields": [["Message ID", "1"], ["Operation", "23 ExtendedRequest"], ["requestName", "1.3.6.1.4.1.1466.20037 StartTLS"]], "raw": null, "hex": null}, {"f": "ldap", "t": "app", "m": "ExtendedResponse success, TLS handshake", "k": "sec", "fields": [["Message ID", "1"], ["Operation", "24 ExtendedResponse"], ["resultCode", "0 success"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Bind as a service account", "tag": "bind", "d": "<p>The app binds as its own service account to be allowed to search.<\/p>", "f": [], "p": [{"f": "app", "t": "ldap", "m": "BindRequest cn=webapp", "k": "sec", "fields": [["Message ID", "2"], ["Operation", "0 BindRequest"], ["version", "3"], ["name", "cn=webapp,ou=services,dc=corp,dc=example"], ["auth", "simple, inside TLS"]], "raw": null, "hex": null}, {"f": "ldap", "t": "app", "m": "BindResponse success", "k": "res", "fields": [["Message ID", "2"], ["Operation", "1 BindResponse"], ["resultCode", "0 success"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Search for the user", "tag": "search", "d": "<p>A user logs in as asha. The app searches for her entry and her groups.<\/p>", "f": [["Base", "ou=people,dc=corp,dc=example"], ["Scope", "subtree"], ["Filter", "(uid=asha)"]], "p": [{"f": "app", "t": "ldap", "m": "SearchRequest (uid=asha)", "k": "req", "fields": [["Message ID", "3"], ["Operation", "3 SearchRequest"], ["baseObject", "ou=people,dc=corp,dc=example"], ["scope", "2 subtree"], ["filter", "(uid=asha)"], ["attributes", "cn, mail, memberOf"]], "raw": null, "hex": null}, {"f": "ldap", "t": "app", "m": "SearchResultEntry uid=asha, memberOf=staff", "k": "res", "fields": [["Message ID", "3"], ["Operation", "4 SearchResultEntry"], ["objectName", "uid=asha,ou=people,dc=corp,dc=example"], ["memberOf", "cn=staff,ou=groups,dc=corp,dc=example"]], "raw": null, "hex": null}, {"f": "ldap", "t": "app", "m": "SearchResultDone", "k": "res", "fields": [["Message ID", "3"], ["Operation", "5 SearchResultDone"], ["resultCode", "0 success"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Check her password", "tag": "bind", "d": "<p>The app binds as asha with the password she typed. Success means the password is right.<\/p>", "f": [], "p": [{"f": "app", "t": "ldap", "m": "BindRequest uid=asha", "k": "sec", "fields": [["Message ID", "4"], ["Operation", "0 BindRequest"], ["version", "3"], ["name", "uid=asha,ou=people,dc=corp,dc=example"], ["auth", "simple, the user's password, inside TLS"]], "raw": null, "hex": null}, {"f": "ldap", "t": "app", "m": "BindResponse success", "k": "res", "fields": [["Message ID", "4"], ["Operation", "1 BindResponse"], ["resultCode", "0 success"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "LDAP over TLS from the start, LDAPS, uses port ____.", "a": ["636"], "why": "Plain LDAP and StartTLS use 389."}, {"q": "Why must LDAP simple binds use TLS?", "opts": ["They are slow", "The password is sent as it is", "They need UDP"], "a": 1, "why": "Without TLS, anyone on the path can read the password.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc4511\" target=\"_blank\" rel=\"noopener\">RFC 4511, LDAP protocol<\/a>."]}, {"id": "oauth", "name": "OAuth 2.0", "full": "Authorization code with PKCE", "layer": 7, "cat": "security", "title": "OAuth 2.0, Sign in with a provider, step by step.", "port": "443", "transport": "HTTPS", "lede": "OAuth lets an app get limited access for you without seeing your password. With OpenID Connect on top, the app also learns who you are. Watch the authorization code flow with PKCE.", "overview": "<p>The roles are the <b>user<\/b>, the <b>client app<\/b>, the <b>authorization server<\/b> and the <b>resource server<\/b>, the API. The app gets a short <b>code<\/b>, then swaps it for <b>tokens<\/b> on a back channel. <b>PKCE<\/b> binds the code to the app that asked for it, using a secret <code>code_verifier<\/code> and its hash, the <code>code_challenge<\/code>.<\/p>", "nodes": {"user": {"label": "User and browser", "sub": "", "icon": "user", "x": 0, "y": 1}, "app": {"label": "Photo app", "sub": "client", "icon": "web", "x": 3, "y": 0}, "auth": {"label": "Login provider", "sub": "authorization server", "icon": "key", "x": 6, "y": 1}, "api": {"label": "Photos API", "sub": "resource server", "icon": "server", "x": 3, "y": 3}}, "links": [["user", "app"], ["user", "auth"], ["app", "auth"], ["app", "api"]], "steps": [{"t": "Redirect to the provider", "tag": "authorize", "d": "<p>The app makes a random code_verifier and sends the browser to the provider with the hash of it, the scopes it wants and a state value.<\/p>", "f": [["response_type", "code"], ["scope", "openid photos.read"], ["code_challenge_method", "S256"]], "p": [{"f": "app", "t": "user", "m": "302 to /authorize?...code_challenge", "k": "req", "fields": [], "raw": "HTTP/1.1 302 Found\r\nLocation: https://auth.example/authorize?response_type=code&client_id=app123&redirect_uri=https%3A%2F%2Fapp.example%2Fcallback&scope=openid%20photos.read&state=af0ifjsldkj&code_challenge=E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM&code_challenge_method=S256\r\n\r\n", "hex": null}, {"f": "user", "t": "auth", "m": "GET /authorize", "k": "req", "fields": [], "raw": "GET /authorize?response_type=code&client_id=app123&scope=openid%20photos.read&state=af0ifjsldkj&code_challenge=E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM&code_challenge_method=S256 HTTP/1.1\r\nHost: auth.example\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Log in and consent", "tag": "login", "d": "<p>You log in at the provider, not at the app, and agree to &quot;read your photos&quot;. The app never sees your password.<\/p>", "f": [], "p": [{"f": "user", "t": "auth", "m": "password, MFA, consent", "k": "sec", "fields": [["Method", "POST"], ["Path", "/login"], ["Then", "MFA code, consent screen for photos.read"], ["Transport", "HTTPS"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Code comes back", "tag": "code", "d": "<p>The provider redirects the browser back to the app with a one time code and the same state.<\/p>", "f": [], "p": [{"f": "auth", "t": "user", "m": "302 to app/callback?code=...&state=...", "k": "res", "fields": [], "raw": "HTTP/1.1 302 Found\r\nLocation: https://app.example/callback?code=SplxlOBeZQQYbYS6WxSbIA&state=af0ifjsldkj\r\n\r\n", "hex": null}, {"f": "user", "t": "app", "m": "GET /callback?code=...", "k": "res", "fields": [], "raw": "GET /callback?code=SplxlOBeZQQYbYS6WxSbIA&state=af0ifjsldkj HTTP/1.1\r\nHost: app.example\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Swap the code for tokens", "tag": "token", "d": "<p>The app sends the code and the original code_verifier to the token endpoint. The provider checks the hash matches and returns an access token and, for OpenID Connect, an ID token.<\/p>", "f": [], "p": [{"f": "app", "t": "auth", "m": "POST /token code + code_verifier", "k": "sec", "fields": [], "raw": "POST /token HTTP/1.1\r\nHost: auth.example\r\nContent-Type: application/x-www-form-urlencoded\r\n\r\ngrant_type=authorization_code&code=SplxlOBeZQQYbYS6WxSbIA&redirect_uri=https%3A%2F%2Fapp.example%2Fcallback&code_verifier=dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk", "hex": null}, {"f": "auth", "t": "app", "m": "access_token, id_token", "k": "sec", "fields": [], "raw": "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nCache-Control: no-store\r\n\r\n{\"access_token\":\"eyJhbGciOi...\",\"token_type\":\"Bearer\",\"expires_in\":900,\"id_token\":\"eyJ...\"}", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Call the API", "tag": "api", "d": "<p>The app calls the photos API with the access token as a Bearer token. The API checks it and returns only what the scope allows.<\/p>", "f": [], "p": [{"f": "app", "t": "api", "m": "GET /photos, Authorization Bearer", "k": "req", "fields": [], "raw": "GET /photos HTTP/1.1\r\nHost: api.example\r\nAuthorization: Bearer eyJhbGciOi...\r\n\r\n", "hex": null}, {"f": "api", "t": "app", "m": "200 photos", "k": "res", "fields": [], "raw": "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{\"photos\":[{\"id\":\"p1\"},{\"id\":\"p2\"}]}", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What does PKCE protect against?", "opts": ["Slow logins", "A stolen authorization code being used by another app", "Weak passwords"], "a": 1, "why": "Only the app with the code_verifier can redeem the code.", "type": "mcq"}, {"type": "fill", "q": "The token that tells the app who the user is, in OpenID Connect, is the ____ token.", "a": ["ID", "id_token", "identity"], "why": "The access token is for calling APIs."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc6749\" target=\"_blank\" rel=\"noopener\">RFC 6749, OAuth 2.0<\/a> and <a href=\"https://www.rfc-editor.org/rfc/rfc7636\" target=\"_blank\" rel=\"noopener\">RFC 7636, PKCE<\/a>.", "OAuth.net. <a href=\"https://oauth.net/2/\" target=\"_blank\" rel=\"noopener\">OAuth 2.0<\/a>."]}, {"id": "smtp", "name": "SMTP", "full": "Simple Mail Transfer Protocol", "layer": 7, "cat": "app", "title": "SMTP, an email crosses the internet.", "port": "25 relay, 587 submission", "transport": "TCP", "lede": "Your app submits the email to your provider, the provider finds the recipient mail server with DNS, and hands the email over in a short text conversation.", "overview": "<p>Clients <b>submit<\/b> mail on port 587 with STARTTLS and a login. Mail servers <b>relay<\/b> to each other on port 25. The receiving server checks <b>SPF<\/b>, which servers may send for the domain, <b>DKIM<\/b>, a signature over the message, and <b>DMARC<\/b>, the domain owner policy for failures.<\/p>", "nodes": {"app": {"label": "Mail app", "sub": "asha@corp.example", "icon": "laptop", "x": 0, "y": 1}, "out": {"label": "Outgoing server", "sub": "smtp.corp.example", "icon": "mail", "x": 3, "y": 1}, "dns": {"label": "DNS", "sub": "MX lookup", "icon": "dns", "x": 3, "y": 3}, "inb": {"label": "Receiving server", "sub": "mx.shop.example", "icon": "mail", "x": 6, "y": 1}, "box": {"label": "Mailbox", "sub": "ben@shop.example", "icon": "folder", "x": 8, "y": 1}}, "links": [["app", "out"], ["out", "dns"], ["out", "inb"], ["inb", "box"]], "steps": [{"t": "Submit on port 587", "tag": "submit", "d": "<p>The app connects to its provider on 587, upgrades with STARTTLS and logs in with AUTH. Then it sends the message.<\/p>", "f": [], "p": [{"f": "app", "t": "out", "m": "EHLO, STARTTLS, AUTH", "k": "sec", "fields": [], "raw": "EHLO laptop.corp.example\r\nSTARTTLS\r\nAUTH PLAIN AGFzaGEAKioqKg==\r\n", "hex": null}, {"f": "app", "t": "out", "m": "MAIL FROM, RCPT TO, DATA", "k": "req", "fields": [], "raw": "MAIL FROM:<asha@corp.example>\r\nRCPT TO:<ben@shop.example>\r\nDATA\r\n", "hex": null}, {"f": "out", "t": "app", "m": "250 queued", "k": "res", "fields": [], "raw": "250 2.0.0 Ok: queued as 4C1D2\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Find the mail server", "tag": "dns", "d": "<p>The outgoing server looks up the MX record of shop.example to find where its mail goes.<\/p>", "f": [], "p": [{"f": "out", "t": "dns", "m": "MX shop.example?", "k": "req", "fields": [["Transaction ID", "0x61c2"], ["Flags", "0x0100 standard query"], ["Questions", "1"], ["Answer RRs", "0"], ["Authority RRs", "0"], ["Additional RRs", "0"], ["Contains", "shop.example MX"]], "raw": null, "hex": null}, {"f": "dns", "t": "out", "m": "MX 10 mx.shop.example", "k": "res", "fields": [["Transaction ID", "0x61c2"], ["Flags", "0x8180 response"], ["Questions", "1"], ["Answer RRs", "1"], ["Authority RRs", "0"], ["Additional RRs", "1"], ["Contains", "MX 10 mx.shop.example, plus its A record"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Greeting and EHLO", "tag": "relay", "d": "<p>The outgoing server connects to mx.shop.example on port 25. The receiver greets with 220. The sender says EHLO and learns the supported extensions, then upgrades with STARTTLS.<\/p>", "f": [], "p": [{"f": "inb", "t": "out", "m": "220 mx.shop.example ESMTP", "k": "ctl", "fields": [], "raw": "220 mx.shop.example ESMTP ready\r\n", "hex": null}, {"f": "out", "t": "inb", "m": "EHLO smtp.corp.example", "k": "req", "fields": [], "raw": "EHLO smtp.corp.example\r\n", "hex": null}, {"f": "inb", "t": "out", "m": "250-STARTTLS ...", "k": "res", "fields": [], "raw": "250-mx.shop.example\r\n250-SIZE 52428800\r\n250-STARTTLS\r\n250 SMTPUTF8\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Envelope and data", "tag": "relay", "d": "<p>The sender gives the envelope, then the message. A line with a single dot ends the data.<\/p>", "f": [], "p": [{"f": "out", "t": "inb", "m": "MAIL FROM:<asha@corp.example>", "k": "req", "fields": [], "raw": "MAIL FROM:<asha@corp.example>\r\n", "hex": null}, {"f": "inb", "t": "out", "m": "250 OK", "k": "res", "fields": [], "raw": "250 2.1.0 Ok\r\n", "hex": null}, {"f": "out", "t": "inb", "m": "RCPT TO:<ben@shop.example>", "k": "req", "fields": [], "raw": "RCPT TO:<ben@shop.example>\r\n", "hex": null}, {"f": "inb", "t": "out", "m": "250 OK", "k": "res", "fields": [], "raw": "250 2.1.5 Ok\r\n", "hex": null}, {"f": "out", "t": "inb", "m": "DATA ... .", "k": "data", "fields": [], "raw": "DATA\r\nSubject: Invoice\r\nFrom: asha@corp.example\r\n\r\nHello Ben.\r\n.\r\n", "hex": null}, {"f": "inb", "t": "out", "m": "250 queued as 8F2A1", "k": "res", "fields": [], "raw": "250 2.0.0 Ok: queued as 8F2A1\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Checks and delivery", "tag": "deliver", "d": "<p>The receiver checks SPF, DKIM and DMARC, scans for spam, and puts the message in the mailbox. The sender says QUIT.<\/p>", "f": [], "p": [{"f": "inb", "t": "box", "m": "deliver to ben", "k": "data", "fields": [["Mailbox", "ben@shop.example"], ["Store", "Maildir or database"], ["Checks", "SPF, DKIM and DMARC results added as headers"]], "raw": null, "hex": null}, {"f": "out", "t": "inb", "m": "QUIT", "k": "ctl", "fields": [], "raw": "QUIT\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "Email clients submit mail on port ____ with STARTTLS and a login.", "a": ["587"], "why": "Port 25 is for server to server relay."}, {"q": "How does the sending server find where to deliver mail for shop.example?", "opts": ["It guesses", "It looks up the MX record in DNS", "It asks the user"], "a": 1, "why": "MX records name the mail servers of a domain.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc5321\" target=\"_blank\" rel=\"noopener\">RFC 5321, SMTP<\/a>.", "Cloudflare. <a href=\"https://www.cloudflare.com/learning/email-security/dmarc-dkim-spf/\" target=\"_blank\" rel=\"noopener\">What are DMARC, DKIM and SPF?<\/a>"]}, {"id": "pop3", "name": "POP3", "full": "Post Office Protocol v3", "layer": 7, "cat": "app", "title": "POP3, download the mail and usually delete it.", "port": "110, 995 with TLS", "transport": "TCP", "lede": "POP3 is the simple, old way to read email. The app logs in, downloads messages and often deletes them from the server. Mail then lives on one device only.", "overview": "<p>POP3 has three states. <b>Authorization<\/b>, you log in. <b>Transaction<\/b>, you list and download. <b>Update<\/b>, after QUIT, the server really deletes the messages you marked. Use port 995, POP3 over TLS, so the password is protected.<\/p>", "nodes": {"app": {"label": "Mail app", "sub": "laptop", "icon": "laptop", "x": 0, "y": 1}, "srv": {"label": "POP3 server", "sub": "pop.example", "icon": "mail", "x": 6, "y": 1}}, "links": [["app", "srv"]], "steps": [{"t": "Greeting and login", "tag": "auth", "d": "<p>After TLS on port 995, the server greets with +OK. The app sends USER and PASS.<\/p>", "f": [], "p": [{"f": "srv", "t": "app", "m": "+OK POP3 ready", "k": "ctl", "fields": [], "raw": "+OK POP3 server ready\r\n", "hex": null}, {"f": "app", "t": "srv", "m": "USER asha", "k": "sec", "fields": [], "raw": "USER asha\r\n", "hex": null}, {"f": "app", "t": "srv", "m": "PASS ********", "k": "sec", "fields": [], "raw": "PASS ********\r\n", "hex": null}, {"f": "srv", "t": "app", "m": "+OK logged in", "k": "res", "fields": [], "raw": "+OK logged in\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "How many messages?", "tag": "list", "d": "<p>STAT returns the number of messages and their total size. LIST gives each size.<\/p>", "f": [], "p": [{"f": "app", "t": "srv", "m": "STAT", "k": "req", "fields": [], "raw": "STAT\r\n", "hex": null}, {"f": "srv", "t": "app", "m": "+OK 2 3200", "k": "res", "fields": [], "raw": "+OK 2 3200\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Download", "tag": "retr", "d": "<p>RETR 1 downloads the whole first message.<\/p>", "f": [], "p": [{"f": "app", "t": "srv", "m": "RETR 1", "k": "req", "fields": [], "raw": "RETR 1\r\n", "hex": null}, {"f": "srv", "t": "app", "m": "+OK message follows ... .", "k": "data", "fields": [], "raw": "+OK 1700 octets\r\nSubject: Hello\r\n\r\nSee you at 10.\r\n.\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Delete and quit", "tag": "update", "d": "<p>DELE marks message 1. QUIT ends the session, and only now does the server delete it.<\/p>", "f": [], "p": [{"f": "app", "t": "srv", "m": "DELE 1", "k": "req", "fields": [], "raw": "DELE 1\r\n", "hex": null}, {"f": "app", "t": "srv", "m": "QUIT", "k": "req", "fields": [], "raw": "QUIT\r\n", "hex": null}, {"f": "srv", "t": "app", "m": "+OK bye, 1 message deleted", "k": "res", "fields": [], "raw": "+OK bye, 1 message deleted\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "When does POP3 actually delete messages marked with DELE?", "opts": ["Immediately", "After QUIT, in the update state", "Never"], "a": 1, "why": "If the connection drops before QUIT, nothing is deleted.", "type": "mcq"}, {"type": "fill", "q": "POP3 over TLS uses port ____.", "a": ["995"], "why": "Plain POP3 uses 110."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc1939\" target=\"_blank\" rel=\"noopener\">RFC 1939, POP3<\/a>."]}, {"id": "imap", "name": "IMAP", "full": "Internet Message Access", "layer": 7, "cat": "app", "title": "IMAP, mail stays on the server and syncs everywhere.", "port": "143, 993 with TLS", "transport": "TCP", "lede": "IMAP keeps your mail on the server. Phone, laptop and web all see the same folders and read marks. Commands carry tags so many can run at once.", "overview": "<p>Every client command starts with a <b>tag<\/b>, such as <code>a1<\/code>. The server ends its answer with the same tag and OK, NO or BAD. Lines starting with <code>*<\/code> are untagged data. <b>IDLE<\/b> lets the server push new mail at once.<\/p>", "nodes": {"phone": {"label": "Phone mail app", "sub": "", "icon": "phone", "x": 0, "y": 1}, "srv": {"label": "IMAP server", "sub": "imap.example", "icon": "mail", "x": 6, "y": 1}}, "links": [["phone", "srv"]], "steps": [{"t": "Log in", "tag": "auth", "d": "<p>After TLS on port 993, the app logs in.<\/p>", "f": [], "p": [{"f": "srv", "t": "phone", "m": "* OK IMAP4rev1 ready", "k": "ctl", "fields": [], "raw": "* OK [CAPABILITY IMAP4rev1 STARTTLS IDLE] ready\r\n", "hex": null}, {"f": "phone", "t": "srv", "m": "a1 LOGIN asha ********", "k": "sec", "fields": [], "raw": "a1 LOGIN asha ********\r\n", "hex": null}, {"f": "srv", "t": "phone", "m": "a1 OK LOGIN completed", "k": "res", "fields": [], "raw": "a1 OK LOGIN completed\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Open the inbox", "tag": "select", "d": "<p>SELECT opens a folder. The server says how many messages exist.<\/p>", "f": [], "p": [{"f": "phone", "t": "srv", "m": "a2 SELECT INBOX", "k": "req", "fields": [], "raw": "a2 SELECT INBOX\r\n", "hex": null}, {"f": "srv", "t": "phone", "m": "* 12 EXISTS, a2 OK", "k": "res", "fields": [], "raw": "* 12 EXISTS\r\n* 1 RECENT\r\na2 OK [READ-WRITE] SELECT completed\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Fetch only headers", "tag": "fetch", "d": "<p>The app fetches only the subject and sender for the list view. It downloads bodies only when you open a message.<\/p>", "f": [], "p": [{"f": "phone", "t": "srv", "m": "a3 FETCH 1:12 (FLAGS ENVELOPE)", "k": "req", "fields": [], "raw": "a3 FETCH 1:12 (FLAGS ENVELOPE)\r\n", "hex": null}, {"f": "srv", "t": "phone", "m": "* 12 FETCH (...)", "k": "data", "fields": [], "raw": "* 12 FETCH (FLAGS () ENVELOPE (\"Mon, 24 Nov 2026 09:12:00 +0000\" \"Lunch?\" ...))\r\na3 OK FETCH completed\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Mark as read", "tag": "flags", "d": "<p>You open message 12. The app sets the Seen flag on the server. Your laptop will see it as read too.<\/p>", "f": [], "p": [{"f": "phone", "t": "srv", "m": "a4 STORE 12 +FLAGS (\\Seen)", "k": "req", "fields": [], "raw": "a4 STORE 12 +FLAGS (\\Seen)\r\n", "hex": null}, {"f": "srv", "t": "phone", "m": "a4 OK", "k": "res", "fields": [], "raw": "* 12 FETCH (FLAGS (\\Seen))\r\na4 OK STORE completed\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Wait for new mail", "tag": "idle", "d": "<p>The app sends IDLE. When new mail arrives, the server pushes an untagged EXISTS line at once.<\/p>", "f": [], "p": [{"f": "phone", "t": "srv", "m": "a5 IDLE", "k": "req", "fields": [], "raw": "a5 IDLE\r\n", "hex": null}, {"f": "srv", "t": "phone", "m": "* 13 EXISTS", "k": "data", "fields": [], "raw": "+ idling\r\n* 13 EXISTS\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "What is the main difference between IMAP and POP3?", "opts": ["IMAP is older", "IMAP keeps mail and flags on the server and syncs devices", "POP3 supports folders"], "a": 1, "why": "POP3 usually downloads and deletes.", "type": "mcq"}, {"type": "fill", "q": "The IMAP command that lets the server push new mail at once is ____.", "a": ["IDLE"], "why": "IDLE keeps the connection waiting for updates."}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc9051\" target=\"_blank\" rel=\"noopener\">RFC 9051, IMAP4rev2<\/a>."]}, {"id": "ftp", "name": "FTP", "full": "File Transfer Protocol", "layer": 7, "cat": "app", "title": "FTP, a control line and a separate data line.", "port": "21 control, extra port for data", "transport": "TCP", "lede": "FTP uses one connection for commands and a second one for each file. Watch a login, passive mode and a download, all in plain text.", "overview": "<p>FTP is from the 1970s. Commands go over port 21. In <b>passive mode<\/b>, the server opens a port and tells the client which one, and the client connects to it for the data. The port is written as two numbers, so port = first times 256 plus second.<\/p>\n<div class=\"plain warn\"><span class=\"k\">Careful<\/span><p>FTP sends the password and files in plain text. Use SFTP, or FTPS which adds TLS.<\/p><\/div>", "nodes": {"cli": {"label": "FTP client", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "srv": {"label": "FTP server", "sub": "203.0.113.50", "icon": "folder", "x": 6, "y": 1}}, "links": [["cli", "srv"]], "steps": [{"t": "Greeting and login", "tag": "auth", "d": "<p>The client connects to port 21. The server greets with 220. USER and PASS follow, in plain text.<\/p>", "f": [], "p": [{"f": "srv", "t": "cli", "m": "220 FTP ready", "k": "ctl", "fields": [], "raw": "220 (vsFTPd 3.0.5)\r\n", "hex": null}, {"f": "cli", "t": "srv", "m": "USER asha", "k": "req", "fields": [], "raw": "USER asha\r\n", "hex": null}, {"f": "srv", "t": "cli", "m": "331 Please specify the password", "k": "ctl", "fields": [], "raw": "331 Please specify the password.\r\n", "hex": null}, {"f": "cli", "t": "srv", "m": "PASS secret123 (plain text)", "k": "bad", "fields": [], "raw": "PASS secret123\r\n", "hex": null}, {"f": "srv", "t": "cli", "m": "230 Login successful", "k": "res", "fields": [], "raw": "230 Login successful.\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Passive mode", "tag": "pasv", "d": "<p>The client sends PASV. The server answers with an address and two port numbers. 195 times 256 plus 80 is port 50000.<\/p>", "f": [["Reply", "227 (203,0,113,50,195,80)"], ["Data port", "50000"]], "p": [{"f": "cli", "t": "srv", "m": "PASV", "k": "req", "fields": [], "raw": "PASV\r\n", "hex": null}, {"f": "srv", "t": "cli", "m": "227 Entering Passive Mode (203,0,113,50,195,80)", "k": "res", "fields": [], "raw": "227 Entering Passive Mode (203,0,113,50,195,80).\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Download a file", "tag": "data", "d": "<p>The client opens a second connection to port 50000, then sends RETR on the control line. The file flows on the data line.<\/p>", "f": [], "p": [{"f": "cli", "t": "srv", "m": "data connection to :50000", "k": "ctl", "fields": [["Src port", "51800"], ["Dst port", "50000"], ["Flags", "SYN"], ["Seq", "8800"], ["Window", "64240"]], "raw": null, "hex": null}, {"f": "cli", "t": "srv", "m": "RETR report.pdf", "k": "req", "fields": [], "raw": "RETR report.pdf\r\n", "hex": null}, {"f": "srv", "t": "cli", "m": "150 Opening data connection", "k": "ctl", "fields": [], "raw": "150 Opening BINARY mode data connection for report.pdf (482113 bytes).\r\n", "hex": null}, {"f": "srv", "t": "cli", "m": "file bytes (data line)", "k": "data", "fields": [["Connection", "data, port 50000"], ["Bytes", "482113"], ["Content", "the PDF, not encrypted"]], "raw": null, "hex": null}, {"f": "srv", "t": "cli", "m": "226 Transfer complete", "k": "res", "fields": [], "raw": "226 Transfer complete.\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Quit", "tag": "close", "d": "<p>The client says QUIT and the server answers 221.<\/p>", "f": [], "p": [{"f": "cli", "t": "srv", "m": "QUIT", "k": "req", "fields": [], "raw": "QUIT\r\n", "hex": null}, {"f": "srv", "t": "cli", "m": "221 Goodbye", "k": "res", "fields": [], "raw": "221 Goodbye.\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "num", "q": "A PASV reply ends with (...,19,137). What is the data port?", "a": 5001, "tol": 0, "unit": "port", "why": "19 times 256 plus 137 is 5001."}, {"q": "What is the main risk of plain FTP?", "opts": ["It is slow", "Passwords and files travel in plain text", "It cannot send PDFs"], "a": 1, "why": "Use SFTP or FTPS.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc959\" target=\"_blank\" rel=\"noopener\">RFC 959, FTP<\/a>."]}, {"id": "smb", "name": "SMB", "full": "Windows file sharing", "layer": 7, "cat": "app", "title": "SMB, opening a file on a Windows share.", "port": "445", "transport": "TCP", "lede": "SMB is how Windows machines share files and printers. Watch dialect negotiation, login with Kerberos or NTLM, connecting to a share and reading a file.", "overview": "<p>Modern SMB is version 2 or 3 on TCP 445. <b>SMB 3<\/b> adds encryption. <b>Signing<\/b> stops tampering and relay attacks. <b>SMB 1<\/b> is old and unsafe. The WannaCry worm in 2017 spread through an SMB 1 bug called EternalBlue. Turn SMB 1 off, and never expose port 445 to the internet.<\/p>", "nodes": {"pc": {"label": "Windows PC", "sub": "10.0.0.25", "icon": "laptop", "x": 0, "y": 1}, "fs": {"label": "File server", "sub": "fs01", "icon": "folder", "x": 6, "y": 1}, "dc": {"label": "Domain controller", "sub": "Kerberos KDC", "icon": "key", "x": 3, "y": 3}}, "links": [["pc", "fs"], ["pc", "dc"]], "steps": [{"t": "Negotiate", "tag": "negotiate", "d": "<p>The client lists the SMB dialects it speaks. The server picks the highest common one, here 3.1.1, and says signing is required.<\/p>", "f": [["Dialects offered", "2.0.2, 2.1, 3.0, 3.0.2, 3.1.1"], ["Chosen", "3.1.1"]], "p": [{"f": "pc", "t": "fs", "m": "NEGOTIATE dialects 2.0.2 to 3.1.1", "k": "req", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0000 NEGOTIATE"], ["MessageId", "0"], ["DialectCount", "5"], ["Dialects", "0x0202, 0x0210, 0x0300, 0x0302, 0x0311"], ["SecurityMode", "0x0001 signing enabled"]], "raw": null, "hex": null}, {"f": "fs", "t": "pc", "m": "NEGOTIATE response 3.1.1", "k": "res", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0000 NEGOTIATE"], ["MessageId", "0"], ["Status", "0x00000000 STATUS_SUCCESS"], ["DialectRevision", "0x0311"], ["Contexts", "preauth integrity SHA-512, encryption AES-128-GCM"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Session setup", "tag": "auth", "d": "<p>The client logs in with SPNEGO. It gets a Kerberos ticket for <code>cifs/fs01<\/code> from the domain controller and sends it. NTLM is the fallback.<\/p>", "f": [], "p": [{"f": "pc", "t": "dc", "m": "TGS-REQ cifs/fs01", "k": "sec", "fields": [["pvno", "5"], ["msg type", "12 TGS-REQ"], ["realm", "CORP.EXAMPLE"], ["sname", "cifs/fs01"], ["padata", "AP-REQ with the TGT"]], "raw": null, "hex": null}, {"f": "dc", "t": "pc", "m": "service ticket", "k": "sec", "fields": [["pvno", "5"], ["msg type", "13 TGS-REP"], ["realm", "CORP.EXAMPLE"], ["sname", "cifs/fs01"], ["ticket", "encrypted with the file server key"]], "raw": null, "hex": null}, {"f": "pc", "t": "fs", "m": "SESSION_SETUP (Kerberos ticket)", "k": "sec", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0001 SESSION_SETUP"], ["MessageId", "1"], ["SecurityBuffer", "SPNEGO with the Kerberos AP-REQ"]], "raw": null, "hex": null}, {"f": "fs", "t": "pc", "m": "SESSION_SETUP success", "k": "res", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0001 SESSION_SETUP"], ["MessageId", "1"], ["Status", "0x00000000 STATUS_SUCCESS"], ["SessionId", "0x0000400000000005"], ["SessionFlags", "encrypt data"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Connect to the share", "tag": "tree", "d": "<p>TREE_CONNECT opens the share <code>\\\\fs01\\finance<\/code>. The server checks share permissions.<\/p>", "f": [], "p": [{"f": "pc", "t": "fs", "m": "TREE_CONNECT \\\\fs01\\finance", "k": "req", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0003 TREE_CONNECT"], ["MessageId", "2"], ["Path", "\\\\fs01\\finance"]], "raw": null, "hex": null}, {"f": "fs", "t": "pc", "m": "TREE_CONNECT response", "k": "res", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0003 TREE_CONNECT"], ["MessageId", "2"], ["Status", "0x00000000 STATUS_SUCCESS"], ["TreeId", "0x00000001"], ["ShareType", "0x01 disk"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Open, read and close", "tag": "file", "d": "<p>CREATE opens <code>budget.xlsx<\/code> and returns a file id. READ gets the data. CLOSE releases it. With SMB 3 encryption on, all of this is encrypted.<\/p>", "f": [], "p": [{"f": "pc", "t": "fs", "m": "CREATE budget.xlsx", "k": "req", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0005 CREATE"], ["MessageId", "3"], ["Name", "budget.xlsx"], ["DesiredAccess", "0x00120089 read"]], "raw": null, "hex": null}, {"f": "fs", "t": "pc", "m": "FileId 0x51", "k": "res", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0005 CREATE"], ["MessageId", "3"], ["Status", "0x00000000 STATUS_SUCCESS"], ["FileId", "0x51"]], "raw": null, "hex": null}, {"f": "pc", "t": "fs", "m": "READ FileId 0x51", "k": "req", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0008 READ"], ["MessageId", "4"], ["FileId", "0x51"], ["Offset", "0"], ["Length", "65536"]], "raw": null, "hex": null}, {"f": "fs", "t": "pc", "m": "data", "k": "data", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0008 READ"], ["MessageId", "4"], ["Status", "0x00000000 STATUS_SUCCESS"], ["DataLength", "48210"]], "raw": null, "hex": null}, {"f": "pc", "t": "fs", "m": "CLOSE", "k": "req", "fields": [["ProtocolId", "0xfe 'SMB'"], ["Command", "0x0006 CLOSE"], ["MessageId", "5"], ["FileId", "0x51"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "Modern SMB runs on TCP port ____.", "a": ["445"], "why": "Old NetBIOS based SMB also used 139."}, {"q": "Which SMB version should be turned off everywhere?", "opts": ["SMB 3.1.1", "SMB 1", "SMB 2.1"], "a": 1, "why": "SMB 1 is insecure and was used by WannaCry.", "type": "mcq"}], "refs": ["Microsoft. <a href=\"https://learn.microsoft.com/en-us/windows-server/storage/file-server/file-server-smb-overview\" target=\"_blank\" rel=\"noopener\">SMB overview<\/a>.", "Microsoft. <a href=\"https://techcommunity.microsoft.com/blog/filecab/stop-using-smb1/425858\" target=\"_blank\" rel=\"noopener\">Stop using SMB1<\/a>."]}, {"id": "nfs", "name": "NFS", "full": "Network File System", "layer": 7, "cat": "app", "title": "NFS, mounting a remote folder on Linux.", "port": "2049, 111 for rpcbind", "transport": "TCP", "lede": "NFS lets Linux machines mount a folder from a server as if it were local. Watch the older v3 flow with rpcbind and mountd, then file reads by file handle.", "overview": "<p>NFS uses ONC RPC. In <b>NFSv3<\/b>, the client asks <b>rpcbind<\/b> on port 111 where <b>mountd<\/b> runs, mounts the export to get a <b>file handle<\/b>, then talks to the NFS service on 2049. <b>NFSv4<\/b> uses only port 2049.<\/p>\n<div class=\"plain warn\"><span class=\"k\">Careful<\/span><p>With the default AUTH_SYS, the server trusts the user and group numbers that the client sends. Anyone who controls a client can claim any user id. Limit exports to trusted hosts, keep <code>root_squash<\/code> on, or use Kerberos with <code>sec=krb5<\/code>.<\/p><\/div>", "nodes": {"cli": {"label": "Linux client", "sub": "10.0.0.40", "icon": "terminal", "x": 0, "y": 1}, "rpc": {"label": "rpcbind", "sub": "port 111", "icon": "server", "x": 4, "y": 0}, "srv": {"label": "NFS server", "sub": "10.0.0.5 nfsd 2049", "icon": "folder", "x": 6, "y": 2}}, "links": [["cli", "rpc"], ["cli", "srv"], ["rpc", "srv"]], "steps": [{"t": "Where is mountd?", "tag": "rpc", "d": "<p><code>mount 10.0.0.5:/exports/data /mnt<\/code> first asks rpcbind for the port of the mount service.<\/p>", "f": [], "p": [{"f": "cli", "t": "rpc", "m": "GETPORT mountd v3", "k": "req", "fields": [["XID", "0x4c2e"], ["Message type", "0 call"], ["Program", "100000 portmapper"], ["Procedure", "3 GETPORT"], ["Asks for", "100005 mountd version 3, TCP"]], "raw": null, "hex": null}, {"f": "rpc", "t": "cli", "m": "port 20048", "k": "res", "fields": [["XID", "0x4c2e"], ["Message type", "1 reply"], ["Program", "100000 portmapper"], ["Procedure", "3 GETPORT"], ["Port", "20048"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Mount and get a file handle", "tag": "mount", "d": "<p>The client asks mountd to mount <code>/exports/data<\/code>. The server checks <code>/etc/exports<\/code> and returns a root file handle.<\/p>", "f": [], "p": [{"f": "cli", "t": "srv", "m": "MNT /exports/data", "k": "req", "fields": [["XID", "0x4c2f"], ["Message type", "0 call"], ["Program", "100005 mountd"], ["Procedure", "1 MNT"], ["Path", "/exports/data"]], "raw": null, "hex": null}, {"f": "srv", "t": "cli", "m": "file handle 0x1a2b...", "k": "res", "fields": [["XID", "0x4c2f"], ["Message type", "1 reply"], ["Program", "100005 mountd"], ["Procedure", "1 MNT"], ["Status", "0 OK"], ["File handle", "0x1a2b..."]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Find a file", "tag": "nfs", "d": "<p>To open report.txt, the client sends LOOKUP with the folder handle and the name. It gets the file handle back.<\/p>", "f": [["Credentials", "AUTH_SYS uid 1000 gid 1000"]], "p": [{"f": "cli", "t": "srv", "m": "LOOKUP report.txt (uid 1000)", "k": "req", "fields": [["XID", "0x4c30"], ["Message type", "0 call"], ["Program", "100003 nfs"], ["Procedure", "3 LOOKUP"], ["Credentials", "AUTH_SYS uid 1000 gid 1000"], ["Name", "report.txt"]], "raw": null, "hex": null}, {"f": "srv", "t": "cli", "m": "file handle 0x7c9e...", "k": "res", "fields": [["XID", "0x4c30"], ["Message type", "1 reply"], ["Program", "100003 nfs"], ["Procedure", "3 LOOKUP"], ["Status", "0 NFS3_OK"], ["File handle", "0x7c9e..."]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Read it", "tag": "nfs", "d": "<p>READ requests with the file handle, an offset and a count bring the data.<\/p>", "f": [], "p": [{"f": "cli", "t": "srv", "m": "READ offset 0 count 65536", "k": "req", "fields": [["XID", "0x4c31"], ["Message type", "0 call"], ["Program", "100003 nfs"], ["Procedure", "6 READ"], ["Offset", "0"], ["Count", "65536"]], "raw": null, "hex": null}, {"f": "srv", "t": "cli", "m": "data", "k": "data", "fields": [["XID", "0x4c31"], ["Message type", "1 reply"], ["Program", "100003 nfs"], ["Procedure", "6 READ"], ["Status", "0 NFS3_OK"], ["Count", "2810"], ["EOF", "1"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "NFS runs on port ____.", "a": ["2049"], "why": "rpcbind is 111."}, {"q": "What does the server trust with AUTH_SYS?", "opts": ["A password", "The user and group numbers that the client sends", "A certificate"], "a": 1, "why": "That is why exports must be limited and root_squash kept on.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc1813\" target=\"_blank\" rel=\"noopener\">RFC 1813, NFS version 3<\/a>.", "Linux man pages. <a href=\"https://man7.org/linux/man-pages/man5/exports.5.html\" target=\"_blank\" rel=\"noopener\">exports<\/a>."]}, {"id": "rsync", "name": "rsync", "full": "Fast file sync", "layer": 7, "cat": "app", "title": "rsync, sending only what changed.", "port": "873, or 22 over SSH", "transport": "TCP or SSH", "lede": "rsync copies folders and big files fast, because it sends only the changed parts of each file. Watch the daemon greeting and the delta algorithm.", "overview": "<p>rsync usually runs over SSH. It can also run as a <b>daemon<\/b> on port 873, with named <b>modules<\/b>. The <b>delta algorithm<\/b> works like this. The receiver splits its old copy into blocks and sends a weak rolling checksum and a strong hash for each. The sender slides over the new file, finds matching blocks, and sends only references to them plus the new bytes.<\/p>\n<div class=\"plain warn\"><span class=\"k\">Careful<\/span><p>A daemon module without <code>auth users<\/code> lets anyone read it. Never expose an open rsync daemon to the internet.<\/p><\/div>", "nodes": {"cli": {"label": "Backup server", "sub": "receiver", "icon": "server", "x": 0, "y": 1}, "srv": {"label": "rsync daemon", "sub": "files.example 873", "icon": "folder", "x": 6, "y": 1}}, "links": [["cli", "srv"]], "steps": [{"t": "Greeting", "tag": "hello", "d": "<p>The client connects to port 873. Both sides send their protocol version.<\/p>", "f": [], "p": [{"f": "srv", "t": "cli", "m": "@RSYNCD: 31.0", "k": "ctl", "fields": [], "raw": "@RSYNCD: 31.0\n", "hex": null}, {"f": "cli", "t": "srv", "m": "@RSYNCD: 31.0", "k": "ctl", "fields": [], "raw": "@RSYNCD: 31.0\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Pick a module and log in", "tag": "auth", "d": "<p>The client names the module <code>backups<\/code>. The server sends a challenge. The client answers with a hash of the challenge and the password.<\/p>", "f": [], "p": [{"f": "cli", "t": "srv", "m": "backups", "k": "req", "fields": [], "raw": "backups\n", "hex": null}, {"f": "srv", "t": "cli", "m": "@RSYNCD: AUTHREQD challenge", "k": "sec", "fields": [], "raw": "@RSYNCD: AUTHREQD 6Xm2ZgYb1kP9qWfT\n", "hex": null}, {"f": "cli", "t": "srv", "m": "user + hashed response", "k": "sec", "fields": [], "raw": "backup-bot 3vW0Kp2bLq8sYx1aZ9rT\n", "hex": null}, {"f": "srv", "t": "cli", "m": "@RSYNCD: OK", "k": "res", "fields": [], "raw": "@RSYNCD: OK\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "File list", "tag": "list", "d": "<p>The sender sends the list of files with sizes and times. Unchanged files are skipped by default.<\/p>", "f": [], "p": [{"f": "srv", "t": "cli", "m": "file list", "k": "data", "fields": [["Entries", "3812 files"], ["Each", "name, size, modified time, mode"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Block checksums", "tag": "delta", "d": "<p>For a changed 1 GB file, the receiver sends checksums of the blocks it already has.<\/p>", "f": [], "p": [{"f": "cli", "t": "srv", "m": "block checksums (weak + strong)", "k": "ctl", "fields": [["Block size", "700"], ["Weak checksum", "rolling, 4 bytes"], ["Strong checksum", "MD5, 2 to 16 bytes"], ["Blocks", "per changed file"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Only the delta", "tag": "delta", "d": "<p>The sender finds matching blocks and sends &quot;use block 17&quot; and the few new bytes. A small edit in a big file costs a small transfer.<\/p>", "f": [], "p": [{"f": "srv", "t": "cli", "m": "match refs + literal bytes", "k": "data", "fields": [["Instructions", "copy block 4, copy block 5, literal 312 bytes, copy block 6"], ["Saved", "most of the file is not sent"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"q": "Why is rsync fast for a big file with a small change?", "opts": ["It compresses everything", "It sends only blocks that do not match the old copy", "It uses UDP"], "a": 1, "why": "Rolling checksums find the unchanged blocks.", "type": "mcq"}, {"type": "fill", "q": "The rsync daemon listens on port ____.", "a": ["873"], "why": "Over SSH it uses 22 instead."}], "refs": ["Andrew Tridgell and Paul Mackerras. <a href=\"https://rsync.samba.org/tech_report/\" target=\"_blank\" rel=\"noopener\">The rsync algorithm<\/a>.", "rsync. <a href=\"https://download.samba.org/pub/rsync/rsyncd.conf.5\" target=\"_blank\" rel=\"noopener\">rsyncd.conf manual<\/a>."]}, {"id": "telnet", "name": "Telnet", "full": "Old plain text remote login", "layer": 7, "cat": "app", "title": "Telnet, why we replaced it with SSH.", "port": "23", "transport": "TCP", "lede": "Telnet gives a remote terminal like SSH, but without any encryption. Watch the option negotiation, then a password that anyone on the path can read.", "overview": "<p>Telnet sends options with <b>IAC<\/b>, the byte 255, followed by commands such as DO, DONT, WILL and WONT. Then text flows as it is. Some network devices still use it, but you should replace it with SSH everywhere.<\/p>", "nodes": {"cli": {"label": "Laptop", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "eve": {"label": "Listener on the path", "sub": "sees everything", "icon": "user", "x": 3, "y": 3}, "dev": {"label": "Old switch", "sub": "192.168.1.2", "icon": "switch", "x": 6, "y": 1}}, "links": [["cli", "dev"], ["cli", "eve"], ["eve", "dev"]], "steps": [{"t": "Option negotiation", "tag": "options", "d": "<p>After TCP connects to port 23, the device and client agree options, such as echo and terminal type, with IAC commands.<\/p>", "f": [["IAC", "255"], ["WILL", "251"], ["DO", "253"], ["ECHO", "option 1"]], "p": [{"f": "dev", "t": "cli", "m": "IAC WILL ECHO, IAC DO TERMINAL-TYPE", "k": "ctl", "fields": [["IAC", "255"], ["WILL", "251"], ["Option", "1 ECHO"], ["IAC 2", "255"], ["DO", "253"], ["Option 2", "24 TERMINAL-TYPE"]], "raw": null, "hex": "ff fb 01 ff fd 18"}, {"f": "cli", "t": "dev", "m": "IAC DO ECHO, IAC WILL TERMINAL-TYPE", "k": "ctl", "fields": [["IAC", "255"], ["DO", "253"], ["Option", "1 ECHO"], ["IAC 2", "255"], ["WILL", "251"], ["Option 2", "24 TERMINAL-TYPE"]], "raw": null, "hex": "ff fd 01 ff fb 18"}], "on": [], "good": "", "bad": []}, {"t": "Login prompt", "tag": "login", "d": "<p>The device sends a login prompt. You type your username.<\/p>", "f": [], "p": [{"f": "dev", "t": "cli", "m": "login:", "k": "ctl", "fields": [], "raw": "\r\nUser Access Verification\r\n\r\nlogin: ", "hex": null}, {"f": "cli", "t": "dev", "m": "admin", "k": "req", "fields": [], "raw": "admin\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Password in plain text", "tag": "risk", "d": "<p>You type the password. It crosses the network as plain characters. The listener reads it.<\/p>", "f": [], "p": [{"f": "cli", "t": "dev", "m": "Sw1tchPass! (plain text)", "k": "bad", "fields": [], "raw": "Sw1tchPass!\r\n", "hex": null}], "on": [], "good": "", "bad": ["eve"]}, {"t": "Commands in plain text", "tag": "risk", "d": "<p>Every command and every reply is readable and can even be changed in transit.<\/p>", "f": [], "p": [{"f": "cli", "t": "dev", "m": "show running-config", "k": "req", "fields": [], "raw": "show running-config\r\n", "hex": null}, {"f": "dev", "t": "cli", "m": "config with secrets", "k": "data", "fields": [], "raw": "hostname core-sw1\r\nenable secret 5 $1$mERr$hx5rVt7rPNoS4wqbXKX7m0\r\nsnmp-server community public RO\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "Telnet uses TCP port ____.", "a": ["23"], "why": "SSH uses 22."}, {"q": "What should replace Telnet?", "opts": ["FTP", "SSH", "HTTP"], "a": 1, "why": "SSH gives the same remote shell with encryption and host keys.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc854\" target=\"_blank\" rel=\"noopener\">RFC 854, Telnet protocol<\/a>."]}, {"id": "snmp", "name": "SNMP", "full": "Network device monitoring", "layer": 7, "cat": "app", "title": "SNMP, asking a router how it feels.", "port": "161, 162 for traps", "transport": "UDP", "lede": "Monitoring systems use SNMP to read counters from routers, switches and printers, and devices send traps when something breaks. Watch a get, a walk and a trap.", "overview": "<p>Each value has an <b>OID<\/b>, a dotted number path in the <b>MIB<\/b> tree. <code>1.3.6.1.2.1.1.5.0<\/code> is the device name, sysName. <b>SNMPv1<\/b> and <b>v2c<\/b> use a <b>community string<\/b>, such as &quot;public&quot;, sent in plain text, which acts as a password. <b>SNMPv3<\/b> adds real users, authentication and encryption.<\/p>", "nodes": {"nms": {"label": "Monitoring server", "sub": "10.0.0.9", "icon": "server", "x": 0, "y": 1}, "rtr": {"label": "Router", "sub": "agent 10.0.0.1", "icon": "router", "x": 6, "y": 1}}, "links": [["nms", "rtr"]], "steps": [{"t": "GetRequest", "tag": "get", "d": "<p>The monitoring server asks the router for its name with an SNMPv2c GetRequest on UDP 161.<\/p>", "f": [["Version", "v2c"], ["Community", "monitor-ro (plain text)"], ["OID", "1.3.6.1.2.1.1.5.0 sysName"]], "p": [{"f": "nms", "t": "rtr", "m": "GetRequest 1.3.6.1.2.1.1.5.0", "k": "req", "fields": [["Version", "1 v2c"], ["Community", "monitor-ro"], ["PDU type", "0xa0 GetRequest"], ["Request ID", "1011"], ["OID", "1.3.6.1.2.1.1.5.0 sysName"]], "raw": null, "hex": null}, {"f": "rtr", "t": "nms", "m": "Response sysName = core-rtr-1", "k": "res", "fields": [["Version", "1 v2c"], ["Community", "monitor-ro"], ["PDU type", "0xa2 Response"], ["Request ID", "1011"], ["Value", "core-rtr-1"], ["Error status", "0"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Walk a table", "tag": "walk", "d": "<p>GetBulk walks the interface table and gets traffic counters for every port in one go.<\/p>", "f": [], "p": [{"f": "nms", "t": "rtr", "m": "GetBulkRequest ifTable", "k": "req", "fields": [["Version", "1 v2c"], ["Community", "monitor-ro"], ["PDU type", "0xa5 GetBulkRequest"], ["Request ID", "1012"], ["Non repeaters", "0"], ["Max repetitions", "10"], ["OID", "1.3.6.1.2.1.2.2 ifTable"]], "raw": null, "hex": null}, {"f": "rtr", "t": "nms", "m": "Response ifInOctets, ifOutOctets ...", "k": "res", "fields": [["Version", "1 v2c"], ["Community", "monitor-ro"], ["PDU type", "0xa2 Response"], ["Request ID", "1012"], ["Values", "ifInOctets.1 9284012, ifOutOctets.1 1182733, and more"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "A trap", "tag": "trap", "d": "<p>A link goes down. The router does not wait to be asked. It sends a trap to the monitoring server on UDP 162.<\/p>", "f": [], "p": [{"f": "rtr", "t": "nms", "m": "Trap linkDown ifIndex 3", "k": "bad", "fields": [["Version", "1 v2c"], ["Community", "monitor-ro"], ["PDU type", "0xa7 SNMPv2-Trap"], ["Request ID", "77"], ["snmpTrapOID", "1.3.6.1.6.3.1.1.5.3 linkDown"], ["ifIndex", "3"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The weak spot", "tag": "risk", "d": "<p>The community string travels in plain text. Default strings such as &quot;public&quot; and &quot;private&quot; are well known. Use SNMPv3 with authentication and privacy, and read only access.<\/p>", "f": [], "p": [], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "SNMP agents listen on UDP port ____.", "a": ["161"], "why": "Traps go to 162 on the manager."}, {"q": "Which SNMP version gives authentication and encryption?", "opts": ["v1", "v2c", "v3"], "a": 2, "why": "v1 and v2c only have plain community strings.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc3411\" target=\"_blank\" rel=\"noopener\">RFC 3411, SNMP architecture<\/a>."]}, {"id": "modbus", "name": "Modbus", "full": "Industrial control (OT)", "layer": 7, "cat": "app", "title": "Modbus, a control system reads and writes a machine.", "port": "502", "transport": "TCP", "lede": "Factories, water plants and power systems still use Modbus. It is simple and fast, and it has no login at all. Anyone who can reach port 502 can read and change values.", "overview": "<p>A Modbus TCP message has an <b>MBAP header<\/b>, a transaction id, a protocol id of 0, a length and a unit id, then a <b>function code<\/b> and data. Code 03 reads holding registers. Code 06 writes one register. An error reply sets the top bit of the function code, so 03 becomes 0x83.<\/p>\n<div class=\"plain warn\"><span class=\"k\">Careful<\/span><p>Modbus has no authentication or encryption. Keep it on isolated networks, behind industrial firewalls that allow only known masters and function codes.<\/p><\/div>", "nodes": {"scada": {"label": "SCADA server", "sub": "10.50.0.10", "icon": "server", "x": 0, "y": 1}, "fw": {"label": "Industrial firewall", "sub": "allow list", "icon": "shield", "x": 3, "y": 1}, "plc": {"label": "PLC", "sub": "pump controller 10.50.1.20", "icon": "plc", "x": 6, "y": 1}, "x": {"label": "Unknown laptop", "sub": "10.50.0.99", "icon": "laptop", "x": 3, "y": 3}}, "links": [["scada", "fw"], ["fw", "plc"], ["x", "fw"]], "steps": [{"t": "Read registers", "tag": "read", "d": "<p>The SCADA server reads two holding registers starting at address 0, the tank level and the pump speed.<\/p>", "f": [["Transaction", "0x0001"], ["Unit", "1"], ["Function", "03 read holding registers"], ["Start", "0"], ["Quantity", "2"]], "p": [{"f": "scada", "t": "plc", "m": "FC 03 read 2 registers from 0", "k": "req", "fields": [["MBAP", "0001 0000 0006 01"], ["PDU", "03 0000 0002"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "The values", "tag": "read", "d": "<p>The PLC answers with a byte count of 4 and the two values, 1820 and 1450.<\/p>", "f": [], "p": [{"f": "plc", "t": "scada", "m": "FC 03 bytes 4: 1820, 1450", "k": "res", "fields": [["PDU", "03 04 071C 05AA"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Write a setpoint", "tag": "write", "d": "<p>The operator lowers the pump speed. The server writes 1200 to register 1 with function code 06. The PLC echoes the request to confirm.<\/p>", "f": [], "p": [{"f": "scada", "t": "plc", "m": "FC 06 write register 1 = 1200", "k": "req", "fields": [["Transaction ID", "1"], ["Protocol ID", "0"], ["Length", "6"], ["Unit ID", "1"], ["Function code", "6 write single register"], ["Register address", "1"], ["Value", "1200"]], "raw": null, "hex": "00 01 00 00 00 06 01 06 00 01 04 b0"}, {"f": "plc", "t": "scada", "m": "FC 06 echo", "k": "res", "fields": [["Transaction ID", "2"], ["Protocol ID", "0"], ["Length", "6"], ["Unit ID", "1"], ["Function code", "6 write single register"], ["Register address", "1"], ["Value", "1200"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "An exception", "tag": "error", "d": "<p>A request for register 9000 does not exist. The PLC answers with function code 0x83 and exception code 02, illegal data address.<\/p>", "f": [], "p": [{"f": "scada", "t": "plc", "m": "FC 03 read from 9000", "k": "req", "fields": [["Transaction ID", "3"], ["Protocol ID", "0"], ["Length", "6"], ["Unit ID", "1"], ["Function code", "3 read holding registers"], ["Start address", "9000"], ["Quantity", "2"]], "raw": null, "hex": null}, {"f": "plc", "t": "scada", "m": "FC 0x83 exception 02", "k": "bad", "fields": [["Transaction ID", "3"], ["Protocol ID", "0"], ["Length", "3"], ["Unit ID", "1"], ["Function code", "0x83 error for 3"], ["Exception code", "2 illegal data address"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "An unknown device tries to write", "tag": "risk", "d": "<p>A laptop that should not be here sends a write. Modbus itself would accept it. The industrial firewall blocks it, because this source is not on the allow list.<\/p>", "f": [], "p": [{"f": "x", "t": "fw", "m": "FC 06 write (blocked)", "k": "bad", "fields": [["Transaction ID", "9"], ["Protocol ID", "0"], ["Length", "6"], ["Unit ID", "1"], ["Function code", "6 write single register"], ["Register address", "1"], ["Value", "9999"], ["Src", "10.50.0.99 not on the allow list"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": ["x"]}], "quiz": [{"type": "fill", "q": "Modbus TCP uses port ____.", "a": ["502"], "why": "There is no built in authentication on that port."}, {"q": "A reply has function code 0x83. What does it mean?", "opts": ["Success", "An exception for function 03", "A write"], "a": 1, "why": "Errors add 0x80 to the function code.", "type": "mcq"}], "refs": ["Modbus Organization. <a href=\"https://www.modbus.org/specs.php\" target=\"_blank\" rel=\"noopener\">Modbus application protocol specification<\/a>.", "CISA. <a href=\"https://www.cisa.gov/topics/industrial-control-systems\" target=\"_blank\" rel=\"noopener\">Industrial control systems security<\/a>."]}, {"id": "redis", "name": "Redis", "full": "RESP, the Redis protocol", "layer": 7, "cat": "data", "title": "Redis, simple text commands to a fast store.", "port": "6379", "transport": "TCP", "lede": "Redis speaks RESP, a simple text protocol. An app logs in, sets and gets keys, and every command is a short array of strings. Watch them on the wire.", "overview": "<p>In RESP, <code>*3<\/code> means an array of 3 items, and <code>$3<\/code> means the next string has 3 bytes. Simple replies start with <code>+<\/code>, errors with <code>-<\/code>, numbers with <code>:<\/code> and strings with <code>$<\/code>.<\/p>\n<div class=\"plain warn\"><span class=\"k\">Careful<\/span><p>Never expose Redis to the internet. Since Redis 3.2, protected mode refuses outside connections when no password is set. Use ACL users with passwords, TLS and a private network.<\/p><\/div>", "nodes": {"app": {"label": "App server", "sub": "10.0.1.20", "icon": "server", "x": 0, "y": 1}, "redis": {"label": "Redis", "sub": "10.0.2.30", "icon": "db", "x": 6, "y": 1}}, "links": [["app", "redis"]], "steps": [{"t": "Log in", "tag": "auth", "d": "<p>The app sends AUTH with an ACL user and password. Redis answers +OK.<\/p>", "f": [], "p": [{"f": "app", "t": "redis", "m": "AUTH app ********", "k": "sec", "fields": [], "raw": "*3\r\n$4\r\nAUTH\r\n$3\r\napp\r\n$8\r\ns3cretpw\r\n", "hex": null}, {"f": "redis", "t": "app", "m": "+OK", "k": "res", "fields": [], "raw": "+OK\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Set a key with a TTL", "tag": "write", "d": "<p>SET with EX 300 stores the session for 300 seconds.<\/p>", "f": [], "p": [{"f": "app", "t": "redis", "m": "SET session:42 alice EX 300", "k": "req", "fields": [], "raw": "*5\r\n$3\r\nSET\r\n$10\r\nsession:42\r\n$5\r\nalice\r\n$2\r\nEX\r\n$3\r\n300\r\n", "hex": null}, {"f": "redis", "t": "app", "m": "+OK", "k": "res", "fields": [], "raw": "+OK\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Get it back", "tag": "read", "d": "<p>GET returns a bulk string of 5 bytes.<\/p>", "f": [], "p": [{"f": "app", "t": "redis", "m": "GET session:42", "k": "req", "fields": [], "raw": "*2\r\n$3\r\nGET\r\n$10\r\nsession:42\r\n", "hex": null}, {"f": "redis", "t": "app", "m": "$5 alice", "k": "res", "fields": [], "raw": "$5\r\nalice\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Pipelining", "tag": "speed", "d": "<p>The app sends three INCR commands without waiting, then reads three replies. One round trip instead of three.<\/p>", "f": [], "p": [{"f": "app", "t": "redis", "m": "INCR views:a, INCR views:b, INCR views:c", "k": "req", "fields": [], "raw": "*2\r\n$4\r\nINCR\r\n$7\r\nviews:a\r\n*2\r\n$4\r\nINCR\r\n$7\r\nviews:b\r\n*2\r\n$4\r\nINCR\r\n$7\r\nviews:c\r\n", "hex": null}, {"f": "redis", "t": "app", "m": ":18, :4, :77", "k": "res", "fields": [], "raw": ":18\r\n:4\r\n:77\r\n", "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "Redis listens on TCP port ____ by default.", "a": ["6379"], "why": "Keep it on a private network."}, {"q": "In RESP, what does $5 mean?", "opts": ["Five commands", "A string of 5 bytes follows", "Error 5"], "a": 1, "why": "The length comes first, so binary data is safe.", "type": "mcq"}], "refs": ["Redis. <a href=\"https://redis.io/docs/latest/develop/reference/protocol-spec/\" target=\"_blank\" rel=\"noopener\">Redis serialization protocol specification<\/a>.", "Redis. <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/management/security/\" target=\"_blank\" rel=\"noopener\">Security<\/a>."]}, {"id": "mysql", "name": "MySQL", "full": "MySQL client protocol", "layer": 7, "cat": "data", "title": "MySQL, from greeting to a result set.", "port": "3306", "transport": "TCP", "lede": "In MySQL the server speaks first. It sends a greeting with a random scramble, the client switches to TLS, logs in, sends a query and reads rows.", "overview": "<p>The server greeting, <b>Initial Handshake v10<\/b>, has the server version, a connection id, random <b>scramble<\/b> data and the auth plugin. MySQL 8 uses <b>caching_sha2_password<\/b> by default. The client can send an <b>SSLRequest<\/b> to switch to TLS before it sends any login data.<\/p>", "nodes": {"app": {"label": "App server", "sub": "10.0.1.20", "icon": "server", "x": 0, "y": 1}, "db": {"label": "MySQL server", "sub": "10.0.2.40", "icon": "db", "x": 6, "y": 1}}, "links": [["app", "db"]], "steps": [{"t": "Server greeting", "tag": "hello", "d": "<p>After TCP connects, the server sends its greeting with version 8.0, a scramble and the auth plugin name.<\/p>", "f": [["Protocol", "10"], ["Version", "8.0.x"], ["Plugin", "caching_sha2_password"]], "p": [{"f": "db", "t": "app", "m": "Initial Handshake v10 + scramble", "k": "ctl", "fields": [["Payload length", "74"], ["Sequence id", "0"], ["Protocol version", "10"], ["Server version", "8.0.40"], ["Connection id", "182"], ["Auth plugin", "caching_sha2_password"], ["Scramble", "20 random bytes"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Switch to TLS", "tag": "tls", "d": "<p>The client sends a short SSLRequest, then a TLS handshake. Everything after is encrypted.<\/p>", "f": [], "p": [{"f": "app", "t": "db", "m": "SSLRequest", "k": "sec", "fields": [["Payload length", "32"], ["Sequence id", "1"], ["Capability flags", "CLIENT_SSL set"], ["Note", "SSLRequest, then TLS starts"]], "raw": null, "hex": null}, {"f": "app", "t": "db", "m": "TLS handshake", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "512"], ["Handshake type", "0x01 ClientHello"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Log in", "tag": "auth", "d": "<p>The client sends HandshakeResponse with the user name and a response computed from the password and the scramble. The server answers OK.<\/p>", "f": [], "p": [{"f": "app", "t": "db", "m": "HandshakeResponse user=shop", "k": "sec", "fields": [["Payload length", "96"], ["Sequence id", "2"], ["Username", "shop"], ["Auth plugin", "caching_sha2_password"], ["Auth response", "32 byte scrambled hash"], ["Database", "shop"]], "raw": null, "hex": null}, {"f": "db", "t": "app", "m": "OK", "k": "res", "fields": [["Payload length", "7"], ["Sequence id", "3"], ["Header", "0x00 OK"], ["Affected rows", "0"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Query and result", "tag": "query", "d": "<p>COM_QUERY carries the SQL. The result has a column count, column definitions, the rows, and an end marker.<\/p>", "f": [], "p": [{"f": "app", "t": "db", "m": "COM_QUERY SELECT id,name FROM users LIMIT 2", "k": "req", "fields": [["Payload length", "38"], ["Sequence id", "0"], ["Command", "0x03 COM_QUERY"], ["Query", "SELECT id,name FROM users LIMIT 2"]], "raw": null, "hex": null}, {"f": "db", "t": "app", "m": "column count 2, column defs", "k": "res", "fields": [["Payload length", "1"], ["Sequence id", "1"], ["Column count", "2"], ["Then", "two column definition packets, id and name"]], "raw": null, "hex": null}, {"f": "db", "t": "app", "m": "row 1, row 2, EOF/OK", "k": "data", "fields": [["Payload length", "9"], ["Sequence id", "4"], ["Row 1", "1, asha"], ["Row 2", "2, ben"], ["End", "0xfe OK packet"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "MySQL listens on TCP port ____ by default.", "a": ["3306"], "why": "Never expose it to the internet."}, {"q": "Who sends the first message on a MySQL connection?", "opts": ["The client", "The server, with its greeting"], "a": 1, "why": "The greeting carries the scramble the client needs.", "type": "mcq"}], "refs": ["MySQL. <a href=\"https://dev.mysql.com/doc/dev/mysql-server/latest/page_protocol_connection_phase.html\" target=\"_blank\" rel=\"noopener\">Client server protocol, connection phase<\/a>."]}, {"id": "postgres", "name": "PostgreSQL", "full": "Postgres wire protocol", "layer": 7, "cat": "data", "title": "PostgreSQL, startup, SCRAM login and a query.", "port": "5432", "transport": "TCP", "lede": "The Postgres client asks for TLS, sends a startup message, proves the password with SCRAM-SHA-256 without sending it, and runs a query.", "overview": "<p>Every message has a one letter type, then a length. <b>Q<\/b> is a simple query, <b>T<\/b> is a row description, <b>D<\/b> is a data row, <b>C<\/b> is command complete, <b>Z<\/b> is ready for query. Since PostgreSQL 14, the default password method is <b>SCRAM-SHA-256<\/b>, which never sends the password itself.<\/p>", "nodes": {"app": {"label": "App server", "sub": "10.0.1.20", "icon": "server", "x": 0, "y": 1}, "pg": {"label": "PostgreSQL", "sub": "10.0.2.50", "icon": "db", "x": 6, "y": 1}}, "links": [["app", "pg"]], "steps": [{"t": "Ask for TLS", "tag": "tls", "d": "<p>The client sends SSLRequest. The server answers with one byte, S, which means yes. A TLS handshake follows.<\/p>", "f": [], "p": [{"f": "app", "t": "pg", "m": "SSLRequest", "k": "sec", "fields": [["Length", "8"], ["Request code", "80877103 SSLRequest"]], "raw": null, "hex": null}, {"f": "pg", "t": "app", "m": "S", "k": "sec", "fields": [["Reply", "S"], ["Meaning", "yes, start TLS"]], "raw": null, "hex": null}, {"f": "app", "t": "pg", "m": "TLS handshake", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "512"], ["Handshake type", "0x01 ClientHello"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Startup message", "tag": "startup", "d": "<p>The client sends the protocol version, the user and the database name.<\/p>", "f": [["User", "shop"], ["Database", "orders"], ["Protocol", "3.0"]], "p": [{"f": "app", "t": "pg", "m": "StartupMessage user=shop database=orders", "k": "req", "fields": [["Length", "35"], ["Protocol", "0x00030000 version 3.0"], ["user", "shop"], ["database", "orders"]], "raw": null, "hex": "00 00 00 23 00 03 00 00 75 73 65 72 00 73 68 6f 70 00 64 61 74 61 62 61 73 65 00 6f 72 64 65 72 73 00 00"}], "on": [], "good": "", "bad": []}, {"t": "SCRAM login", "tag": "auth", "d": "<p>The server asks for SASL with SCRAM-SHA-256. Client and server swap nonces and proofs. The password never crosses the wire, and the client also checks the server.<\/p>", "f": [], "p": [{"f": "pg", "t": "app", "m": "AuthenticationSASL SCRAM-SHA-256", "k": "sec", "fields": [["Type", "R"], ["Length", "23"], ["Auth type", "10 SASL"], ["Mechanism", "SCRAM-SHA-256"]], "raw": null, "hex": null}, {"f": "app", "t": "pg", "m": "SASLInitialResponse (client nonce)", "k": "sec", "fields": [["Type", "p"], ["Length", "54"], ["Mechanism", "SCRAM-SHA-256"], ["Data", "n,,n=,r=rOprNGfwEbeRWgbNEkqO"]], "raw": null, "hex": null}, {"f": "pg", "t": "app", "m": "SASLContinue (salt, iterations)", "k": "sec", "fields": [["Type", "R"], ["Length", "92"], ["Auth type", "11 SASL continue"], ["Data", "r=rOprNG...%hvYDpWUa2RaTCAfuxFIlj)hNlF$k0, s=W22ZaJ0SNY7soEsUEjb6gQ==, i=4096"]], "raw": null, "hex": null}, {"f": "app", "t": "pg", "m": "SASLResponse (client proof)", "k": "sec", "fields": [["Type", "p"], ["Length", "108"], ["Data", "c=biws, r=..., p=client proof, 32 bytes base64"]], "raw": null, "hex": null}, {"f": "pg", "t": "app", "m": "SASLFinal + AuthenticationOk", "k": "sec", "fields": [["Type", "R"], ["Length", "54"], ["Auth type", "12 SASL final, then 0 AuthenticationOk"], ["Data", "v=server signature"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Ready", "tag": "ready", "d": "<p>The server sends ParameterStatus messages, BackendKeyData for cancelling queries, and ReadyForQuery Z.<\/p>", "f": [], "p": [{"f": "pg", "t": "app", "m": "ParameterStatus, BackendKeyData, ReadyForQuery", "k": "res", "fields": [["Type", "S"], ["Length", "25"], ["Then", "K BackendKeyData, Z ReadyForQuery idle"], ["Example", "server_version 16.4"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Simple query", "tag": "query", "d": "<p>The client sends Q with the SQL. The server returns T, then D for each row, then C and Z.<\/p>", "f": [], "p": [{"f": "app", "t": "pg", "m": "Q SELECT id, total FROM orders LIMIT 2", "k": "req", "fields": [["Type", "Q"], ["Length", "41"], ["Query", "SELECT id, total FROM orders LIMIT 2"]], "raw": null, "hex": null}, {"f": "pg", "t": "app", "m": "T RowDescription", "k": "res", "fields": [["Type", "T"], ["Length", "48"], ["Fields", "2"], ["Names", "id, total"]], "raw": null, "hex": null}, {"f": "pg", "t": "app", "m": "D row, D row", "k": "data", "fields": [["Type", "D"], ["Length", "21"], ["Row 1", "1001, 59.90"], ["Row 2", "1002, 12.50"]], "raw": null, "hex": null}, {"f": "pg", "t": "app", "m": "C SELECT 2, Z", "k": "res", "fields": [["Type", "C"], ["Length", "13"], ["Tag", "SELECT 2"], ["Then", "Z ReadyForQuery idle"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "PostgreSQL listens on TCP port ____.", "a": ["5432"], "why": "The default port."}, {"q": "What is the benefit of SCRAM-SHA-256?", "opts": ["Faster queries", "The password is never sent, and both sides prove themselves", "No TLS needed"], "a": 1, "why": "Still use TLS to protect the data.", "type": "mcq"}], "refs": ["PostgreSQL. <a href=\"https://www.postgresql.org/docs/current/protocol-flow.html\" target=\"_blank\" rel=\"noopener\">Frontend and backend protocol, message flow<\/a>."]}, {"id": "mssql", "name": "MSSQL", "full": "TDS, Microsoft SQL Server", "layer": 7, "cat": "data", "title": "SQL Server, TDS from prelogin to rows.", "port": "1433, UDP 1434 browser", "transport": "TCP", "lede": "SQL Server clients speak TDS, Tabular Data Stream. Watch the prelogin, TLS, the login, a SQL batch and the tokens that carry the result.", "overview": "<p>A default instance listens on TCP 1433. Named instances use other ports, and the <b>SQL Server Browser<\/b> service on UDP 1434 tells clients which. In TDS 7.x, the <b>PRELOGIN<\/b> packet agrees on encryption, then the TLS handshake runs inside TDS packets. TDS 8.0 does TLS first. Results come as tokens, such as <b>COLMETADATA<\/b>, <b>ROW<\/b> and <b>DONE<\/b>.<\/p>", "nodes": {"app": {"label": "App server", "sub": "10.0.1.20", "icon": "server", "x": 0, "y": 1}, "sql": {"label": "SQL Server", "sub": "10.0.2.60", "icon": "db", "x": 6, "y": 1}}, "links": [["app", "sql"]], "steps": [{"t": "PRELOGIN", "tag": "hello", "d": "<p>The client sends its version and asks for encryption. The server answers with its version and agrees.<\/p>", "f": [["Encryption", "required"]], "p": [{"f": "app", "t": "sql", "m": "PRELOGIN version, ENCRYPT_ON", "k": "ctl", "fields": [["Packet type", "0x12 PRELOGIN"], ["Status", "0x01 end of message"], ["Length", "47"], ["Options", "VERSION, ENCRYPTION, INSTOPT, THREADID"], ["ENCRYPTION", "0x01 ENCRYPT_ON"]], "raw": null, "hex": null}, {"f": "sql", "t": "app", "m": "PRELOGIN response", "k": "ctl", "fields": [["Packet type", "0x04 tabular result"], ["Status", "0x01 end of message"], ["Length", "43"], ["Options", "VERSION 16.0, ENCRYPTION"], ["ENCRYPTION", "0x03 ENCRYPT_REQ"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "TLS", "tag": "tls", "d": "<p>The TLS handshake runs inside TDS packets. The login that follows is encrypted.<\/p>", "f": [], "p": [{"f": "app", "t": "sql", "m": "TLS handshake (in TDS)", "k": "sec", "fields": [["Packet type", "0x12 PRELOGIN"], ["Status", "0x01 end of message"], ["Length", "517"], ["Contains", "TLS handshake bytes wrapped in TDS"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "LOGIN7", "tag": "auth", "d": "<p>The client sends LOGIN7 with the user, the database and the app name. Integrated Windows login can use Kerberos instead of a password.<\/p>", "f": [], "p": [{"f": "app", "t": "sql", "m": "LOGIN7 user=shop db=Sales", "k": "sec", "fields": [["Packet type", "0x10 TDS7 LOGIN"], ["Status", "0x01 end of message"], ["Length", "188"], ["UserName", "shop"], ["Database", "Sales"], ["Password", "inside TLS"]], "raw": null, "hex": null}, {"f": "sql", "t": "app", "m": "LOGINACK, ENVCHANGE database=Sales", "k": "res", "fields": [["Packet type", "0x04 tabular result"], ["Status", "0x01 end of message"], ["Length", "392"], ["Tokens", "0xAD LOGINACK, 0xE3 ENVCHANGE database Sales"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "SQL batch and result", "tag": "query", "d": "<p>The client sends a SQL batch. The server returns COLMETADATA, ROW tokens and DONE with the row count.<\/p>", "f": [], "p": [{"f": "app", "t": "sql", "m": "SQL Batch SELECT TOP 2 id, name FROM Customers", "k": "req", "fields": [["Packet type", "0x01 SQL batch"], ["Status", "0x01 end of message"], ["Length", "92"], ["SQL", "SELECT TOP 2 id, name FROM Customers"]], "raw": null, "hex": null}, {"f": "sql", "t": "app", "m": "COLMETADATA, ROW, ROW, DONE (2 rows)", "k": "data", "fields": [["Packet type", "0x04 tabular result"], ["Status", "0x01 end of message"], ["Length", "140"], ["Tokens", "0x81 COLMETADATA, 0xD1 ROW, 0xD1 ROW, 0xFD DONE"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "The default SQL Server instance listens on TCP port ____.", "a": ["1433"], "why": "UDP 1434 is the browser service for named instances."}, {"q": "What does the PRELOGIN exchange decide?", "opts": ["The SQL query", "Versions and whether to encrypt", "The database name"], "a": 1, "why": "Login comes after, in LOGIN7.", "type": "mcq"}], "refs": ["Microsoft. <a href=\"https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-tds/b46a581a-39de-4745-b076-ec4dbb7d13ec\" target=\"_blank\" rel=\"noopener\">MS-TDS, Tabular Data Stream protocol<\/a>."]}, {"id": "oracle-tns", "name": "Oracle TNS", "full": "Oracle Net listener", "layer": 7, "cat": "data", "title": "Oracle TNS, the listener hands you to the database.", "port": "1521", "transport": "TCP", "lede": "Oracle clients first talk to a listener. The listener checks the service name in the connect request and accepts it, refuses it, or redirects the client to the database process.", "overview": "<p>TNS packets have types such as <b>CONNECT<\/b>, <b>ACCEPT<\/b>, <b>REFUSE<\/b>, <b>REDIRECT<\/b> and <b>DATA<\/b>. The connect request carries a <b>connect descriptor<\/b> with the service name. An unknown service gives the error ORA-12514. After that, authentication and SQL travel in DATA packets. <b>Oracle Native Network Encryption<\/b> or TLS protects the traffic.<\/p>", "nodes": {"app": {"label": "App server", "sub": "10.0.1.20", "icon": "server", "x": 0, "y": 1}, "lsn": {"label": "Listener", "sub": "port 1521", "icon": "server", "x": 4, "y": 0}, "db": {"label": "Database instance", "sub": "ORCLPDB1", "icon": "db", "x": 6, "y": 2}}, "links": [["app", "lsn"], ["app", "db"], ["lsn", "db"]], "steps": [{"t": "CONNECT to the listener", "tag": "connect", "d": "<p>The client sends a CONNECT packet with a connect descriptor naming the service.<\/p>", "f": [], "p": [{"f": "app", "t": "lsn", "m": "CONNECT (SERVICE_NAME=ORCLPDB1)", "k": "req", "fields": [], "raw": "(DESCRIPTION=(CONNECT_DATA=(SERVICE_NAME=ORCLPDB1))(ADDRESS=(PROTOCOL=TCP)(HOST=10.0.2.70)(PORT=1521)))", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Accept or redirect", "tag": "connect", "d": "<p>The listener knows the service. It accepts the connection, or redirects the client to a dispatcher port. An unknown service would get REFUSE with ORA-12514.<\/p>", "f": [], "p": [{"f": "lsn", "t": "app", "m": "ACCEPT", "k": "res", "fields": [["Packet length", "32"], ["Packet type", "2 ACCEPT"], ["Contents", "version 315, session data unit 8192"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Negotiate and authenticate", "tag": "auth", "d": "<p>DATA packets negotiate options and run the login. The server sends a session key and salt, and the client proves the password without sending it in clear.<\/p>", "f": [], "p": [{"f": "app", "t": "db", "m": "DATA protocol and option negotiation", "k": "ctl", "fields": [["Packet length", "150"], ["Packet type", "6 DATA"], ["Contents", "protocol and data type negotiation"]], "raw": null, "hex": null}, {"f": "db", "t": "app", "m": "DATA auth session key + salt", "k": "sec", "fields": [["Packet length", "410"], ["Packet type", "6 DATA"], ["Contents", "AUTH_SESSKEY encrypted, AUTH_VFR_DATA salt"]], "raw": null, "hex": null}, {"f": "app", "t": "db", "m": "DATA auth response", "k": "sec", "fields": [["Packet length", "520"], ["Packet type", "6 DATA"], ["Contents", "AUTH_SESSKEY from client, AUTH_PASSWORD encrypted"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Run SQL", "tag": "query", "d": "<p>SQL and rows now travel in DATA packets.<\/p>", "f": [], "p": [{"f": "app", "t": "db", "m": "DATA SELECT ...", "k": "req", "fields": [["Packet length", "210"], ["Packet type", "6 DATA"], ["Contents", "TTI function call with the SQL text"]], "raw": null, "hex": null}, {"f": "db", "t": "app", "m": "DATA rows", "k": "data", "fields": [["Packet length", "340"], ["Packet type", "6 DATA"], ["Contents", "rows in Oracle's internal format"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "The Oracle listener uses TCP port ____ by default.", "a": ["1521"], "why": "It routes clients to the right database service."}, {"q": "A client asks for a service the listener does not know. What happens?", "opts": ["It connects anyway", "The listener refuses with ORA-12514", "It creates the service"], "a": 1, "why": "Check the service name in the connect descriptor.", "type": "mcq"}], "refs": ["Oracle. <a href=\"https://docs.oracle.com/en/database/oracle/oracle-database/19/netag/\" target=\"_blank\" rel=\"noopener\">Net Services administrator guide<\/a>."]}, {"id": "rdp", "name": "RDP", "full": "Remote Desktop Protocol", "layer": 7, "cat": "data", "title": "RDP, a Windows desktop over the network.", "port": "3389", "transport": "TCP and UDP", "lede": "RDP shows a remote Windows desktop and sends your keyboard and mouse back. Watch the negotiation, TLS, the Network Level Authentication login and the screen updates.", "overview": "<p><b>Network Level Authentication<\/b>, NLA, uses <b>CredSSP<\/b> to log you in before the server creates a desktop session. That saves server resources and blocks many attacks, so keep it on. Never put RDP directly on the internet. Use a VPN or a gateway with MFA, because RDP is a top target for ransomware groups.<\/p>", "nodes": {"pc": {"label": "Your PC", "sub": "192.168.1.10", "icon": "laptop", "x": 0, "y": 1}, "gw": {"label": "VPN or RD gateway", "sub": "MFA", "icon": "shield", "x": 3, "y": 1}, "srv": {"label": "Windows server", "sub": "10.0.3.15", "icon": "server", "x": 6, "y": 1}}, "links": [["pc", "gw"], ["gw", "srv"]], "steps": [{"t": "Negotiate security", "tag": "negotiate", "d": "<p>The client sends an X.224 Connection Request listing the security it supports, TLS and CredSSP. The server picks CredSSP, which means NLA.<\/p>", "f": [], "p": [{"f": "pc", "t": "srv", "m": "X.224 Connection Request (TLS, CredSSP)", "k": "ctl", "fields": [["TPKT version", "3"], ["Length", "43"], ["X224 type", "0xe0 Connection Request"], ["Cookie", "mstshash=asha"], ["Requested protocols", "0x00000003 TLS and CredSSP"]], "raw": null, "hex": null}, {"f": "srv", "t": "pc", "m": "Connection Confirm (CredSSP)", "k": "ctl", "fields": [["TPKT version", "3"], ["Length", "19"], ["X224 type", "0xd0 Connection Confirm"], ["Selected protocol", "0x00000002 CredSSP"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "TLS", "tag": "tls", "d": "<p>A TLS handshake protects the rest. The client checks the server certificate.<\/p>", "f": [], "p": [{"f": "pc", "t": "srv", "m": "TLS handshake", "k": "sec", "fields": [["Content type", "0x16 handshake"], ["Version", "0x0303"], ["Length", "512"], ["Handshake type", "0x01 ClientHello"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "NLA login with CredSSP", "tag": "auth", "d": "<p>Inside TLS, CredSSP runs Kerberos or NTLM through SPNEGO. Only after success does the client send the credentials to the server for the session.<\/p>", "f": [], "p": [{"f": "pc", "t": "srv", "m": "TSRequest (SPNEGO token)", "k": "sec", "fields": [["TSRequest version", "6"], ["negoTokens", "SPNEGO with Kerberos or NTLM"], ["Inside", "TLS"]], "raw": null, "hex": null}, {"f": "srv", "t": "pc", "m": "TSRequest (token)", "k": "sec", "fields": [["TSRequest version", "6"], ["negoTokens", "server token"], ["pubKeyAuth", "binds the TLS key to the login"]], "raw": null, "hex": null}, {"f": "pc", "t": "srv", "m": "TSRequest (credentials)", "k": "sec", "fields": [["TSRequest version", "6"], ["authInfo", "user name and password, encrypted for the server only"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Set up the session", "tag": "setup", "d": "<p>MCS Connect sends client details, such as screen size and keyboard. Then channels for clipboard and sound join, and the server sends its capabilities.<\/p>", "f": [], "p": [{"f": "pc", "t": "srv", "m": "MCS Connect Initial (screen 1920x1080)", "k": "req", "fields": [["MCS", "Connect Initial"], ["Desktop width", "1920"], ["Desktop height", "1080"], ["Color depth", "32"], ["Channels", "rdpdr, rdpsnd, cliprdr"]], "raw": null, "hex": null}, {"f": "srv", "t": "pc", "m": "MCS Connect Response, Demand Active", "k": "res", "fields": [["MCS", "Connect Response"], ["Then", "Demand Active PDU with server capabilities"]], "raw": null, "hex": null}, {"f": "pc", "t": "srv", "m": "Confirm Active", "k": "req", "fields": [["PDU", "Confirm Active"], ["Capabilities", "bitmap, order, pointer, input"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Screen and input", "tag": "data", "d": "<p>The server sends compressed screen updates. The client sends keyboard and mouse events.<\/p>", "f": [], "p": [{"f": "srv", "t": "pc", "m": "bitmap updates", "k": "data", "fields": [["Update", "bitmap, compressed"], ["Region", "screen tiles that changed"], ["Transport", "TCP or UDP 3389"]], "raw": null, "hex": null}, {"f": "pc", "t": "srv", "m": "input events", "k": "data", "fields": [["Events", "mouse move 640 400, key down 0x1e"], ["PDU", "fast path input"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "RDP uses port ____ by default.", "a": ["3389"], "why": "Keep it behind a VPN or gateway."}, {"q": "What does Network Level Authentication do?", "opts": ["Makes the screen faster", "Logs the user in before the server creates a session", "Turns off TLS"], "a": 1, "why": "NLA uses CredSSP before any desktop is created.", "type": "mcq"}], "refs": ["Microsoft. <a href=\"https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-rdpbcgr/5073f4ed-1e93-45e1-b039-6e30c385867c\" target=\"_blank\" rel=\"noopener\">MS-RDPBCGR, basic connectivity and graphics<\/a>."]}, {"id": "winrm", "name": "WinRM", "full": "Windows Remote Management", "layer": 7, "cat": "data", "title": "WinRM, running a command on a Windows server.", "port": "5985, 5986 with HTTPS", "transport": "HTTP or HTTPS", "lede": "WinRM is how PowerShell Remoting and many tools run commands on Windows machines. It sends SOAP messages over HTTP and logs in with Kerberos.", "overview": "<p>WinRM implements <b>WS-Management<\/b>. A client POSTs SOAP envelopes to <code>/wsman<\/code>. To run a command, it creates a <b>shell<\/b>, sends a <b>command<\/b>, <b>receives<\/b> the output and deletes the shell. Authentication is usually <b>Negotiate<\/b>, Kerberos in a domain, which also encrypts the message body even on port 5985. Use 5986 with HTTPS outside domains.<\/p>", "nodes": {"admin": {"label": "Admin PC", "sub": "10.0.0.30", "icon": "laptop", "x": 0, "y": 1}, "dc": {"label": "Domain controller", "sub": "KDC", "icon": "key", "x": 3, "y": 3}, "srv": {"label": "Windows server", "sub": "web-02 10.0.3.22", "icon": "server", "x": 6, "y": 1}}, "links": [["admin", "srv"], ["admin", "dc"]], "steps": [{"t": "Get a Kerberos ticket", "tag": "auth", "d": "<p><code>Enter-PSSession web-02<\/code> gets a Kerberos ticket for <code>HTTP/web-02<\/code> from the domain controller.<\/p>", "f": [], "p": [{"f": "admin", "t": "dc", "m": "TGS-REQ HTTP/web-02", "k": "sec", "fields": [["pvno", "5"], ["msg type", "12 TGS-REQ"], ["realm", "CORP.EXAMPLE"], ["sname", "HTTP/web-02"], ["padata", "AP-REQ with the TGT"]], "raw": null, "hex": null}, {"f": "dc", "t": "admin", "m": "service ticket", "k": "sec", "fields": [["pvno", "5"], ["msg type", "13 TGS-REP"], ["realm", "CORP.EXAMPLE"], ["sname", "HTTP/web-02"], ["ticket", "encrypted with the web-02 machine key"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "First request and login", "tag": "auth", "d": "<p>The client POSTs to <code>/wsman<\/code> with an Authorization Negotiate header that carries the ticket. The server accepts it.<\/p>", "f": [], "p": [{"f": "admin", "t": "srv", "m": "POST /wsman Authorization Negotiate", "k": "sec", "fields": [], "raw": "POST /wsman HTTP/1.1\r\nHost: web-02:5985\r\nAuthorization: Negotiate YIIHGgYGKwYBBQUCoIIH...\r\nContent-Length: 0\r\n\r\n", "hex": null}, {"f": "srv", "t": "admin", "m": "200 OK", "k": "res", "fields": [], "raw": "HTTP/1.1 200\r\nWWW-Authenticate: Negotiate oYG3MIG0oAMKAQChCwYJKoZIgvcSAQIC...\r\nServer: Microsoft-HTTPAPI/2.0\r\n\r\n", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Create a shell", "tag": "shell", "d": "<p>A SOAP Create request opens a remote shell and returns a ShellId.<\/p>", "f": [], "p": [{"f": "admin", "t": "srv", "m": "SOAP Create shell", "k": "req", "fields": [["Action", "http://schemas.xmlsoap.org/ws/2004/09/transfer/Create"], ["ResourceURI", "http://schemas.microsoft.com/wbem/wsman/1/windows/shell/cmd"], ["Body", "encrypted with the Kerberos session key"]], "raw": null, "hex": null}, {"f": "srv", "t": "admin", "m": "ShellId 7A3F...", "k": "res", "fields": [["ShellId", "7A3F..."], ["Body", "encrypted with the Kerberos session key"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Run and read", "tag": "command", "d": "<p>A Command request runs <code>hostname<\/code>. A Receive request gets the output, base64 encoded in the SOAP body.<\/p>", "f": [], "p": [{"f": "admin", "t": "srv", "m": "SOAP Command hostname", "k": "req", "fields": [["Action", "http://schemas.microsoft.com/wbem/wsman/1/windows/shell/Command"], ["Command", "hostname"], ["ShellId", "7A3F..."]], "raw": null, "hex": null}, {"f": "admin", "t": "srv", "m": "SOAP Receive", "k": "req", "fields": [["Action", "http://schemas.microsoft.com/wbem/wsman/1/windows/shell/Receive"], ["ShellId", "7A3F..."]], "raw": null, "hex": null}, {"f": "srv", "t": "admin", "m": "stdout WEB-02", "k": "data", "fields": [["Stream", "stdout"], ["Data", "WEB-02, base64 in the XML"], ["ExitCode", "0"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Clean up", "tag": "close", "d": "<p>A Delete request closes the shell.<\/p>", "f": [], "p": [{"f": "admin", "t": "srv", "m": "SOAP Delete shell", "k": "req", "fields": [["Action", "http://schemas.xmlsoap.org/ws/2004/09/transfer/Delete"], ["ShellId", "7A3F..."]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "WinRM over HTTPS uses port ____.", "a": ["5986"], "why": "HTTP is 5985."}, {"q": "Which login does WinRM prefer inside a Windows domain?", "opts": ["Basic over HTTP", "Kerberos through Negotiate", "No login"], "a": 1, "why": "Kerberos also protects the message body.", "type": "mcq"}], "refs": ["Microsoft. <a href=\"https://learn.microsoft.com/en-us/windows/win32/winrm/installation-and-configuration-for-windows-remote-management\" target=\"_blank\" rel=\"noopener\">Installation and configuration for WinRM<\/a>."]}, {"id": "wmi", "name": "WMI", "full": "Windows management over DCOM", "layer": 7, "cat": "data", "title": "WMI, asking a Windows machine to run a process.", "port": "135, then a high port", "transport": "MSRPC and DCOM", "lede": "WMI lets administrators query and control Windows machines remotely. The classic way uses DCOM, which starts at the RPC endpoint mapper on port 135 and moves to a random high port.", "overview": "<p>The client asks the <b>endpoint mapper<\/b> on TCP 135 where the DCOM activation service lives. It gets a <b>dynamic port<\/b>, by default between 49152 and 65535. Then it authenticates with Kerberos or NTLM, connects to the WMI namespace <code>root\\cimv2<\/code>, and calls methods, such as <code>Win32_Process.Create<\/code>.<\/p>\n<p>Admins also use WMI through WinRM with CIM cmdlets, which is easier to firewall. Attackers use remote WMI to move between machines, so defenders log and alert on it.<\/p>", "nodes": {"admin": {"label": "Admin PC", "sub": "10.0.0.30", "icon": "laptop", "x": 0, "y": 1}, "epm": {"label": "Endpoint mapper", "sub": "port 135", "icon": "server", "x": 4, "y": 0}, "host": {"label": "Windows host", "sub": "ws-17 10.0.4.17", "icon": "server", "x": 6, "y": 2}}, "links": [["admin", "epm"], ["admin", "host"], ["epm", "host"]], "steps": [{"t": "Ask the endpoint mapper", "tag": "rpc", "d": "<p>The client connects to TCP 135 and asks where the DCOM remote activation interface listens.<\/p>", "f": [], "p": [{"f": "admin", "t": "epm", "m": "EPM Map (remote activation)", "k": "req", "fields": [["Version", "5.0"], ["Packet type", "0 request"], ["Call ID", "1"], ["Interface", "ISystemActivator, remote activation"], ["Target", "WMI on ws-17"]], "raw": null, "hex": null}, {"f": "epm", "t": "admin", "m": "port 49712", "k": "res", "fields": [["Version", "5.0"], ["Packet type", "2 response"], ["Call ID", "1"], ["Binding", "ncacn_ip_tcp 10.0.4.17 port 49712"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Bind with authentication", "tag": "auth", "d": "<p>The client connects to port 49712 and binds to the interface with Kerberos or NTLM.<\/p>", "f": [], "p": [{"f": "admin", "t": "host", "m": "RPC Bind (Kerberos)", "k": "sec", "fields": [["Version", "5.0"], ["Packet type", "11 bind"], ["Call ID", "2"], ["Auth", "Kerberos, packet privacy"], ["Interface", "IWbemLevel1Login"]], "raw": null, "hex": null}, {"f": "host", "t": "admin", "m": "Bind Ack", "k": "sec", "fields": [["Version", "5.0"], ["Packet type", "12 bind_ack"], ["Call ID", "2"], ["Result", "acceptance"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Log in to the namespace", "tag": "wmi", "d": "<p>The client activates the WMI service and logs in to <code>root\\cimv2<\/code>. It gets an IWbemServices interface.<\/p>", "f": [], "p": [{"f": "admin", "t": "host", "m": "IWbemLevel1Login root\\cimv2", "k": "req", "fields": [["Version", "5.0"], ["Packet type", "0 request"], ["Call ID", "3"], ["Opnum", "6 NTLMLogin"], ["Namespace", "//./root/cimv2"]], "raw": null, "hex": null}, {"f": "host", "t": "admin", "m": "IWbemServices", "k": "res", "fields": [["Version", "5.0"], ["Packet type", "2 response"], ["Call ID", "3"], ["Returns", "IWbemServices interface pointer"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Run a method", "tag": "wmi", "d": "<p>ExecMethod on Win32_Process.Create with a command line starts a process. The reply has the new process id and a return value of 0.<\/p>", "f": [], "p": [{"f": "admin", "t": "host", "m": "ExecMethod Win32_Process.Create", "k": "req", "fields": [["Version", "5.0"], ["Packet type", "0 request"], ["Call ID", "4"], ["Method", "Win32_Process.Create"], ["CommandLine", "cmd.exe /c whoami"], ["Note", "encrypted with packet privacy"]], "raw": null, "hex": null}, {"f": "host", "t": "admin", "m": "ProcessId 6120, ReturnValue 0", "k": "res", "fields": [["Version", "5.0"], ["Packet type", "2 response"], ["Call ID", "4"], ["ProcessId", "6120"], ["ReturnValue", "0"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "DCOM based WMI starts at the RPC endpoint mapper on TCP port ____.", "a": ["135"], "why": "Then it moves to a dynamic high port."}, {"q": "Why do defenders watch remote Win32_Process.Create calls?", "opts": ["They are slow", "Attackers use remote WMI to run commands on other machines", "They break printing"], "a": 1, "why": "It is a common lateral movement method.", "type": "mcq"}], "refs": ["Microsoft. <a href=\"https://learn.microsoft.com/en-us/windows/win32/wmisdk/connecting-to-wmi-on-a-remote-computer\" target=\"_blank\" rel=\"noopener\">Connecting to WMI on a remote computer<\/a>."]}, {"id": "ipmi", "name": "IPMI", "full": "Server management controllers", "layer": 7, "cat": "data", "title": "IPMI, controlling a server even when it is off.", "port": "623", "transport": "UDP", "lede": "Servers have a small management computer, the BMC, that can power cycle the machine and show its console. IPMI talks to it. Its login has a known weakness that defenders must plan around.", "overview": "<p><b>IPMI 2.0<\/b> uses RMCP+ on UDP 623. The <b>RAKP<\/b> login exchange has a design weakness. In RAKP message 2, the BMC sends an HMAC computed with the user password before the client has proved anything. Anyone who can reach port 623 and knows a user name can collect it and try password guesses offline.<\/p>\n<div class=\"plain warn\"><span class=\"k\">Careful<\/span><p>Keep BMCs on a separate management network, use long unique passwords, disable cipher suite 0, and prefer the newer Redfish API over HTTPS.<\/p><\/div>", "nodes": {"admin": {"label": "Admin tool", "sub": "10.99.0.5", "icon": "laptop", "x": 0, "y": 1}, "bmc": {"label": "BMC", "sub": "10.99.1.21", "icon": "server", "x": 6, "y": 1}, "host": {"label": "Server", "sub": "powered by BMC", "icon": "server", "x": 6, "y": 3}}, "links": [["admin", "bmc"], ["bmc", "host"]], "steps": [{"t": "Ask for capabilities", "tag": "hello", "d": "<p>The tool asks which authentication types this channel supports.<\/p>", "f": [], "p": [{"f": "admin", "t": "bmc", "m": "Get Channel Auth Capabilities", "k": "req", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["Auth type", "0x00 none"], ["NetFn", "0x06 App"], ["Command", "0x38 Get Channel Auth Capabilities"], ["Channel", "0x8e"]], "raw": null, "hex": null}, {"f": "bmc", "t": "admin", "m": "supports IPMI 2.0 RMCP+", "k": "res", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["NetFn", "0x07 App response"], ["Completion code", "0x00"], ["Auth support", "0x80 IPMI 2.0 extended"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Open a session", "tag": "session", "d": "<p>The tool proposes cipher suites and opens an RMCP+ session.<\/p>", "f": [], "p": [{"f": "admin", "t": "bmc", "m": "Open Session Request", "k": "req", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["Payload type", "0x10 RMCP+ Open Session Request"], ["Tag", "0x00"], ["Auth algorithm", "1 RAKP-HMAC-SHA1"]], "raw": null, "hex": null}, {"f": "bmc", "t": "admin", "m": "Open Session Response", "k": "res", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["Payload type", "0x11 RMCP+ Open Session Response"], ["Status", "0x00"], ["Managed session ID", "0x02000300"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "RAKP 1 and 2", "tag": "rakp", "d": "<p>The tool sends a random number and the user name, admin. The BMC answers with its own random number and an HMAC keyed with the password. This is the value an attacker could collect.<\/p>", "f": [], "p": [{"f": "admin", "t": "bmc", "m": "RAKP 1 (user admin)", "k": "sec", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["Payload type", "0x12 RAKP 1"], ["Console random", "16 bytes"], ["User name", "admin"]], "raw": null, "hex": null}, {"f": "bmc", "t": "admin", "m": "RAKP 2 (HMAC with password)", "k": "bad", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["Payload type", "0x13 RAKP 2"], ["BMC random", "16 bytes"], ["Key exchange auth code", "HMAC-SHA1 keyed with the password, can be cracked offline"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "RAKP 3 and 4", "tag": "rakp", "d": "<p>The tool proves it knows the password with its own HMAC. The BMC confirms. The session is ready.<\/p>", "f": [], "p": [{"f": "admin", "t": "bmc", "m": "RAKP 3", "k": "sec", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["Payload type", "0x14 RAKP 3"], ["Key exchange auth code", "HMAC-SHA1 from the console"]], "raw": null, "hex": null}, {"f": "bmc", "t": "admin", "m": "RAKP 4", "k": "sec", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["Payload type", "0x15 RAKP 4"], ["Integrity check", "HMAC, session is ready"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Run a command", "tag": "control", "d": "<p>The tool asks for the chassis status, then sends a power cycle.<\/p>", "f": [], "p": [{"f": "admin", "t": "bmc", "m": "Get Chassis Status", "k": "req", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["NetFn", "0x00 Chassis"], ["Command", "0x01 Get Chassis Status"]], "raw": null, "hex": null}, {"f": "bmc", "t": "admin", "m": "power on", "k": "res", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["NetFn", "0x01 Chassis response"], ["Completion code", "0x00"], ["Power state", "0x01 on"]], "raw": null, "hex": null}, {"f": "admin", "t": "bmc", "m": "Chassis Control power cycle", "k": "req", "fields": [["RMCP version", "0x06"], ["RMCP class", "0x07 IPMI"], ["NetFn", "0x00 Chassis"], ["Command", "0x02 Chassis Control"], ["Data", "0x02 power cycle"]], "raw": null, "hex": null}, {"f": "bmc", "t": "host", "m": "power cycle", "k": "ctl", "fields": [["Action", "power cycle"], ["Effect", "the server turns off and on"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}], "quiz": [{"type": "fill", "q": "IPMI over LAN uses UDP port ____.", "a": ["623"], "why": "Keep it on an isolated management network."}, {"q": "Why is RAKP message 2 a risk?", "opts": ["It is slow", "It contains an HMAC keyed with the password, sent before the client proves anything, so it can be cracked offline", "It turns the server off"], "a": 1, "why": "Long unique passwords and network isolation reduce the risk.", "type": "mcq"}], "refs": ["Rapid7. <a href=\"https://www.rapid7.com/blog/post/2013/07/02/a-penetration-testers-guide-to-ipmi/\" target=\"_blank\" rel=\"noopener\">A penetration tester&#x27;s guide to IPMI and BMCs<\/a>.", "DMTF. <a href=\"https://www.dmtf.org/standards/redfish\" target=\"_blank\" rel=\"noopener\">Redfish<\/a>."]}, {"id": "r-services", "name": "r-services", "full": "rlogin, rsh and rexec", "layer": 7, "cat": "data", "title": "r-services, the old trust by address.", "port": "512, 513, 514", "transport": "TCP", "lede": "Before SSH, Unix machines used rlogin and rsh. They trusted other hosts by IP address and user name, with no password and no encryption. Watch why that is unsafe.", "overview": "<p><b>rexec<\/b> uses port 512, <b>rlogin<\/b> 513 and <b>rsh<\/b> 514. The files <code>/etc/hosts.equiv<\/code> and <code>~/.rhosts<\/code> list trusted hosts and users. A client from a trusted host connects from a <b>privileged source port<\/b>, below 1024, which was supposed to prove it ran as root. The server then logs the user in without a password.<\/p>\n<p>Anyone who controls a trusted host, or can fake its address, gets in. Everything is plain text. Replace r-services with SSH and remove <code>.rhosts<\/code> files.<\/p>", "nodes": {"cli": {"label": "Trusted host", "sub": "build-1 10.0.0.12", "icon": "terminal", "x": 0, "y": 1}, "srv": {"label": "Unix server", "sub": "db-1 10.0.0.20", "icon": "terminal", "x": 6, "y": 1}, "eve": {"label": "Attacker", "sub": "fakes 10.0.0.12", "icon": "user", "x": 3, "y": 3}}, "links": [["cli", "srv"], ["eve", "srv"]], "steps": [{"t": "Connect from a low port", "tag": "connect", "d": "<p><code>rlogin db-1<\/code> connects to port 513 from source port 1022, a privileged port.<\/p>", "f": [], "p": [{"f": "cli", "t": "srv", "m": "TCP SYN from :1022 to :513", "k": "ctl", "fields": [["Src port", "1022"], ["Dst port", "513"], ["Flags", "SYN"], ["Seq", "4400"], ["Window", "64240"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Send the user names", "tag": "login", "d": "<p>The client sends the local user, the remote user and the terminal type, separated by zero bytes.<\/p>", "f": [], "p": [{"f": "cli", "t": "srv", "m": "\\0asha\\0asha\\0xterm/38400\\0", "k": "req", "fields": [], "raw": "\u0000asha\u0000asha\u0000xterm/38400\u0000", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Trust check, no password", "tag": "trust", "d": "<p>The server finds <code>build-1 asha<\/code> in <code>~/.rhosts<\/code> and logs asha in. No password is asked.<\/p>", "f": [], "p": [{"f": "srv", "t": "cli", "m": "shell prompt (plain text)", "k": "res", "fields": [], "raw": "Last login: Mon Nov 23 09:10 from build-1\r\nasha@db-1:~$ ", "hex": null}], "on": [], "good": "", "bad": []}, {"t": "Why it fails", "tag": "risk", "d": "<p>An attacker who controls the trusted host, or can fake its address on the network, gets the same access. Every keystroke is plain text too.<\/p>", "f": [], "p": [{"f": "eve", "t": "srv", "m": "rlogin as asha from fake 10.0.0.12", "k": "bad", "fields": [["Src IP", "10.0.0.12 forged"], ["Src port", "1023"], ["Dst port", "513"], ["Trust", ".rhosts trusts build-1, so no password"]], "raw": null, "hex": null}], "on": [], "good": "", "bad": ["eve"]}], "quiz": [{"type": "fill", "q": "rlogin uses TCP port ____.", "a": ["513"], "why": "rexec 512, rlogin 513, rsh 514."}, {"q": "What replaced the r-services?", "opts": ["Telnet", "SSH with keys", "FTP"], "a": 1, "why": "SSH gives encryption and real authentication.", "type": "mcq"}], "refs": ["IETF. <a href=\"https://www.rfc-editor.org/rfc/rfc1282\" target=\"_blank\" rel=\"noopener\">RFC 1282, BSD rlogin<\/a>."]}];window.PCATS={"core": "Core", "app": "Application", "security": "Security", "data": "Data and admin"};